/**
 * Multi-Entity / Multi-Company Service
 * Manage companies and user-company associations.
 */

import { sql, withTransaction } from '@/lib/neon';
import { log } from '@/lib/logger';

// ── Types ────────────────────────────────────────────────────────────────────

export interface Company {
  id: string;
  name: string;
  tradingName: string | null;
  registrationNumber: string | null;
  vatNumber: string | null;
  taxNumber: string | null;
  addressLine1: string | null;
  addressLine2: string | null;
  city: string | null;
  province: string | null;
  postalCode: string | null;
  country: string;
  phone: string | null;
  email: string | null;
  website: string | null;
  logoUrl: string | null;
  logoData: string | null;
  bankName: string | null;
  bankAccountNumber: string | null;
  bankBranchCode: string | null;
  bankAccountType: string;
  financialYearStart: number;
  vatPeriod: string;
  vatPeriodAlignment: 'odd' | 'even';
  defaultCurrency: string;
  isActive: boolean;
  createdAt: string;
  // Lockdown
  lockdownEnabled: boolean;
  lockdownDate: string | null;
  // VAT system
  vatSystemType: string;
  // Entity & statutory
  entityType: string;
  registeredName: string | null;
  taxOffice: string | null;
  contactName: string | null;
  fax: string | null;
  mobile: string | null;
  // Physical address
  physicalAddressLine1: string | null;
  physicalAddressLine2: string | null;
  physicalCity: string | null;
  physicalProvince: string | null;
  physicalPostalCode: string | null;
  // Tax practitioner
  taxPractitionerRegNumber: string | null;
  taxPractitionerName: string | null;
  // SARS contact
  sarsContactFirstName: string | null;
  sarsContactLastName: string | null;
  sarsContactCapacity: string | null;
  sarsContactNumber: string | null;
  sarsContactTelephone: string | null;
  // Branding
  logoPosition: string;
  logoOnEmails: boolean;
  logoOnPortal: boolean;
  // Regional
  roundingType: string;
  roundToNearest: number;
  qtyDecimalPlaces: number;
  valueDecimalPlaces: number;
  hoursDecimalPlaces: number;
  costPriceDecimalPlaces: number;
  sellingPriceDecimalPlaces: number;
  currencySymbol: string;
  dateFormat: string;
  // Email toggles
  emailUseForCommunication: boolean;
  emailAlwaysCc: boolean;
  emailUseServiceFrom: boolean;
  // Customer & Supplier settings
  warnDuplicateCustomerRef: boolean;
  warnDuplicateSupplierInv: boolean;
  displayInactiveCustomersProcessing: boolean;
  displayInactiveSuppliersProcessing: boolean;
  displayInactiveCustomersReports: boolean;
  displayInactiveSuppliersReports: boolean;
  useInclusiveProcessing: boolean;
  useAccountDefaultLineType: boolean;
  // Item settings
  warnItemQtyBelowZero: boolean;
  blockItemQtyBelowZero: boolean;
  warnItemCostZero: boolean;
  warnItemSellingBelowCost: boolean;
  displayInactiveItemsProcessing: boolean;
  displayInactiveItemsReports: boolean;
  salesOrdersReserveQty: boolean;
  displayInactiveBundles: boolean;
  // Ageing
  ageingMonthly: boolean;
  ageingBasedOn: string;
  // Org classification
  industry: string | null;
  businessStructure: string | null;
  // Social media
  socialFacebook: string | null;
  socialLinkedin: string | null;
  socialX: string | null;
}

export interface CompanyUser {
  companyId: string;
  companyName: string;
  role: string;
  isDefault: boolean;
}

// ── Company CRUD ─────────────────────────────────────────────────────────────

export async function listCompanies(): Promise<Company[]> {
  const rows = (await sql`SELECT * FROM companies WHERE is_active = true ORDER BY name`) as Record<string, unknown>[];
  return rows.map(mapCompany);
}

export async function getCompany(id: string): Promise<Company | null> {
  const rows = (await sql`SELECT * FROM companies WHERE id = ${id}::UUID`) as Record<string, unknown>[];
  return rows[0] ? mapCompany(rows[0]) : null;
}

export async function createCompany(input: {
  name: string;
  tradingName?: string;
  registrationNumber?: string;
  vatNumber?: string;
  taxNumber?: string;
  email?: string;
  phone?: string;
  website?: string;
  addressLine1?: string;
  addressLine2?: string;
  city?: string;
  province?: string;
  postalCode?: string;
  country?: string;
  logoData?: string;
  bankName?: string;
  bankAccountNumber?: string;
  bankBranchCode?: string;
  bankAccountType?: string;
  financialYearStart?: number;
  vatPeriod?: string;
  vatPeriodAlignment?: 'odd' | 'even';
  defaultCurrency?: string;
}, userId: string): Promise<Company> {
  const rows = (await sql`
    INSERT INTO companies (
      name, registered_name, trading_name, registration_number, vat_number, tax_number,
      email, phone, website,
      address_line1, address_line2, city, province, postal_code, country,
      logo_data,
      bank_name, bank_account_number, bank_branch_code, bank_account_type,
      financial_year_start, vat_period, vat_period_alignment, default_currency
    ) VALUES (
      ${input.name}, ${input.name}, ${input.tradingName || null}, ${input.registrationNumber || null},
      ${input.vatNumber || null}, ${input.taxNumber || null}, ${input.email || null}, ${input.phone || null},
      ${input.website || null},
      ${input.addressLine1 || null}, ${input.addressLine2 || null}, ${input.city || null},
      ${input.province || null}, ${input.postalCode || null}, ${input.country || 'South Africa'},
      ${input.logoData || null},
      ${input.bankName || null}, ${input.bankAccountNumber || null}, ${input.bankBranchCode || null},
      ${input.bankAccountType || 'current'},
      ${input.financialYearStart ?? 3}, ${input.vatPeriod || 'bi-monthly'}, ${input.vatPeriodAlignment || 'odd'}, ${input.defaultCurrency || 'ZAR'}
    ) RETURNING *
  `) as Record<string, unknown>[];

  // Auto-assign creator as owner
  await sql`
    INSERT INTO company_users (company_id, user_id, role, is_default)
    VALUES (${rows[0]!.id}::UUID, ${userId}, 'owner', false)
  `;

  log.info('Company created', { id: rows[0]!.id, name: input.name }, 'accounting');
  return mapCompany(rows[0]!);
}

export async function updateCompany(id: string, input: Partial<Record<string, unknown>>): Promise<Company> {
  const v = (key: string) => input[key] !== undefined ? (input[key] === '' ? null : input[key]) : undefined;

  const rows = (await sql`
    UPDATE companies SET
      name = COALESCE(${v('name') ?? null}, name),
      trading_name = COALESCE(${v('tradingName') ?? null}, trading_name),
      registration_number = COALESCE(${v('registrationNumber') ?? null}, registration_number),
      vat_number = COALESCE(${v('vatNumber') ?? null}, vat_number),
      tax_number = COALESCE(${v('taxNumber') ?? null}, tax_number),
      address_line1 = COALESCE(${v('addressLine1') ?? null}, address_line1),
      address_line2 = COALESCE(${v('addressLine2') ?? null}, address_line2),
      city = COALESCE(${v('city') ?? null}, city),
      province = COALESCE(${v('province') ?? null}, province),
      postal_code = COALESCE(${v('postalCode') ?? null}, postal_code),
      country = COALESCE(${v('country') ?? null}, country),
      phone = COALESCE(${v('phone') ?? null}, phone),
      email = COALESCE(${v('email') ?? null}, email),
      website = COALESCE(${v('website') ?? null}, website),
      logo_data = COALESCE(${v('logoData') ?? null}, logo_data),
      bank_name = COALESCE(${v('bankName') ?? null}, bank_name),
      bank_account_number = COALESCE(${v('bankAccountNumber') ?? null}, bank_account_number),
      bank_branch_code = COALESCE(${v('bankBranchCode') ?? null}, bank_branch_code),
      bank_account_type = COALESCE(${v('bankAccountType') ?? null}, bank_account_type),
      financial_year_start = COALESCE(${v('financialYearStart') ?? null}, financial_year_start),
      vat_period = COALESCE(${v('vatPeriod') ?? null}, vat_period),
      vat_period_alignment = COALESCE(${v('vatPeriodAlignment') ?? null}, vat_period_alignment),
      default_currency = COALESCE(${v('defaultCurrency') ?? null}, default_currency),
      lockdown_enabled = COALESCE(${v('lockdownEnabled') ?? null}, lockdown_enabled),
      lockdown_date = COALESCE(${v('lockdownDate') ?? null}::date, lockdown_date),
      vat_system_type = COALESCE(${v('vatSystemType') ?? null}, vat_system_type),
      entity_type = COALESCE(${v('entityType') ?? null}, entity_type),
      registered_name = COALESCE(${v('registeredName') ?? null}, registered_name),
      tax_office = COALESCE(${v('taxOffice') ?? null}, tax_office),
      contact_name = COALESCE(${v('contactName') ?? null}, contact_name),
      fax = COALESCE(${v('fax') ?? null}, fax),
      mobile = COALESCE(${v('mobile') ?? null}, mobile),
      physical_address_line1 = COALESCE(${v('physicalAddressLine1') ?? null}, physical_address_line1),
      physical_address_line2 = COALESCE(${v('physicalAddressLine2') ?? null}, physical_address_line2),
      physical_city = COALESCE(${v('physicalCity') ?? null}, physical_city),
      physical_province = COALESCE(${v('physicalProvince') ?? null}, physical_province),
      physical_postal_code = COALESCE(${v('physicalPostalCode') ?? null}, physical_postal_code),
      tax_practitioner_reg_number = COALESCE(${v('taxPractitionerRegNumber') ?? null}, tax_practitioner_reg_number),
      tax_practitioner_name = COALESCE(${v('taxPractitionerName') ?? null}, tax_practitioner_name),
      sars_contact_first_name = COALESCE(${v('sarsContactFirstName') ?? null}, sars_contact_first_name),
      sars_contact_last_name = COALESCE(${v('sarsContactLastName') ?? null}, sars_contact_last_name),
      sars_contact_capacity = COALESCE(${v('sarsContactCapacity') ?? null}, sars_contact_capacity),
      sars_contact_number = COALESCE(${v('sarsContactNumber') ?? null}, sars_contact_number),
      sars_contact_telephone = COALESCE(${v('sarsContactTelephone') ?? null}, sars_contact_telephone),
      logo_position = COALESCE(${v('logoPosition') ?? null}, logo_position),
      logo_on_emails = COALESCE(${v('logoOnEmails') ?? null}, logo_on_emails),
      logo_on_portal = COALESCE(${v('logoOnPortal') ?? null}, logo_on_portal),
      rounding_type = COALESCE(${v('roundingType') ?? null}, rounding_type),
      round_to_nearest = COALESCE(${v('roundToNearest') ?? null}, round_to_nearest),
      qty_decimal_places = COALESCE(${v('qtyDecimalPlaces') ?? null}, qty_decimal_places),
      value_decimal_places = COALESCE(${v('valueDecimalPlaces') ?? null}, value_decimal_places),
      hours_decimal_places = COALESCE(${v('hoursDecimalPlaces') ?? null}, hours_decimal_places),
      cost_price_decimal_places = COALESCE(${v('costPriceDecimalPlaces') ?? null}, cost_price_decimal_places),
      selling_price_decimal_places = COALESCE(${v('sellingPriceDecimalPlaces') ?? null}, selling_price_decimal_places),
      currency_symbol = COALESCE(${v('currencySymbol') ?? null}, currency_symbol),
      date_format = COALESCE(${v('dateFormat') ?? null}, date_format),
      email_use_for_communication = COALESCE(${v('emailUseForCommunication') ?? null}, email_use_for_communication),
      email_always_cc = COALESCE(${v('emailAlwaysCc') ?? null}, email_always_cc),
      email_use_service_from = COALESCE(${v('emailUseServiceFrom') ?? null}, email_use_service_from),
      warn_duplicate_customer_ref = COALESCE(${v('warnDuplicateCustomerRef') ?? null}, warn_duplicate_customer_ref),
      warn_duplicate_supplier_inv = COALESCE(${v('warnDuplicateSupplierInv') ?? null}, warn_duplicate_supplier_inv),
      display_inactive_customers_processing = COALESCE(${v('displayInactiveCustomersProcessing') ?? null}, display_inactive_customers_processing),
      display_inactive_suppliers_processing = COALESCE(${v('displayInactiveSuppliersProcessing') ?? null}, display_inactive_suppliers_processing),
      display_inactive_customers_reports = COALESCE(${v('displayInactiveCustomersReports') ?? null}, display_inactive_customers_reports),
      display_inactive_suppliers_reports = COALESCE(${v('displayInactiveSuppliersReports') ?? null}, display_inactive_suppliers_reports),
      use_inclusive_processing = COALESCE(${v('useInclusiveProcessing') ?? null}, use_inclusive_processing),
      use_account_default_line_type = COALESCE(${v('useAccountDefaultLineType') ?? null}, use_account_default_line_type),
      warn_item_qty_below_zero = COALESCE(${v('warnItemQtyBelowZero') ?? null}, warn_item_qty_below_zero),
      block_item_qty_below_zero = COALESCE(${v('blockItemQtyBelowZero') ?? null}, block_item_qty_below_zero),
      warn_item_cost_zero = COALESCE(${v('warnItemCostZero') ?? null}, warn_item_cost_zero),
      warn_item_selling_below_cost = COALESCE(${v('warnItemSellingBelowCost') ?? null}, warn_item_selling_below_cost),
      display_inactive_items_processing = COALESCE(${v('displayInactiveItemsProcessing') ?? null}, display_inactive_items_processing),
      display_inactive_items_reports = COALESCE(${v('displayInactiveItemsReports') ?? null}, display_inactive_items_reports),
      sales_orders_reserve_qty = COALESCE(${v('salesOrdersReserveQty') ?? null}, sales_orders_reserve_qty),
      display_inactive_bundles = COALESCE(${v('displayInactiveBundles') ?? null}, display_inactive_bundles),
      ageing_monthly = COALESCE(${v('ageingMonthly') ?? null}, ageing_monthly),
      ageing_based_on = COALESCE(${v('ageingBasedOn') ?? null}, ageing_based_on),
      industry = COALESCE(${v('industry') ?? null}, industry),
      business_structure = COALESCE(${v('businessStructure') ?? null}, business_structure),
      social_facebook = COALESCE(${v('socialFacebook') ?? null}, social_facebook),
      social_linkedin = COALESCE(${v('socialLinkedin') ?? null}, social_linkedin),
      social_x = COALESCE(${v('socialX') ?? null}, social_x),
      updated_at = NOW()
    WHERE id = ${id}::UUID RETURNING *
  `) as Record<string, unknown>[];
  if (!rows[0]) throw new Error(`Company ${id} not found`);
  return mapCompany(rows[0]);
}

// ── User-Company ─────────────────────────────────────────────────────────────

export async function getUserCompanies(userId: string): Promise<CompanyUser[]> {
  const rows = (await sql`
    SELECT cu.company_id, c.name AS company_name, cu.role, cu.is_default
    FROM company_users cu
    JOIN companies c ON c.id = cu.company_id
    WHERE cu.user_id = ${userId} AND c.is_active = true
    ORDER BY cu.is_default DESC, c.name ASC
  `) as Record<string, unknown>[];
  return rows.map((r: Record<string, unknown>) => ({
    companyId: String(r.company_id),
    companyName: String(r.company_name),
    role: String(r.role),
    isDefault: Boolean(r.is_default),
  }));
}

export async function setDefaultCompany(userId: string, companyId: string): Promise<void> {
  await withTransaction(async (tx) => {
    await tx`UPDATE company_users SET is_default = false WHERE user_id = ${userId}`;
    await tx`UPDATE company_users SET is_default = true WHERE user_id = ${userId} AND company_id = ${companyId}::UUID`;
  });
}

// ── Mapper ───────────────────────────────────────────────────────────────────

function mapCompany(r: Record<string, unknown>): Company {
  const str = (v: unknown): string => (v != null ? String(v) : '');
  const strN = (v: unknown): string | null => (v != null ? String(v) : null);
  const bool = (v: unknown, def: boolean): boolean => (v != null ? Boolean(v) : def);
  const num = (v: unknown, def: number): number => (v != null ? Number(v) : def);
  return {
    id: str(r.id),
    name: str(r.name),
    tradingName: strN(r.trading_name),
    registrationNumber: strN(r.registration_number),
    vatNumber: strN(r.vat_number),
    taxNumber: strN(r.tax_number),
    addressLine1: strN(r.address_line1),
    addressLine2: strN(r.address_line2),
    city: strN(r.city),
    province: strN(r.province),
    postalCode: strN(r.postal_code),
    country: str(r.country),
    phone: strN(r.phone),
    email: strN(r.email),
    website: strN(r.website),
    logoUrl: strN(r.logo_url),
    logoData: strN(r.logo_data),
    bankName: strN(r.bank_name),
    bankAccountNumber: strN(r.bank_account_number),
    bankBranchCode: strN(r.bank_branch_code),
    bankAccountType: str(r.bank_account_type),
    financialYearStart: num(r.financial_year_start, 3),
    vatPeriod: str(r.vat_period),
    vatPeriodAlignment: (r.vat_period_alignment != null ? String(r.vat_period_alignment) : 'odd') as 'odd' | 'even',
    defaultCurrency: str(r.default_currency),
    isActive: bool(r.is_active, true),
    createdAt: str(r.created_at),
    // Lockdown
    lockdownEnabled: bool(r.lockdown_enabled, false),
    lockdownDate: r.lockdown_date != null ? new Date(r.lockdown_date as string | number | Date).toISOString().split('T')[0]! : null,
    // VAT system
    vatSystemType: r.vat_system_type != null ? String(r.vat_system_type) : 'invoice',
    // Entity & statutory
    entityType: r.entity_type != null ? String(r.entity_type) : 'company',
    registeredName: strN(r.registered_name),
    taxOffice: strN(r.tax_office),
    contactName: strN(r.contact_name),
    fax: strN(r.fax),
    mobile: strN(r.mobile),
    // Physical address
    physicalAddressLine1: strN(r.physical_address_line1),
    physicalAddressLine2: strN(r.physical_address_line2),
    physicalCity: strN(r.physical_city),
    physicalProvince: strN(r.physical_province),
    physicalPostalCode: strN(r.physical_postal_code),
    // Tax practitioner
    taxPractitionerRegNumber: strN(r.tax_practitioner_reg_number),
    taxPractitionerName: strN(r.tax_practitioner_name),
    // SARS contact
    sarsContactFirstName: strN(r.sars_contact_first_name),
    sarsContactLastName: strN(r.sars_contact_last_name),
    sarsContactCapacity: strN(r.sars_contact_capacity),
    sarsContactNumber: strN(r.sars_contact_number),
    sarsContactTelephone: strN(r.sars_contact_telephone),
    // Branding
    logoPosition: r.logo_position != null ? String(r.logo_position) : 'top-left',
    logoOnEmails: bool(r.logo_on_emails, true),
    logoOnPortal: bool(r.logo_on_portal, true),
    // Regional
    roundingType: r.rounding_type != null ? String(r.rounding_type) : 'none',
    roundToNearest: parseFloat(r.round_to_nearest != null ? String(r.round_to_nearest) : '0'),
    qtyDecimalPlaces: num(r.qty_decimal_places, 2),
    valueDecimalPlaces: num(r.value_decimal_places, 2),
    hoursDecimalPlaces: num(r.hours_decimal_places, 2),
    costPriceDecimalPlaces: num(r.cost_price_decimal_places, 2),
    sellingPriceDecimalPlaces: num(r.selling_price_decimal_places, 2),
    currencySymbol: r.currency_symbol != null ? String(r.currency_symbol) : 'R',
    dateFormat: r.date_format != null ? String(r.date_format) : 'dd/mm/yyyy',
    // Email toggles
    emailUseForCommunication: bool(r.email_use_for_communication, true),
    emailAlwaysCc: bool(r.email_always_cc, false),
    emailUseServiceFrom: bool(r.email_use_service_from, false),
    // Customer & Supplier
    warnDuplicateCustomerRef: bool(r.warn_duplicate_customer_ref, true),
    warnDuplicateSupplierInv: bool(r.warn_duplicate_supplier_inv, true),
    displayInactiveCustomersProcessing: bool(r.display_inactive_customers_processing, false),
    displayInactiveSuppliersProcessing: bool(r.display_inactive_suppliers_processing, false),
    displayInactiveCustomersReports: bool(r.display_inactive_customers_reports, false),
    displayInactiveSuppliersReports: bool(r.display_inactive_suppliers_reports, false),
    useInclusiveProcessing: bool(r.use_inclusive_processing, true),
    useAccountDefaultLineType: bool(r.use_account_default_line_type, false),
    // Items
    warnItemQtyBelowZero: bool(r.warn_item_qty_below_zero, true),
    blockItemQtyBelowZero: bool(r.block_item_qty_below_zero, false),
    warnItemCostZero: bool(r.warn_item_cost_zero, false),
    warnItemSellingBelowCost: bool(r.warn_item_selling_below_cost, false),
    displayInactiveItemsProcessing: bool(r.display_inactive_items_processing, false),
    displayInactiveItemsReports: bool(r.display_inactive_items_reports, false),
    salesOrdersReserveQty: bool(r.sales_orders_reserve_qty, false),
    displayInactiveBundles: bool(r.display_inactive_bundles, false),
    // Ageing
    ageingMonthly: bool(r.ageing_monthly, true),
    ageingBasedOn: r.ageing_based_on != null ? String(r.ageing_based_on) : 'invoice_date',
    // Org classification
    industry: strN(r.industry),
    businessStructure: strN(r.business_structure),
    // Social media
    socialFacebook: strN(r.social_facebook),
    socialLinkedin: strN(r.social_linkedin),
    socialX: strN(r.social_x),
  };
}

// ── Document Numbers ──────────────────────────────────────────────────────────

export interface DocumentNumber {
  id: string;
  companyId: string;
  documentType: string;
  prefix: string;
  nextNumber: number;
  padding: number;
}

const DEFAULT_DOC_NUMBERS: { type: string; prefix: string }[] = [
  { type: 'quotation', prefix: 'QUO' },
  { type: 'sales_order', prefix: 'SO' },
  { type: 'customer_invoice', prefix: 'INV' },
  { type: 'credit_note', prefix: 'CRN' },
  { type: 'customer_receipt', prefix: 'RCP' },
  { type: 'customer_write_off', prefix: 'WRI' },
  { type: 'recurring_invoice', prefix: 'RINV' },
  { type: 'customer_adjustment', prefix: 'CADJ' },
  { type: 'purchase_order', prefix: 'PO' },
  { type: 'supplier_invoice', prefix: 'SIV' },
  { type: 'supplier_return', prefix: 'RTN' },
  { type: 'supplier_payment', prefix: 'PAY' },
  { type: 'supplier_adjustment', prefix: 'SADJ' },
  { type: 'delivery_note', prefix: 'DN' },
];

export async function getDocumentNumbers(companyId: string): Promise<DocumentNumber[]> {
  const rows = (await sql`
    SELECT * FROM company_document_numbers WHERE company_id = ${companyId}::UUID ORDER BY document_type
  `) as Record<string, unknown>[];
  return rows.map((r: Record<string, unknown>) => ({
    id: String(r.id), companyId: String(r.company_id), documentType: String(r.document_type),
    prefix: String(r.prefix), nextNumber: Number(r.next_number), padding: Number(r.padding),
  }));
}

export async function ensureDocumentNumbers(companyId: string): Promise<DocumentNumber[]> {
  for (const d of DEFAULT_DOC_NUMBERS) {
    await sql`
      INSERT INTO company_document_numbers (company_id, document_type, prefix, next_number, padding)
      VALUES (${companyId}::UUID, ${d.type}, ${d.prefix}, 1, 7)
      ON CONFLICT (company_id, document_type) DO NOTHING
    `;
  }
  return getDocumentNumbers(companyId);
}

export async function updateDocumentNumber(companyId: string, documentType: string, prefix: string, nextNumber?: number): Promise<void> {
  if (nextNumber !== undefined) {
    await sql`
      UPDATE company_document_numbers SET prefix = ${prefix}, next_number = ${nextNumber}
      WHERE company_id = ${companyId}::UUID AND document_type = ${documentType}
    `;
  } else {
    await sql`
      UPDATE company_document_numbers SET prefix = ${prefix}
      WHERE company_id = ${companyId}::UUID AND document_type = ${documentType}
    `;
  }
}

// ── Company Messages ──────────────────────────────────────────────────────────

export interface CompanyMessage {
  messageType: string;
  message: string;
}

export async function getCompanyMessages(companyId: string): Promise<CompanyMessage[]> {
  const rows = (await sql`
    SELECT message_type, message FROM company_messages WHERE company_id = ${companyId}::UUID ORDER BY message_type
  `) as Record<string, unknown>[];
  return rows.map((r: Record<string, unknown>) => ({ messageType: String(r.message_type ?? ''), message: String(r.message ?? '') }));
}

export async function upsertCompanyMessage(companyId: string, messageType: string, message: string): Promise<void> {
  await sql`
    INSERT INTO company_messages (company_id, message_type, message)
    VALUES (${companyId}::UUID, ${messageType}, ${message})
    ON CONFLICT (company_id, message_type) DO UPDATE SET message = ${message}, updated_at = NOW()
  `;
}

export async function upsertCompanyMessages(companyId: string, messages: CompanyMessage[]): Promise<void> {
  for (const m of messages) {
    await upsertCompanyMessage(companyId, m.messageType, m.message);
  }
}

/**
 * Payment Gateway Service — PayFast integration
 * Handles payment form generation, ITN validation, and transaction tracking.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import crypto from 'crypto';
type Row = Record<string, unknown>;


// ── Config ──────────────────────────────────────────────────────────────────

const PAYFAST_SANDBOX_URL = 'https://sandbox.payfast.co.za/eng/process';
const PAYFAST_LIVE_URL = 'https://www.payfast.co.za/eng/process';

// PayFast valid IP ranges (production)
const PAYFAST_IP_RANGES = [
  '197.97.145.144/28',
  '41.74.179.192/27',
  '196.12.62.128/27',
];

// Sandbox allows any IP, but we still check in production
const PAYFAST_SANDBOX_IPS = ['127.0.0.1', '::1'];

function getConfig() {
  return {
    merchantId: process.env.PAYFAST_MERCHANT_ID || '',
    merchantKey: process.env.PAYFAST_MERCHANT_KEY || '',
    passphrase: process.env.PAYFAST_PASSPHRASE || '',
    isSandbox: process.env.PAYFAST_SANDBOX === 'true',
  };
}

function getPayFastUrl(): string {
  return getConfig().isSandbox ? PAYFAST_SANDBOX_URL : PAYFAST_LIVE_URL;
}

// ── Signature Generation ────────────────────────────────────────────────────

function generateSignature(data: Record<string, string>, passphrase: string): string {
  // Sort keys alphabetically, exclude blank values and 'signature' key
  const sortedKeys = Object.keys(data)
    .filter(k => k !== 'signature' && data[k] !== '' && data[k] !== undefined && data[k] !== null)
    .sort();

  const queryString = sortedKeys
    .map(k => `${k}=${encodeURIComponent(data[k]!).replace(/%20/g, '+')}`)
    .join('&');

  const toHash = passphrase ? `${queryString}&passphrase=${encodeURIComponent(passphrase).replace(/%20/g, '+')}` : queryString;

  return crypto.createHash('md5').update(toHash).digest('hex');
}

// ── IP Validation ───────────────────────────────────────────────────────────

function ipInCidr(ip: string, cidr: string): boolean {
  const [range, bitsStr] = cidr.split('/');
  if (!range || !bitsStr) return false;
  const bits = parseInt(bitsStr, 10);

  const ipParts = ip.split('.').map(Number);
  const rangeParts = range.split('.').map(Number);

  const ipNum = ((ipParts[0]! << 24) | (ipParts[1]! << 16) | (ipParts[2]! << 8) | ipParts[3]!) >>> 0;
  const rangeNum = ((rangeParts[0]! << 24) | (rangeParts[1]! << 16) | (rangeParts[2]! << 8) | rangeParts[3]!) >>> 0;
  const mask = (~0 << (32 - bits)) >>> 0;

  return (ipNum & mask) === (rangeNum & mask);
}

function isPayFastIp(ip: string): boolean {
  const config = getConfig();
  if (config.isSandbox) return true; // Sandbox mode: accept any IP

  // Strip IPv6 prefix
  const cleanIp = ip.startsWith('::ffff:') ? ip.slice(7) : ip;

  for (const cidr of PAYFAST_IP_RANGES) {
    if (ipInCidr(cleanIp, cidr)) return true;
  }
  return PAYFAST_SANDBOX_IPS.includes(cleanIp);
}

// ── Public Functions ────────────────────────────────────────────────────────

export interface PayFastFormData {
  paymentUrl: string;
  fields: Record<string, string>;
  transactionId: string;
}

/**
 * Generate PayFast payment form data for an invoice.
 */
export async function generatePayFastForm(
  companyId: string,
  invoiceId: string,
  returnUrl: string,
  cancelUrl: string,
  notifyUrl: string,
): Promise<PayFastFormData> {
  const config = getConfig();
  if (!config.merchantId || !config.merchantKey) {
    throw new Error('PayFast merchant credentials not configured');
  }

  // Look up invoice details
  const invoices = (await sql`
    SELECT ci.id, ci.invoice_number, ci.total_amount, ci.amount_paid,
           ci.client_name, ci.status,
           c.email AS client_email
    FROM customer_invoices ci
    LEFT JOIN customers c ON c.id = ci.client_id
    WHERE ci.id = ${invoiceId}::UUID AND ci.company_id = ${companyId}::UUID
  `) as Row[];

  if (!invoices[0]) throw new Error('Invoice not found');

  const invRow = invoices[0];
  const inv = {
    invoice_number: String(invRow.invoice_number ?? ''),
    total_amount: Number(invRow.total_amount),
    amount_paid: Number(invRow.amount_paid ?? 0),
    client_name: invRow.client_name != null ? String(invRow.client_name) : null,
    client_email: invRow.client_email != null ? String(invRow.client_email) : null,
  };
  const balance = inv.total_amount - inv.amount_paid;
  if (balance <= 0) throw new Error('Invoice is already fully paid');

  // Create payment transaction record
  const txRows = (await sql`
    INSERT INTO payment_transactions (company_id, invoice_id, gateway, amount, currency, customer_email, customer_name, status)
    VALUES (${companyId}::UUID, ${invoiceId}::UUID, 'payfast', ${balance}, 'ZAR', ${inv.client_email || ''}, ${inv.client_name || ''}, 'pending')
    RETURNING id
  `) as Row[];

  const transactionId = String(txRows[0]!.id);

  // Build PayFast form fields
  const fields: Record<string, string> = {
    merchant_id: config.merchantId,
    merchant_key: config.merchantKey,
    return_url: returnUrl,
    cancel_url: cancelUrl,
    notify_url: notifyUrl,
    m_payment_id: transactionId,
    amount: balance.toFixed(2),
    item_name: `Invoice ${inv.invoice_number}`.slice(0, 100),
    item_description: `Payment for invoice ${inv.invoice_number}`.slice(0, 255),
  };

  // Add customer email if available
  if (inv.client_email) {
    fields.email_address = inv.client_email;
  }

  // Add customer name if available
  if (inv.client_name) {
    const nameParts = inv.client_name.split(' ');
    fields.name_first = (nameParts[0] || '').slice(0, 100);
    fields.name_last = (nameParts.slice(1).join(' ') || '').slice(0, 100);
  }

  // Generate signature
  fields.signature = generateSignature(fields, config.passphrase);

  log.info('PayFast form generated', { transactionId, invoiceId, amount: balance }, 'PaymentGateway');

  return {
    paymentUrl: getPayFastUrl(),
    fields,
    transactionId,
  };
}

/**
 * Handle PayFast ITN (Instant Transaction Notification).
 * Validates the notification and updates payment status.
 */
export async function handleITN(
  body: Record<string, string>,
  sourceIp: string,
): Promise<{ valid: boolean; transactionId: string | null }> {
  const config = getConfig();

  // 1. Verify source IP
  if (!isPayFastIp(sourceIp)) {
    log.error('ITN rejected: invalid source IP', { sourceIp }, 'PaymentGateway');
    return { valid: false, transactionId: null };
  }

  // 2. Verify signature
  const receivedSignature = body.signature;
  if (!receivedSignature) {
    log.error('ITN rejected: no signature', {}, 'PaymentGateway');
    return { valid: false, transactionId: null };
  }

  const dataForSig = { ...body };
  delete dataForSig.signature;
  const expectedSignature = generateSignature(dataForSig, config.passphrase);

  if (receivedSignature !== expectedSignature) {
    log.error('ITN rejected: signature mismatch', { received: receivedSignature, expected: expectedSignature }, 'PaymentGateway');
    return { valid: false, transactionId: null };
  }

  const transactionId = body.m_payment_id || null;
  if (!transactionId) {
    log.error('ITN rejected: no m_payment_id', {}, 'PaymentGateway');
    return { valid: false, transactionId: null };
  }

  // 3. Look up the transaction
  const txRows = (await sql`
    SELECT id, company_id, invoice_id, amount, status
    FROM payment_transactions WHERE id = ${transactionId}::UUID
  `) as Row[];

  if (!txRows[0]) {
    log.error('ITN rejected: transaction not found', { transactionId }, 'PaymentGateway');
    return { valid: false, transactionId };
  }

  const tx = txRows[0];

  // 4. Verify amount matches
  const itnAmount = parseFloat(body.amount_gross || '0');
  const expectedAmount = Number(tx.amount);
  if (Math.abs(itnAmount - expectedAmount) > 0.01) {
    log.error('ITN rejected: amount mismatch', { expected: expectedAmount, received: itnAmount }, 'PaymentGateway');
    await sql`
      UPDATE payment_transactions SET status = 'failed', error_message = 'Amount mismatch', updated_at = NOW()
      WHERE id = ${transactionId}::UUID
    `;
    return { valid: false, transactionId };
  }

  // 5. Map PayFast status to our status
  const pfStatus = (body.payment_status || '').toUpperCase();
  let newStatus: string;
  switch (pfStatus) {
    case 'COMPLETE':
      newStatus = 'completed';
      break;
    case 'FAILED':
      newStatus = 'failed';
      break;
    case 'PENDING':
      newStatus = 'processing';
      break;
    case 'CANCELLED':
      newStatus = 'cancelled';
      break;
    default:
      newStatus = 'processing';
  }

  // 6. Update transaction
  await sql`
    UPDATE payment_transactions
    SET status = ${newStatus},
        gateway_ref = ${body.pf_payment_id || ''},
        payment_method = ${body.payment_method || ''},
        paid_at = ${newStatus === 'completed' ? new Date().toISOString() : null},
        metadata = ${JSON.stringify(body)}::JSONB,
        updated_at = NOW()
    WHERE id = ${transactionId}::UUID
  `;

  // 7. If completed, update the invoice
  if (newStatus === 'completed' && tx.invoice_id) {
    await sql`
      UPDATE customer_invoices
      SET amount_paid = COALESCE(amount_paid, 0) + ${itnAmount},
          status = CASE
            WHEN COALESCE(amount_paid, 0) + ${itnAmount} >= total_amount THEN 'paid'
            ELSE 'partially_paid'
          END,
          updated_at = NOW()
      WHERE id = ${tx.invoice_id}::UUID AND company_id = ${tx.company_id}::UUID
    `;

    log.info('Invoice payment recorded via PayFast', {
      transactionId, invoiceId: tx.invoice_id, amount: itnAmount, status: 'completed',
    }, 'PaymentGateway');
  }

  log.info('ITN processed', { transactionId, pfStatus, newStatus }, 'PaymentGateway');
  return { valid: true, transactionId };
}

/**
 * Get payment transaction details.
 */
export async function getPaymentStatus(companyId: string, transactionId: string) {
  const rows = (await sql`
    SELECT * FROM payment_transactions
    WHERE id = ${transactionId}::UUID AND company_id = ${companyId}::UUID
  `) as Row[];

  if (!rows[0]) return null;
  return mapTransaction(rows[0]);
}

/**
 * List all payment attempts for an invoice.
 */
export async function getInvoicePayments(companyId: string, invoiceId: string) {
  const rows = (await sql`
    SELECT * FROM payment_transactions
    WHERE invoice_id = ${invoiceId}::UUID AND company_id = ${companyId}::UUID
    ORDER BY created_at DESC
  `) as Row[];

  return rows.map(mapTransaction);
}

/**
 * Enable online payment for an invoice and generate a payment URL.
 */
export async function enableOnlinePayment(companyId: string, invoiceId: string): Promise<string> {
  const appUrl = process.env.NEXT_PUBLIC_APP_URL || 'http://localhost:3101';

  // Create a portal payment link token for public access
  const linkRows = (await sql`
    INSERT INTO portal_payment_links (invoice_id, client_id, amount)
    SELECT ci.id, ci.client_id, ci.total_amount - COALESCE(ci.amount_paid, 0)
    FROM customer_invoices ci
    WHERE ci.id = ${invoiceId}::UUID AND ci.company_id = ${companyId}::UUID
    RETURNING token
  `) as Row[];

  if (!linkRows[0]) throw new Error('Invoice not found or no balance due');

  const token = linkRows[0].token as string;
  const paymentUrl = `${appUrl}/portal/pay/${token}`;

  // Store the payment URL and enable online payments on the invoice
  await sql`
    UPDATE customer_invoices
    SET online_payment_enabled = true, payment_url = ${paymentUrl}, updated_at = NOW()
    WHERE id = ${invoiceId}::UUID AND company_id = ${companyId}::UUID
  `;

  log.info('Online payment enabled', { invoiceId, paymentUrl }, 'PaymentGateway');
  return paymentUrl;
}

// ── Mapper ──────────────────────────────────────────────────────────────────

interface PaymentTransaction {
  id: string;
  companyId: string;
  invoiceId: string | null;
  gateway: string;
  gatewayRef: string | null;
  amount: number;
  currency: string;
  status: string;
  customerEmail: string | null;
  customerName: string | null;
  paymentMethod: string | null;
  metadata: Record<string, unknown>;
  errorMessage: string | null;
  paidAt: string | null;
  createdAt: string;
  updatedAt: string;
}

function mapTransaction(r: Row): PaymentTransaction {
  return {
    id: String(r.id),
    companyId: String(r.company_id),
    invoiceId: r.invoice_id != null ? String(r.invoice_id) : null,
    gateway: String(r.gateway),
    gatewayRef: r.gateway_ref != null ? String(r.gateway_ref) : null,
    amount: Number(r.amount),
    currency: String(r.currency),
    status: String(r.status),
    customerEmail: r.customer_email != null ? String(r.customer_email) : null,
    customerName: r.customer_name != null ? String(r.customer_name) : null,
    paymentMethod: r.payment_method != null ? String(r.payment_method) : null,
    metadata: (r.metadata as Record<string, unknown>) || {},
    errorMessage: r.error_message != null ? String(r.error_message) : null,
    paidAt: r.paid_at != null ? String(r.paid_at) : null,
    createdAt: String(r.created_at),
    updatedAt: String(r.updated_at),
  };
}

/**
 * PRD-060: FibreFlow Accounting Module — Phase 2
 * Supplier Invoice Service
 */

import { sql, withTransaction } from '@/lib/neon';
import { log } from '@/lib/logger';
import { createJournalEntry, postJournalEntry } from './journalEntryService';
import { getSystemAccount } from './systemAccountResolver';
import { validateThreeWayMatch } from '../utils/threeWayMatch';
import type {
  SupplierInvoice,
  SupplierInvoiceItem,
  SupplierInvoiceCreateInput,
  SupplierInvoiceStatus,
  InvoiceMatchStatus,
} from '../types/ap.types';
import type { JournalLineInput, VatType } from '../types/gl.types';
type Row = Record<string, unknown>;


interface InvoiceFilters {
  status?: SupplierInvoiceStatus;
  supplierId?: string;
  matchStatus?: InvoiceMatchStatus;
  limit?: number;
  offset?: number;
}

export async function getSupplierInvoices(companyId: string, filters?: InvoiceFilters): Promise<{
  invoices: SupplierInvoice[];
  total: number;
}> {
  try {
    const limit = Math.min(filters?.limit || 50, 200);
    const offset = filters?.offset || 0;
    let rows: Row[];
    let countRows: Row[];

    // NOTE: purchase_orders table is not available in standalone accounting app.
    // po_number is returned as NULL; purchase_order_id column is kept for data integrity.
    if (filters?.status && filters?.supplierId) {
      rows = (await sql`
        SELECT si.*, s.name AS supplier_name, NULL::text AS po_number
        FROM supplier_invoices si
        LEFT JOIN suppliers s ON s.id = si.supplier_id
        WHERE si.company_id = ${companyId}::UUID AND si.deleted_at IS NULL
          AND si.status = ${filters.status} AND si.supplier_id = ${filters.supplierId}
        ORDER BY si.invoice_date DESC LIMIT ${limit} OFFSET ${offset}
      `) as Row[];
      countRows = (await sql`
        SELECT COUNT(*) AS cnt FROM supplier_invoices
        WHERE company_id = ${companyId}::UUID AND deleted_at IS NULL
          AND status = ${filters.status} AND supplier_id = ${filters.supplierId}
      `) as Row[];
    } else if (filters?.status) {
      rows = (await sql`
        SELECT si.*, s.name AS supplier_name, NULL::text AS po_number
        FROM supplier_invoices si
        LEFT JOIN suppliers s ON s.id = si.supplier_id
        WHERE si.company_id = ${companyId}::UUID AND si.deleted_at IS NULL
          AND si.status = ${filters.status}
        ORDER BY si.invoice_date DESC LIMIT ${limit} OFFSET ${offset}
      `) as Row[];
      countRows = (await sql`
        SELECT COUNT(*) AS cnt FROM supplier_invoices
        WHERE company_id = ${companyId}::UUID AND deleted_at IS NULL AND status = ${filters.status}
      `) as Row[];
    } else if (filters?.supplierId) {
      rows = (await sql`
        SELECT si.*, s.name AS supplier_name, NULL::text AS po_number
        FROM supplier_invoices si
        LEFT JOIN suppliers s ON s.id = si.supplier_id
        WHERE si.company_id = ${companyId}::UUID AND si.deleted_at IS NULL
          AND si.supplier_id = ${filters.supplierId}
        ORDER BY si.invoice_date DESC LIMIT ${limit} OFFSET ${offset}
      `) as Row[];
      countRows = (await sql`
        SELECT COUNT(*) AS cnt FROM supplier_invoices
        WHERE company_id = ${companyId}::UUID AND deleted_at IS NULL AND supplier_id = ${filters.supplierId}
      `) as Row[];
    } else {
      rows = (await sql`
        SELECT si.*, s.name AS supplier_name, NULL::text AS po_number
        FROM supplier_invoices si
        LEFT JOIN suppliers s ON s.id = si.supplier_id
        WHERE si.company_id = ${companyId}::UUID AND si.deleted_at IS NULL
        ORDER BY si.invoice_date DESC LIMIT ${limit} OFFSET ${offset}
      `) as Row[];
      countRows = (await sql`
        SELECT COUNT(*) AS cnt FROM supplier_invoices WHERE company_id = ${companyId}::UUID AND deleted_at IS NULL
      `) as Row[];
    }

    return { invoices: rows.map(mapInvoiceRow), total: Number(countRows[0]!.cnt) };
  } catch (err) {
    log.error('Failed to get supplier invoices', { error: err }, 'accounting');
    throw err;
  }
}

export async function getSupplierInvoiceById(companyId: string, 
  id: string
): Promise<(SupplierInvoice & { items: SupplierInvoiceItem[] }) | null> {
  try {
    const rows = (await sql`
      SELECT si.*, s.name AS supplier_name, NULL::text AS po_number
      FROM supplier_invoices si
      LEFT JOIN suppliers s ON s.id = si.supplier_id
      WHERE si.id = ${id} AND si.company_id = ${companyId}::UUID
    `) as Row[];
    if (rows.length === 0) return null;

    const itemRows = (await sql`
      SELECT sii.*, a.account_code, a.account_name
      FROM supplier_invoice_items sii
      LEFT JOIN gl_accounts a ON a.id = sii.gl_account_id
      WHERE sii.supplier_invoice_id = ${id}
      ORDER BY sii.created_at
    `) as Row[];

    return { ...mapInvoiceRow(rows[0]!), items: itemRows.map(mapItemRow) };
  } catch (err) {
    log.error('Failed to get supplier invoice', { id, error: err }, 'accounting');
    throw err;
  }
}

export async function createSupplierInvoice(companyId: string, 
  input: SupplierInvoiceCreateInput,
  userId: string
): Promise<SupplierInvoice> {
  try {
    const invoiceTaxRate = input.taxRate ?? 15;
    let subtotal = 0;
    let totalTax = 0;

    const computedItems = input.items.map(item => {
      const lineTotal = Math.round(item.quantity * item.unitPrice * 100) / 100;
      const itemTaxRate = item.taxRate ?? invoiceTaxRate;
      const itemTax = Math.round(lineTotal * itemTaxRate / 100 * 100) / 100;
      subtotal += lineTotal;
      totalTax += itemTax;
      return { ...item, lineTotal, taxAmount: itemTax, taxRate: itemTaxRate };
    });

    subtotal = Math.round(subtotal * 100) / 100;
    totalTax = Math.round(totalTax * 100) / 100;
    const totalAmount = subtotal + totalTax;

    const dueDate = input.dueDate || calculateDueDate(input.invoiceDate, input.paymentTerms);

    const invoiceRow = await withTransaction(async (tx) => {
      const rows = (await tx`
        INSERT INTO supplier_invoices (
          company_id, invoice_number, supplier_id, purchase_order_id, grn_id,
          invoice_date, due_date, subtotal, tax_rate, tax_amount,
          total_amount, payment_terms, reference, project_id,
          cost_center_id, notes, created_by
        ) VALUES (
          ${companyId}::UUID, ${input.invoiceNumber}, ${input.supplierId},
          ${input.purchaseOrderId || null}, ${input.grnId || null},
          ${input.invoiceDate}, ${dueDate || null},
          ${subtotal}, ${invoiceTaxRate}, ${totalTax}, ${totalAmount},
          ${input.paymentTerms || null}, ${input.reference || null},
          ${input.projectId || null}, ${input.costCenterId || null},
          ${input.notes || null}, ${userId}::UUID
        ) RETURNING *
      `) as Row[];

      const invoiceId = String(rows[0]!.id);

      for (const item of computedItems) {
        await tx`
          INSERT INTO supplier_invoice_items (
            supplier_invoice_id, po_item_id, description, quantity,
            unit_price, tax_rate, tax_amount, line_total,
            gl_account_id, project_id, cost_center_id, vat_classification
          ) VALUES (
            ${invoiceId}::UUID, ${item.poItemId || null}, ${item.description},
            ${item.quantity}, ${item.unitPrice}, ${item.taxRate},
            ${item.taxAmount}, ${item.lineTotal},
            ${item.glAccountId || null}, ${item.projectId || null},
            ${item.costCenterId || null},
            ${item.vatClassification || (item.taxRate > 0 ? 'standard' : 'zero_rated')}
          )
        `;
      }

      return rows[0] as Row;
    });

    log.info('Created supplier invoice', { invoiceId: String(invoiceRow.id), invoiceNumber: input.invoiceNumber }, 'accounting');
    return mapInvoiceRow(invoiceRow);
  } catch (err) {
    log.error('Failed to create supplier invoice', { error: err }, 'accounting');
    throw err;
  }
}

export async function approveSupplierInvoice(companyId: string, 
  id: string,
  userId: string
): Promise<SupplierInvoice> {
  try {
    const invoice = await getSupplierInvoiceById(companyId, id);
    if (!invoice) throw new Error(`Supplier invoice ${id} not found`);
    if (invoice.status !== 'draft' && invoice.status !== 'pending_approval') {
      throw new Error(`Cannot approve invoice with status: ${invoice.status}`);
    }

    // Auto-post GL entry: DR Expense + DR VAT Input, CR Accounts Payable
    const apAccount = await getSystemAccount('payable');
    const vatAccount = await getSystemAccount('vat_input');

    const defaultExpenseAccount = await getSystemAccount('default_expense');
    const lines: JournalLineInput[] = [];

    for (const item of invoice.items) {
      const glAccountId = item.glAccountId || defaultExpenseAccount.id;
      if (!glAccountId) throw new Error('No GL account for invoice item and no default expense account');
      lines.push({
        glAccountId,
        debit: item.lineTotal,
        credit: 0,
        description: item.description,
        projectId: item.projectId || invoice.projectId,
        costCenterId: item.costCenterId || invoice.costCenterId,
      });
    }

    if (invoice.taxAmount > 0) {
      lines.push({
        glAccountId: vatAccount.id,
        debit: invoice.taxAmount,
        credit: 0,
        description: `VAT on ${invoice.invoiceNumber}`,
        vatType: 'standard',
      });
    }

    lines.push({
      glAccountId: apAccount.id,
      debit: 0,
      credit: invoice.totalAmount,
      description: `AP: ${invoice.invoiceNumber}`,
    });

    const journalEntry = await createJournalEntry(companyId, {
      entryDate: invoice.invoiceDate,
      description: `Supplier invoice ${invoice.invoiceNumber}`,
      source: 'auto_supplier_invoice',
      sourceDocumentId: id,
      lines,
    }, userId);

    await postJournalEntry(companyId, journalEntry.id, userId);

    const updated = (await sql`
      UPDATE supplier_invoices
      SET status = 'approved', approved_by = ${userId}::UUID, approved_at = NOW(),
          gl_journal_entry_id = ${journalEntry.id}::UUID
      WHERE id = ${id} AND company_id = ${companyId}::UUID
      RETURNING *
    `) as Row[];

    log.info('Approved supplier invoice', { id, journalEntryId: journalEntry.id }, 'accounting');
    return mapInvoiceRow(updated[0]!);
  } catch (err) {
    log.error('Failed to approve supplier invoice', { id, error: err }, 'accounting');
    throw err;
  }
}

export async function cancelSupplierInvoice(companyId: string, id: string): Promise<SupplierInvoice> {
  try {
    const invoice = await getSupplierInvoiceById(companyId, id);
    if (!invoice) throw new Error(`Supplier invoice ${id} not found`);
    if (invoice.status === 'paid' || invoice.status === 'partially_paid') {
      throw new Error('Cannot cancel invoice with payments');
    }
    const rows = (await sql`
      UPDATE supplier_invoices SET status = 'cancelled' WHERE id = ${id} AND company_id = ${companyId}::UUID RETURNING *
    `) as Row[];
    return mapInvoiceRow(rows[0]!);
  } catch (err) {
    log.error('Failed to cancel supplier invoice', { id, error: err }, 'accounting');
    throw err;
  }
}

export async function performThreeWayMatch(companyId: string, invoiceId: string) {
  try {
    const invoice = await getSupplierInvoiceById(companyId, invoiceId);
    if (!invoice) throw new Error(`Invoice ${invoiceId} not found`);
    if (!invoice.purchaseOrderId) throw new Error('Invoice has no linked PO');

    const poItems = (await sql`
      SELECT * FROM po_items WHERE purchase_order_id = ${invoice.purchaseOrderId}
    `) as Row[];

    const grnItems = invoice.grnId
      ? ((await sql`
          SELECT * FROM grn_items WHERE grn_id = ${invoice.grnId}
        `) as Row[])
      : [];

    const results = invoice.items.map(item => {
      const poItem = item.poItemId ? poItems.find((p: Row) => String(p.id) === item.poItemId) : null;
      const grnItem = poItem ? grnItems.find((g: Row) => String(g.po_item_id) === String(poItem.id)) : null;

      return {
        itemDescription: item.description,
        match: validateThreeWayMatch({
          poQuantity: poItem ? Number(poItem.quantity_ordered) : 0,
          poUnitPrice: poItem ? Number(poItem.unit_price) : 0,
          grnQuantityReceived: grnItem ? Number(grnItem.quantity_received) : 0,
          invoiceQuantity: item.quantity,
          invoiceUnitPrice: item.unitPrice,
        }),
      };
    });

    const overallStatus = results.every(r => r.match.status === 'fully_matched')
      ? 'fully_matched'
      : results.some(r => r.match.status === 'po_matched') ? 'po_matched'
      : results.some(r => r.match.status === 'grn_matched') ? 'grn_matched'
      : 'unmatched';

    await sql`
      UPDATE supplier_invoices SET match_status = ${overallStatus} WHERE id = ${invoiceId} AND company_id = ${companyId}::UUID
    `;

    return { invoiceId, matchStatus: overallStatus, itemResults: results };
  } catch (err) {
    log.error('Failed to perform 3-way match', { invoiceId, error: err }, 'accounting');
    throw err;
  }
}

function calculateDueDate(invoiceDate: string, paymentTerms?: string): string | null {
  if (!paymentTerms) return null;
  const match = paymentTerms.match(/net(\d+)/i);
  if (!match) return null;
  const date = new Date(invoiceDate);
  date.setDate(date.getDate() + Number(match[1]));
  return date.toISOString().split('T')[0]!;
}

