    if (cn.client_address) {
      for (const line of String(cn.client_address).split('\n')) {
        doc.text(line.trim(), rightX, ry); ry += 4;
      }
    }
    if (cn.client_vat) { doc.text(`VAT No: ${cn.client_vat}`, rightX, ry); ry += 4; }
  }

