/**
 * Customer Payments API
 * GET  /api/accounting/customer-payments - List payments (with filters)
 * POST /api/accounting/customer-payments - Create payment with allocations
 */

import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type AuthenticatedNextApiRequest, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import {
  getCustomerPayments,
  getCustomerPaymentById,
  createCustomerPayment,
} from '@/modules/accounting/services/customerPaymentService';
import type { CustomerPaymentStatus } from '@/modules/accounting/types/ar.types';

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  const { companyId } = req as CompanyApiRequest;

  if (req.method === 'GET') {
    try {
      const { id, status, client_id, limit, offset } = req.query;

      // Single payment by ID
      if (id) {
        const payment = await getCustomerPaymentById(companyId, String(id));
        if (!payment) return apiResponse.notFound(res, 'Payment', String(id));
        return apiResponse.success(res, payment);
      }

      const result = await getCustomerPayments(companyId, {
        status: status as CustomerPaymentStatus | undefined,
        clientId: client_id ? String(client_id) : undefined,
        limit: limit ? Number(limit) : undefined,
        offset: offset ? Number(offset) : undefined,
      });
      return apiResponse.success(res, result);
    } catch (err) {
      log.error('Failed to get customer payments', { error: err }, 'accounting-api');
      return apiResponse.badRequest(res, 'Failed to get customer payments');
    }
  }

  if (req.method === 'POST') {
    try {
      const { clientId, paymentDate, totalAmount, paymentMethod, bankReference,
        bankAccountId, description, projectId, allocations } = req.body;

      if (!clientId || !paymentDate || !totalAmount || !allocations || !Array.isArray(allocations)) {
        return apiResponse.badRequest(res, 'clientId, paymentDate, totalAmount, and allocations are required');
      }

      // User identity comes from JWT (req.user), never from client request body
      const userId = req.user.id;

      const payment = await createCustomerPayment(companyId, {
        clientId: String(clientId),
        paymentDate,
        totalAmount: Number(totalAmount),
        paymentMethod: paymentMethod || 'eft',
        bankReference: bankReference || undefined,
        bankAccountId: bankAccountId || undefined,
        description: description || undefined,
        projectId: projectId || undefined,
        allocations: allocations.map((a: { invoiceId: string; amount: number }) => ({
          invoiceId: String(a.invoiceId),
          amount: Number(a.amount),
        })),
      }, userId);

      return apiResponse.created(res, payment);
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to create customer payment';
      log.error('Failed to create customer payment', { error: err }, 'accounting-api');
      return apiResponse.badRequest(res, message);
    }
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST']);
}


export default withCompany(withErrorHandler(handler));

/**
 * Batch Payment Actions API
 * POST — approve, process, cancel
 */

import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type AuthenticatedNextApiRequest, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import {
  approveBatch,
  processBatch,
  cancelBatch,
} from '@/modules/accounting/services/batchPaymentService';

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['POST']);
  }

  const { companyId } = req as CompanyApiRequest;

  try {
    const { action, id } = req.body;
    const userId = req.user.id;
    if (!action || !id) return apiResponse.badRequest(res, 'action and id are required');

    switch (action) {
      case 'approve': {
        await approveBatch(companyId, id, userId);
        return apiResponse.success(res, { status: 'approved' });
      }
      case 'process': {
        await processBatch(companyId, id, userId);
        return apiResponse.success(res, { status: 'processed' });
      }
      case 'cancel':
        await cancelBatch(companyId, id);
        return apiResponse.success(res, { status: 'cancelled' });
      default:
        return apiResponse.badRequest(res, `Unknown action: ${action}`);
    }
  } catch (err) {
    const msg = err instanceof Error ? err.message : 'Action failed';
    log.error('Batch payment action failed', { error: err }, 'accounting-api');
    return apiResponse.badRequest(res, msg);
  }
}


export default withCompany(withErrorHandler(handler));

import { sql } from '@/lib/neon';
/**
 * Bank Transfers API
 * POST /api/accounting/bank-transfers - Transfer between bank accounts
 * Creates a balanced journal entry: DR destination bank, CR source bank
 * Sage equivalent: Banking > Transfers
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type AuthenticatedNextApiRequest, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';


async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['POST']);
  }

  const { companyId } = req as CompanyApiRequest;
  const userId = (req as AuthenticatedNextApiRequest).user.id;
  const { fromAccountId, toAccountId, amount, reference, transferDate } = req.body;

  if (!fromAccountId || !toAccountId || !amount) {
    return apiResponse.validationError(res, {
      ...((!fromAccountId) && { fromAccountId: 'Required' }),
      ...((!toAccountId) && { toAccountId: 'Required' }),
      ...((!amount) && { amount: 'Required' }),
    });
  }

  if (fromAccountId === toAccountId) {
    return apiResponse.badRequest(res, 'Source and destination accounts must be different');
  }

  if (Number(amount) <= 0) {
    return apiResponse.badRequest(res, 'Transfer amount must be positive');
  }

  try {
    // Verify both accounts exist and are bank accounts
    const accounts = await sql`
      SELECT id, account_code, account_name, account_subtype
      FROM gl_accounts
      WHERE id IN (${fromAccountId}, ${toAccountId}) AND company_id = ${companyId}
    `;

    if (accounts.length !== 2) {
      return apiResponse.badRequest(res, 'One or both accounts not found');
    }

    const fromAcct = accounts.find(a => a.id === fromAccountId);
    const toAcct = accounts.find(a => a.id === toAccountId);

    // Get current fiscal period
    const [period] = await sql`
      SELECT id FROM fiscal_periods
      WHERE status = 'open' AND company_id = ${companyId}
      ORDER BY start_date DESC
      LIMIT 1
    `;

    // Create journal entry
    const entryRef = reference || `Transfer: ${fromAcct?.account_name} → ${toAcct?.account_name}`;
    const txDate = transferDate || new Date().toISOString().split('T')[0];

    const entryRows = await sql`
      INSERT INTO gl_journal_entries (
        id, entry_number, entry_date, description,
        source, status, fiscal_period_id,
        total_debit, total_credit,
        created_by, created_at, company_id
      ) VALUES (
        gen_random_uuid(),
        'TXF-' || LPAD((SELECT COALESCE(MAX(CAST(SUBSTRING(entry_number FROM 5) AS INTEGER)), 0) + 1 FROM gl_journal_entries WHERE entry_number LIKE 'TXF-%' AND company_id = ${companyId})::text, 4, '0'),
        ${txDate}, ${entryRef},
        'bank_transfer', 'posted', ${period?.id || null},
        ${Number(amount)}, ${Number(amount)},
        ${userId}, NOW(), ${companyId}
      )
      RETURNING *
    `;
    const entry = entryRows[0];
    if (!entry) throw new Error('Failed to create journal entry');

    // Create journal lines: DR destination, CR source
    await sql`
      INSERT INTO gl_journal_lines (id, journal_entry_id, gl_account_id, debit, credit, description, created_at)
      VALUES
        (gen_random_uuid(), ${entry.id}, ${toAccountId}, ${Number(amount)}, 0, ${`Transfer from ${fromAcct?.account_name}`}, NOW()),
        (gen_random_uuid(), ${entry.id}, ${fromAccountId}, 0, ${Number(amount)}, ${`Transfer to ${toAcct?.account_name}`}, NOW())
    `;

    log.info('Bank transfer completed', {
      entryId: entry.id,
      from: fromAcct?.account_code,
      to: toAcct?.account_code,
      amount,
      module: 'accounting',
    });

    return apiResponse.success(res, {
      journalEntry: entry,
      message: `Transferred R${Number(amount).toFixed(2)} from ${fromAcct?.account_name} to ${toAcct?.account_name}`,
    });
  } catch (err) {
    log.error('Failed to process bank transfer', { error: err, module: 'accounting' });
    return apiResponse.databaseError(res, err, 'Failed to process bank transfer');
  }
}


export default withCompany(withErrorHandler(handler));

/**
 * Customer Invoice Create API (standalone, not project-linked)
 * POST — create invoice with line items
 */

import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type AuthenticatedNextApiRequest, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import { sql } from '@/lib/neon';
type Row = Record<string, unknown>;


async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  const { companyId } = req as CompanyApiRequest;

  if (req.method !== 'POST') return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['POST']);

  const { clientId, invoiceDate, dueDate, billingPeriodStart, billingPeriodEnd, taxRate, notes, items } = req.body;
  if (!clientId) return apiResponse.badRequest(res, 'clientId is required');
  if (!items || !Array.isArray(items) || items.length === 0) return apiResponse.badRequest(res, 'items required');

  try {
    const userId = String(req.user?.id || 'system');

    // Auto-generate invoice number (use MAX to avoid duplicates)
    const maxRows = (await sql`
      SELECT MAX(CAST(SUBSTRING(invoice_number FROM '[0-9]+$') AS INTEGER)) as max_num
      FROM customer_invoices WHERE company_id = ${companyId} AND invoice_number LIKE 'INV-%'
    `) as Row[];
    const nextNum = (Number(maxRows[0]?.['max_num']) || 0) + 1;
    const invoiceNumber = `INV-${String(nextNum).padStart(5, '0')}`;

    // Calculate totals
    const rate = taxRate ?? 15;
    let subtotal = 0;
    for (const item of items) {
      subtotal += (item.quantity || 1) * item.unitPrice;
    }
    subtotal = Math.round(subtotal * 100) / 100;
    const taxAmount = Math.round(subtotal * (rate / 100) * 100) / 100;
    const totalAmount = subtotal + taxAmount;

    const today = new Date().toISOString().split('T')[0];
    const invDate = invoiceDate || today;
    const bpStart = billingPeriodStart || null;
    const bpEnd = billingPeriodEnd || null;

    // Find project from client (optional)
    let projectId: string | null = null;
    try {
      const projRows = (await sql`SELECT id FROM projects WHERE client_id = ${clientId}::UUID LIMIT 1`) as Row[];
      projectId = (projRows[0]?.['id'] as string | undefined) ?? null;
    } catch { /* projects table may not exist */ }

    const invRows = (await sql`
      INSERT INTO customer_invoices (
        company_id, invoice_number, project_id, customer_id, client_id, billing_period_start, billing_period_end,
        subtotal, tax_rate, tax_amount, total_amount, invoice_date, due_date,
        notes, status, created_by
      ) VALUES (
        ${companyId}, ${invoiceNumber}, ${projectId}, ${clientId}::UUID, ${clientId}::UUID, ${bpStart}, ${bpEnd},
        ${subtotal}, ${rate}, ${taxAmount}, ${totalAmount}, ${invDate},
        ${dueDate || null}, ${notes || null}, 'draft', ${userId}
      ) RETURNING id
    `) as Row[];

    const invoiceId = String(invRows[0]!.id);

    for (const item of items) {
      const qty = item.quantity || 1;
      const lineAmount = Math.round(qty * item.unitPrice * 100) / 100;
      await sql`
        INSERT INTO customer_invoice_items (invoice_id, description, unit_price, quantity, amount, tax_rate)
        VALUES (${invoiceId}::UUID, ${item.description}, ${item.unitPrice}, ${qty}, ${lineAmount}, ${rate})
      `;
    }

    log.info('Customer invoice created', { invoiceNumber, totalAmount });
    return apiResponse.created(res, { id: invoiceId, invoiceNumber });
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    log.error('Invoice create failed', { error: msg });
    const clientMessage = process.env.NODE_ENV === 'development' ? msg : 'Failed to create invoice';
    return res.status(500).json({ success: false, error: { code: 'CREATE_FAILED', message: clientMessage } });
  }
}


