}

/**
 * Accounting Adjustment Service
 * Phase 1 Sage Alignment: Customer & supplier balance adjustments
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { createJournalEntry, postJournalEntry } from './journalEntryService';
import { getSystemAccount } from './systemAccountResolver';
import type { AccountingAdjustment, AdjustmentCreateInput } from '../types/ar.types';
import type { JournalLineInput } from '../types/gl.types';
type Row = Record<string, unknown>;


export async function getAdjustments(companyId: string, filters?: {
  entityType?: string;
  status?: string;
  limit?: number;
  offset?: number;
}): Promise<{ items: AccountingAdjustment[]; total: number }> {
  const limit = filters?.limit || 50;
  const offset = filters?.offset || 0;
  let rows: Row[];
  let countRows: Row[];

  if (filters?.entityType) {
    rows = (await sql`
      SELECT a.*, c.name AS customer_name, s.name AS supplier_name
      FROM accounting_adjustments a
      LEFT JOIN customers c ON a.entity_type = 'customer' AND c.id = a.entity_id
      LEFT JOIN suppliers s ON a.entity_type = 'supplier' AND s.id = a.entity_id
      WHERE a.company_id = ${companyId} AND a.entity_type = ${filters.entityType}
      ORDER BY a.created_at DESC LIMIT ${limit} OFFSET ${offset}
    `) as Row[];
    countRows = (await sql`
      SELECT COUNT(*) AS cnt FROM accounting_adjustments
      WHERE company_id = ${companyId} AND entity_type = ${filters.entityType}
    `) as Row[];
  } else {
    rows = (await sql`
      SELECT a.*, c.name AS customer_name, s.name AS supplier_name
      FROM accounting_adjustments a
      LEFT JOIN customers c ON a.entity_type = 'customer' AND c.id = a.entity_id
      LEFT JOIN suppliers s ON a.entity_type = 'supplier' AND s.id = a.entity_id
      WHERE a.company_id = ${companyId}
      ORDER BY a.created_at DESC LIMIT ${limit} OFFSET ${offset}
    `) as Row[];
    countRows = (await sql`SELECT COUNT(*) AS cnt FROM accounting_adjustments WHERE company_id = ${companyId}`) as Row[];
  }

  const items: AccountingAdjustment[] = rows.map(row => {
    const mapped = mapRow(row);
    mapped.entityName = row.entity_type === 'customer'
      ? (row.customer_name ? String(row.customer_name) : 'Unknown')
      : (row.supplier_name ? String(row.supplier_name) : 'Unknown');
    return mapped;
  });

  return { items, total: Number(countRows[0]?.cnt || 0) };
}

export async function createAdjustment(companyId: string, 
  input: AdjustmentCreateInput,
  userId: string
): Promise<AccountingAdjustment> {
  const rows = (await sql`
    INSERT INTO accounting_adjustments (
      company_id, entity_type, entity_id, adjustment_type, amount, reason,
      adjustment_date, created_by
    ) VALUES (
      ${companyId}, ${input.entityType}, ${input.entityId}::UUID, ${input.adjustmentType},
      ${input.amount}, ${input.reason},
      ${input.adjustmentDate || new Date().toISOString().split('T')[0]},
      ${userId}::UUID
    ) RETURNING *
  `) as Row[];

  log.info('Created adjustment', { id: rows[0]?.id, type: input.entityType }, 'accounting');
  return mapRow(rows[0]!);
}

export async function approveAdjustment(companyId: string, id: string, userId: string): Promise<AccountingAdjustment> {
  const adjRows = (await sql`SELECT * FROM accounting_adjustments WHERE id = ${id} AND company_id = ${companyId}`) as Row[];
  if (!adjRows[0]) throw new Error('Adjustment not found');
  if (adjRows[0].status !== 'draft') throw new Error('Adjustment is not in draft status');

  const adj = adjRows[0];
  const amount = Number(adj.amount);
  const isCustomer = adj.entity_type === 'customer';
  const isDebit = adj.adjustment_type === 'debit';

  // GL accounts
  const balanceAccount = isCustomer
    ? await getSystemAccount('receivable')
    : await getSystemAccount('payable');
  const offsetAccount = isDebit
    ? await getSystemAccount('other_income')
    : await getSystemAccount('admin_expense');

  const lines: JournalLineInput[] = isDebit
    ? [
        { glAccountId: balanceAccount.id, debit: amount, credit: 0,
          description: `Adjustment ${adj.adjustment_number}` },
        { glAccountId: offsetAccount.id, debit: 0, credit: amount,
          description: `Adjustment ${adj.adjustment_number}` },
      ]
    : [
        { glAccountId: offsetAccount.id, debit: amount, credit: 0,
          description: `Adjustment ${adj.adjustment_number}` },
        { glAccountId: balanceAccount.id, debit: 0, credit: amount,
          description: `Adjustment ${adj.adjustment_number}` },
      ];

  const je = await createJournalEntry('', {
    entryDate: String(adj.adjustment_date),
    description: `${isCustomer ? 'Customer' : 'Supplier'} adjustment ${adj.adjustment_number}`,
    source: 'auto_adjustment',
    sourceDocumentId: id,
    lines,
  }, userId);
  await postJournalEntry(companyId, je.id, userId);

  const updated = (await sql`
    UPDATE accounting_adjustments
    SET status = 'approved', approved_by = ${userId}::UUID, approved_at = NOW(),
        gl_journal_entry_id = ${je.id}::UUID
    WHERE id = ${id} AND company_id = ${companyId} RETURNING *
  `) as Row[];

  log.info('Approved adjustment', { id, journalEntryId: je.id }, 'accounting');
  return mapRow(updated[0]!);
}

export async function cancelAdjustment(companyId: string, id: string): Promise<void> {
  await sql`UPDATE accounting_adjustments SET status = 'cancelled' WHERE id = ${id} AND company_id = ${companyId} AND status = 'draft'`;
}

function mapRow(row: Row): AccountingAdjustment {
  return {
    id: String(row.id),
    adjustmentNumber: row.adjustment_number ? String(row.adjustment_number) : '',
    entityType: String(row.entity_type) as AccountingAdjustment['entityType'],
    entityId: String(row.entity_id),
    adjustmentType: String(row.adjustment_type) as AccountingAdjustment['adjustmentType'],
    amount: Number(row.amount),
    reason: String(row.reason),
    adjustmentDate: String(row.adjustment_date),
    status: String(row.status) as AccountingAdjustment['status'],
    glJournalEntryId: row.gl_journal_entry_id ? String(row.gl_journal_entry_id) : undefined,
    approvedBy: row.approved_by ? String(row.approved_by) : undefined,
    approvedAt: row.approved_at ? String(row.approved_at) : undefined,
    createdBy: String(row.created_by),
    createdAt: String(row.created_at),
    updatedAt: String(row.updated_at),
  };
}

/**
 * PRD-060: FibreFlow Accounting Module — Phase 3
 * Credit Note Service (Customer & Supplier)
 */

import { sql, withTransaction } from '@/lib/neon';
import { log } from '@/lib/logger';
import { createJournalEntry, postJournalEntry, reverseJournalEntry } from './journalEntryService';
import { getSystemAccount } from './systemAccountResolver';
import type { CreditNote, CreditNoteCreateInput, CreditNoteStatus } from '../types/ar.types';
import type { JournalLineInput } from '../types/gl.types';

interface CreditNoteFilters {
  type?: 'customer' | 'supplier';
  status?: CreditNoteStatus;
  limit?: number;
  offset?: number;
}

export async function getCreditNotes(companyId: string, filters?: CreditNoteFilters): Promise<{
  creditNotes: CreditNote[];
  total: number;
}> {
  try {
    // TODO: Apply pagination cap to all list endpoints (M16)
    const limit = Math.min(filters?.limit || 50, 200);
    const offset = filters?.offset || 0;
    let rows: Record<string, unknown>[];
    let countRows: Record<string, unknown>[];

    if (filters?.type) {
      rows = (await sql`
        SELECT cn.*, c.name AS client_name, COALESCE(s.company_name, s.name) AS supplier_name,
          COALESCE(ci.invoice_number, si.invoice_number) AS invoice_number
        FROM credit_notes cn
        LEFT JOIN customers c ON c.id = cn.client_id
        LEFT JOIN suppliers s ON s.id = cn.supplier_id
        LEFT JOIN customer_invoices ci ON ci.id = cn.customer_invoice_id
        LEFT JOIN supplier_invoices si ON si.id = cn.supplier_invoice_id
        WHERE cn.company_id = ${companyId} AND cn.type = ${filters.type}
        ORDER BY cn.credit_date DESC LIMIT ${limit} OFFSET ${offset}
      `) as Record<string, unknown>[];
      countRows = (await sql`
        SELECT COUNT(*) AS cnt FROM credit_notes WHERE company_id = ${companyId} AND type = ${filters.type}
      `) as Record<string, unknown>[];
    } else {
      rows = (await sql`
        SELECT cn.*, c.name AS client_name, COALESCE(s.company_name, s.name) AS supplier_name,
          COALESCE(ci.invoice_number, si.invoice_number) AS invoice_number
        FROM credit_notes cn
        LEFT JOIN customers c ON c.id = cn.client_id
        LEFT JOIN suppliers s ON s.id = cn.supplier_id
        LEFT JOIN customer_invoices ci ON ci.id = cn.customer_invoice_id
        LEFT JOIN supplier_invoices si ON si.id = cn.supplier_invoice_id
        WHERE cn.company_id = ${companyId}
        ORDER BY cn.credit_date DESC LIMIT ${limit} OFFSET ${offset}
      `) as Record<string, unknown>[];
      countRows = (await sql`SELECT COUNT(*) AS cnt FROM credit_notes WHERE company_id = ${companyId}`) as Record<string, unknown>[];
    }

    return { creditNotes: rows.map(mapRow), total: Number(countRows[0]!.cnt) };
  } catch (err) {
    log.error('Failed to get credit notes', { error: err }, 'accounting');
    throw err;
  }
}

export async function getCreditNoteById(companyId: string, id: string): Promise<CreditNote | null> {
  const rows = (await sql`
    SELECT cn.*, c.name AS client_name, COALESCE(s.company_name, s.name) AS supplier_name,
      COALESCE(ci.invoice_number, si.invoice_number) AS invoice_number
    FROM credit_notes cn
    LEFT JOIN customers c ON c.id = cn.client_id
    LEFT JOIN suppliers s ON s.id = cn.supplier_id
    LEFT JOIN customer_invoices ci ON ci.id = cn.customer_invoice_id
    LEFT JOIN supplier_invoices si ON si.id = cn.supplier_invoice_id
    WHERE cn.id = ${id}::UUID AND cn.company_id = ${companyId}
  `) as Record<string, unknown>[];
  return rows.length > 0 ? mapRow(rows[0]!) : null;
}

export async function createCreditNote(companyId: string, 
  input: CreditNoteCreateInput,
  userId: string
): Promise<CreditNote> {
  try {
    const taxRate = input.taxRate ?? 15;
    const taxAmount = Math.round(input.subtotal * taxRate / 100 * 100) / 100;
    const totalAmount = input.subtotal + taxAmount;

    const rows = (await sql`
      INSERT INTO credit_notes (
        type, client_id, customer_invoice_id, supplier_id, supplier_invoice_id,
        credit_date, reason, subtotal, tax_rate, tax_amount, total_amount,
        project_id, created_by
      ) VALUES (
        ${input.type}, ${input.clientId || null}, ${input.customerInvoiceId || null},
        ${input.supplierId ? Number(input.supplierId) : null},
        ${input.supplierInvoiceId || null},
        ${input.creditDate}, ${input.reason || null},
        ${input.subtotal}, ${taxRate}, ${taxAmount}, ${totalAmount},
        ${input.projectId || null}, ${userId}::UUID
      ) RETURNING *
    `) as Record<string, unknown>[];

    log.info('Created credit note', { id: String(rows[0]!.id), type: input.type }, 'accounting');
    return mapRow(rows[0]!);
  } catch (err) {
    log.error('Failed to create credit note', { error: err }, 'accounting');
    throw err;
  }
}

export async function approveCreditNote(companyId: string, id: string, userId: string): Promise<CreditNote> {
  try {
    const cnRows = (await sql`SELECT * FROM credit_notes WHERE id = ${id} AND company_id = ${companyId}`) as Record<string, unknown>[];
    if (cnRows.length === 0) throw new Error(`Credit note ${id} not found`);
    const cn = cnRows[0]!;
    if (String(cn.status) !== 'draft') throw new Error(`Cannot approve credit note with status: ${cn.status}`);

    let lines: JournalLineInput[];

    if (String(cn.type) === 'customer') {
      // Customer CN: DR Revenue, CR Accounts Receivable
      const revenueAccount = await getSystemAccount('default_revenue');
      const arAccount = await getSystemAccount('receivable');
      const vatAccount = await getSystemAccount('vat_output');

      lines = [
        { glAccountId: revenueAccount.id, debit: Number(cn.subtotal), credit: 0,
          description: `Credit note ${cn.credit_note_number}` },
      ];
      if (Number(cn.tax_amount) > 0 && vatAccount) {
        lines.push({ glAccountId: vatAccount.id, debit: Number(cn.tax_amount), credit: 0,
          description: `VAT reversal: ${cn.credit_note_number}` });
      }
      lines.push({ glAccountId: arAccount.id, debit: 0, credit: Number(cn.total_amount),
        description: `AR credit: ${cn.credit_note_number}` });
    } else {
      // Supplier CN: DR Accounts Payable, CR Expense
      const apAccount = await getSystemAccount('payable');
      const expenseAccount = await getSystemAccount('default_expense');
      const vatAccount = await getSystemAccount('vat_input');

      lines = [
        { glAccountId: apAccount.id, debit: Number(cn.total_amount), credit: 0,
          description: `AP credit: ${cn.credit_note_number}` },
      ];
      if (Number(cn.tax_amount) > 0 && vatAccount) {
        lines.push({ glAccountId: vatAccount.id, debit: 0, credit: Number(cn.tax_amount),
          description: `VAT reversal: ${cn.credit_note_number}` });
      }
      lines.push({ glAccountId: expenseAccount.id, debit: 0, credit: Number(cn.subtotal),
        description: `Expense credit: ${cn.credit_note_number}` });
    }

    const je = await createJournalEntry('', {
      entryDate: String(cn.credit_date),
      description: `Credit note ${cn.credit_note_number}`,
      source: 'auto_credit_note',
      sourceDocumentId: id,
      lines,
    }, userId);
    await postJournalEntry(companyId, je.id, userId);

    // Update invoice balance and credit note status atomically
    const updated = await withTransaction(async (tx) => {
      if (String(cn.type) === 'customer' && cn.customer_invoice_id) {
        await tx`
          UPDATE customer_invoices SET amount_paid = amount_paid + ${Number(cn.total_amount)}
          WHERE id = ${cn.customer_invoice_id}::UUID
        `;
      } else if (String(cn.type) === 'supplier' && cn.supplier_invoice_id) {
        await tx`
          UPDATE supplier_invoices SET amount_paid = amount_paid + ${Number(cn.total_amount)}
          WHERE id = ${cn.supplier_invoice_id}::UUID
        `;
      }

      const rows = (await tx`
        UPDATE credit_notes SET status = 'approved', approved_by = ${userId}::UUID,
          approved_at = NOW(), gl_journal_entry_id = ${je.id}::UUID
        WHERE id = ${id} RETURNING *
      `) as Record<string, unknown>[];

      return rows[0] as Record<string, unknown>;
    });

    log.info('Approved credit note', { id, journalEntryId: je.id }, 'accounting');
    return mapRow(updated);
  } catch (err) {
    log.error('Failed to approve credit note', { id, error: err }, 'accounting');
    throw err;
  }
}

export async function cancelCreditNote(companyId: string, 
  id: string,
  userId: string,
  reason?: string
): Promise<CreditNote> {
  try {
    const cnRows = (await sql`SELECT * FROM credit_notes WHERE id = ${id} AND company_id = ${companyId}`) as Record<string, unknown>[];
    if (cnRows.length === 0) throw new Error(`Credit note ${id} not found`);
    const cn = cnRows[0]!;
    if (String(cn.status) !== 'approved') {
      throw new Error(`Cannot cancel credit note with status: ${cn.status}`);
    }

    // Reverse GL journal entry — manages its own transaction, must stay outside
    if (cn.gl_journal_entry_id) {
      await reverseJournalEntry('', String(cn.gl_journal_entry_id), userId);
    }

    // Atomically reverse invoice balance adjustments and mark credit note cancelled
    const updated = await withTransaction(async (tx) => {
      if (String(cn.type) === 'customer' && cn.customer_invoice_id) {
        await tx`
          UPDATE customer_invoices
          SET amount_paid = GREATEST(0, amount_paid - ${Number(cn.total_amount)})
          WHERE id = ${cn.customer_invoice_id}::UUID
        `;
        await tx`
          UPDATE customer_invoices SET status = CASE
            WHEN amount_paid <= 0.01 THEN 'approved'
            WHEN amount_paid < total_amount THEN 'partially_paid'
            ELSE status
          END
          WHERE id = ${cn.customer_invoice_id}::UUID
        `;
      } else if (String(cn.type) === 'supplier' && cn.supplier_invoice_id) {
        await tx`
          UPDATE supplier_invoices
          SET amount_paid = GREATEST(0, amount_paid - ${Number(cn.total_amount)})
          WHERE id = ${cn.supplier_invoice_id}::UUID
        `;
      }

      const rows = (await tx`
        UPDATE credit_notes
        SET status = 'cancelled', cancelled_by = ${userId}::UUID,
            cancelled_at = NOW(), cancel_reason = ${reason || null}
        WHERE id = ${id} RETURNING *
      `) as Record<string, unknown>[];

      return rows[0] as Record<string, unknown>;
    });

    log.info('Cancelled credit note', { id, reason }, 'accounting');
    return mapRow(updated);
  } catch (err) {
    log.error('Failed to cancel credit note', { id, error: err }, 'accounting');
    throw err;
  }
}

function mapRow(row: Record<string, unknown>): CreditNote {
  return {
    id: String(row.id),
    creditNoteNumber: row.credit_note_number ? String(row.credit_note_number) : '',
    type: String(row.type) as CreditNote['type'],
    clientId: row.client_id ? String(row.client_id) : undefined,
    customerInvoiceId: row.customer_invoice_id ? String(row.customer_invoice_id) : undefined,
    supplierId: row.supplier_id ? String(row.supplier_id) : undefined,
    supplierInvoiceId: row.supplier_invoice_id ? String(row.supplier_invoice_id) : undefined,
    creditDate: String(row.credit_date),
    reason: row.reason ? String(row.reason) : undefined,
    subtotal: Number(row.subtotal),
    taxRate: Number(row.tax_rate),
    taxAmount: Number(row.tax_amount),
    totalAmount: Number(row.total_amount),
    status: String(row.status) as CreditNoteStatus,
    glJournalEntryId: row.gl_journal_entry_id ? String(row.gl_journal_entry_id) : undefined,
    projectId: row.project_id ? String(row.project_id) : undefined,
    createdBy: String(row.created_by),
    approvedBy: row.approved_by ? String(row.approved_by) : undefined,
    approvedAt: row.approved_at ? String(row.approved_at) : undefined,
    createdAt: String(row.created_at),
    updatedAt: String(row.updated_at),
    clientName: row.client_name ? String(row.client_name) : undefined,
    supplierName: row.supplier_name ? String(row.supplier_name) : undefined,
    invoiceNumber: row.invoice_number ? String(row.invoice_number) : undefined,
  };
}

/**
 * PRD-060: FibreFlow Accounting Module — Phase 3
 * Customer Payment Service
 */

import { sql, withTransaction } from '@/lib/neon';
import { log } from '@/lib/logger';
import { createJournalEntry, postJournalEntry, reverseJournalEntry } from './journalEntryService';
import { getSystemAccount } from './systemAccountResolver';
import type {
  CustomerPayment,
  CustomerPaymentAllocation,
  CustomerPaymentCreateInput,
  CustomerPaymentStatus,
} from '../types/ar.types';
import type { JournalLineInput } from '../types/gl.types';

type Row = Record<string, unknown>;

interface PaymentFilters {
  status?: CustomerPaymentStatus;
  clientId?: string;
  limit?: number;
  offset?: number;
}

export async function getCustomerPayments(companyId: string, filters?: PaymentFilters): Promise<{
  payments: CustomerPayment[];
  total: number;
}> {
  try {
    // TODO: Apply pagination cap to all list endpoints (M16)
    const limit = Math.min(filters?.limit || 50, 200);
    const offset = filters?.offset || 0;
    let rows: Record<string, unknown>[];
    let countRows: Record<string, unknown>[];

    if (filters?.clientId) {
      rows = (await sql`
        SELECT cp.*, c.name AS client_name,
          COALESCE((SELECT SUM(cpa.amount_allocated) FROM customer_payment_allocations cpa WHERE cpa.payment_id = cp.id), 0) AS allocated_amount
        FROM customer_payments cp LEFT JOIN customers c ON c.id = cp.client_id
        WHERE cp.client_id = ${filters.clientId}::UUID AND cp.company_id = ${companyId}
        ORDER BY cp.payment_date DESC LIMIT ${limit} OFFSET ${offset}
      `) as Row[];
      countRows = (await sql`
        SELECT COUNT(*) AS cnt FROM customer_payments WHERE client_id = ${filters.clientId}::UUID AND company_id = ${companyId}
      `) as Row[];
    } else if (filters?.status) {
      rows = (await sql`
        SELECT cp.*, c.name AS client_name,
          COALESCE((SELECT SUM(cpa.amount_allocated) FROM customer_payment_allocations cpa WHERE cpa.payment_id = cp.id), 0) AS allocated_amount
        FROM customer_payments cp LEFT JOIN customers c ON c.id = cp.client_id
        WHERE cp.status = ${filters.status} AND cp.company_id = ${companyId}
        ORDER BY cp.payment_date DESC LIMIT ${limit} OFFSET ${offset}
      `) as Row[];
      countRows = (await sql`
        SELECT COUNT(*) AS cnt FROM customer_payments WHERE status = ${filters.status} AND company_id = ${companyId}
      `) as Row[];
    } else {
      rows = (await sql`
        SELECT cp.*, c.name AS client_name,
          COALESCE((SELECT SUM(cpa.amount_allocated) FROM customer_payment_allocations cpa WHERE cpa.payment_id = cp.id), 0) AS allocated_amount
        FROM customer_payments cp LEFT JOIN customers c ON c.id = cp.client_id
        WHERE cp.company_id = ${companyId}
        ORDER BY cp.payment_date DESC LIMIT ${limit} OFFSET ${offset}
      `) as Row[];
      countRows = (await sql`SELECT COUNT(*) AS cnt FROM customer_payments WHERE company_id = ${companyId}`) as Row[];
    }

    return { payments: rows.map(mapPaymentRow), total: Number(countRows[0]!.cnt) };
  } catch (err) {
    log.error('Failed to get customer payments', { error: err }, 'accounting');
    throw err;
  }
}

export async function getCustomerPaymentById(companyId: string, 
  id: string
): Promise<(CustomerPayment & { allocations: CustomerPaymentAllocation[] }) | null> {
  try {
    const rows = (await sql`
      SELECT cp.*, c.name AS client_name
      FROM customer_payments cp LEFT JOIN customers c ON c.id = cp.client_id
      WHERE cp.id = ${id} AND cp.company_id = ${companyId}
    `) as Row[];
    if (rows.length === 0) return null;

    const allocRows = (await sql`
      SELECT cpa.*, ci.invoice_number
      FROM customer_payment_allocations cpa
      LEFT JOIN customer_invoices ci ON ci.id = cpa.invoice_id
      WHERE cpa.payment_id = ${id}
    `) as Row[];

    return { ...mapPaymentRow(rows[0]!), allocations: allocRows.map(mapAllocationRow) };
  } catch (err) {
    log.error('Failed to get customer payment', { id, error: err }, 'accounting');
    throw err;
  }
}

export async function createCustomerPayment(companyId: string, 
  input: CustomerPaymentCreateInput,
  userId: string
): Promise<CustomerPayment> {
  try {
    // Validate allocations against invoice balances
    for (const alloc of input.allocations) {
      const invRows = (await sql`
        SELECT total_amount, amount_paid FROM customer_invoices WHERE id = ${alloc.invoiceId}::UUID
      `) as Row[];
      if (invRows.length === 0) throw new Error(`Invoice ${alloc.invoiceId} not found`);
      const balance = Number(invRows[0]!.total_amount) - Number(invRows[0]!.amount_paid);
      if (alloc.amount > balance + 0.01) {
        throw new Error(`Allocation R${alloc.amount.toFixed(2)} exceeds invoice balance R${balance.toFixed(2)}`);
      }
    }

    const totalAllocated = input.allocations.reduce((s, a) => s + a.amount, 0);
    if (Math.abs(totalAllocated - input.totalAmount) > 0.01) {
      throw new Error(`Allocations total R${totalAllocated.toFixed(2)} does not match payment R${input.totalAmount.toFixed(2)}`);
    }

    const paymentRow = await withTransaction(async (tx) => {
      const rows = (await tx`
        INSERT INTO customer_payments (
          client_id, payment_date, total_amount, payment_method,
          bank_reference, bank_account_id, description, project_id, created_by
        ) VALUES (
          ${input.clientId}::UUID, ${input.paymentDate}, ${input.totalAmount},
          ${input.paymentMethod || 'eft'}, ${input.bankReference || null},
          ${input.bankAccountId || null}, ${input.description || null},
          ${input.projectId || null}, ${userId}::UUID
        ) RETURNING *
      `) as Row[];

      const paymentId = String(rows[0]!.id);

      for (const alloc of input.allocations) {
        await tx`
          INSERT INTO customer_payment_allocations (payment_id, invoice_id, amount_allocated)
          VALUES (${paymentId}::UUID, ${alloc.invoiceId}::UUID, ${alloc.amount})
        `;
      }

      return rows[0] as Row;
    });

    log.info('Created customer payment', { paymentId: String(paymentRow.id), totalAmount: input.totalAmount }, 'accounting');
    return mapPaymentRow(paymentRow);
  } catch (err) {
    log.error('Failed to create customer payment', { error: err }, 'accounting');
    throw err;
  }
}

export async function confirmCustomerPayment(companyId: string, 
  id: string,
  userId: string
): Promise<CustomerPayment> {
  try {
    const payment = await getCustomerPaymentById(companyId, id);
    if (!payment) throw new Error(`Payment ${id} not found`);
    if (payment.status !== 'draft') throw new Error(`Cannot confirm payment with status: ${payment.status}`);

    // Auto-post GL: DR Bank, CR Accounts Receivable
    const arAccount = await getSystemAccount('receivable');
    const bankAccount = payment.bankAccountId
      ? ((await sql`SELECT id FROM gl_accounts WHERE id = ${payment.bankAccountId}`) as Row[])[0]
      : await getSystemAccount('bank');
    if (!bankAccount) throw new Error('Bank account not found');

    const lines: JournalLineInput[] = [
      { glAccountId: String(bankAccount.id), debit: payment.totalAmount, credit: 0,
        description: `Customer payment ${payment.paymentNumber}` },
      { glAccountId: arAccount.id, debit: 0, credit: payment.totalAmount,
        description: `Customer payment ${payment.paymentNumber}` },
    ];

    const je = await createJournalEntry(companyId, {
      entryDate: payment.paymentDate,
      description: `Customer payment ${payment.paymentNumber}`,
      source: 'auto_payment',
      sourceDocumentId: id,
      lines,
    }, userId);
    await postJournalEntry(companyId, je.id, userId);

    // Update invoice balances and mark payment confirmed atomically
    const updated = await withTransaction(async (tx) => {
      for (const alloc of payment.allocations) {
        await tx`
          UPDATE customer_invoices SET amount_paid = amount_paid + ${alloc.amountAllocated}
          WHERE id = ${alloc.invoiceId}::UUID
        `;
        await tx`
          UPDATE customer_invoices SET status = CASE
            WHEN (total_amount - amount_paid) <= 0.01 THEN 'paid'
            WHEN amount_paid > 0 THEN 'partially_paid'
            ELSE status
          END, paid_at = CASE WHEN (total_amount - amount_paid) <= 0.01 THEN NOW() ELSE paid_at END
          WHERE id = ${alloc.invoiceId}::UUID
        `;
      }

      const rows = (await tx`
        UPDATE customer_payments
        SET status = 'confirmed', confirmed_by = ${userId}::UUID, confirmed_at = NOW(),
            gl_journal_entry_id = ${je.id}::UUID
        WHERE id = ${id} RETURNING *
      `) as Row[];

      return rows[0] as Row;
    });

    log.info('Confirmed customer payment', { id, journalEntryId: je.id }, 'accounting');
    return mapPaymentRow(updated);
  } catch (err) {
    log.error('Failed to confirm customer payment', { id, error: err }, 'accounting');
    throw err;
  }
}

export async function cancelCustomerPayment(companyId: string, 
  id: string,
  userId: string,
  reason?: string
): Promise<CustomerPayment> {
  try {
    const payment = await getCustomerPaymentById(companyId, id);
    if (!payment) throw new Error(`Payment ${id} not found`);
    if (payment.status !== 'confirmed') {
      throw new Error(`Cannot cancel payment with status: ${payment.status}`);
    }

    // Reverse GL journal entry
    if (payment.glJournalEntryId) {
      await reverseJournalEntry(companyId, payment.glJournalEntryId, userId);
    }

    // Reverse invoice balance updates
    for (const alloc of payment.allocations) {
      await sql`
        UPDATE customer_invoices
        SET amount_paid = GREATEST(0, amount_paid - ${alloc.amountAllocated})
        WHERE id = ${alloc.invoiceId}::UUID
      `;
      await sql`
        UPDATE customer_invoices SET status = CASE
          WHEN amount_paid <= 0.01 THEN 'approved'
          WHEN amount_paid < total_amount THEN 'partially_paid'
          ELSE status
        END, paid_at = CASE WHEN amount_paid <= 0.01 THEN NULL ELSE paid_at END
        WHERE id = ${alloc.invoiceId}::UUID
      `;
    }

    const updated = (await sql`
      UPDATE customer_payments
      SET status = 'cancelled', cancelled_by = ${userId}::UUID,
          cancelled_at = NOW(), cancel_reason = ${reason || null}
      WHERE id = ${id} RETURNING *
    `) as Row[];

    log.info('Cancelled customer payment', { id, reason }, 'accounting');
    return mapPaymentRow(updated[0]!);
  } catch (err) {
    log.error('Failed to cancel customer payment', { id, error: err }, 'accounting');
    throw err;
  }
}

export async function postCustomerInvoiceToGL(companyId: string, invoiceId: string, userId: string): Promise<string> {
  try {
    const invRows = (await sql`
      SELECT ci.*, c.name AS client_name
      FROM customer_invoices ci LEFT JOIN customers c ON c.id = ci.client_id
      WHERE ci.id = ${invoiceId}::UUID
    `) as Row[];
    if (invRows.length === 0) throw new Error(`Invoice ${invoiceId} not found`);
    const inv = invRows[0]!;

    if (inv.gl_journal_entry_id) return String(inv.gl_journal_entry_id);

    const arAccount = await getSystemAccount('receivable');
    const revenueAccount = await getSystemAccount('default_revenue');
    const vatAccount = await getSystemAccount('vat_output');

    const lines: JournalLineInput[] = [
      { glAccountId: arAccount.id, debit: Number(inv.total_amount), credit: 0,
        description: `AR: ${inv.invoice_number}` },
      { glAccountId: revenueAccount.id, debit: 0, credit: Number(inv.subtotal),
        description: `Revenue: ${inv.invoice_number}` },
    ];

    if (Number(inv.tax_amount) > 0) {
      lines.push({
        glAccountId: vatAccount.id, debit: 0, credit: Number(inv.tax_amount),
        description: `VAT Output: ${inv.invoice_number}`,
      });
    }

    const je = await createJournalEntry(companyId, {
      entryDate: String(inv.invoice_date),
      description: `Customer invoice ${inv.invoice_number}`,
      source: 'auto_invoice',
      sourceDocumentId: invoiceId,
      lines,
    }, userId);
    await postJournalEntry(companyId, je.id, userId);

    await sql`UPDATE customer_invoices SET gl_journal_entry_id = ${je.id}::UUID WHERE id = ${invoiceId}::UUID`;

    log.info('Posted customer invoice to GL', { invoiceId, journalEntryId: je.id }, 'accounting');
    return je.id;
  } catch (err) {
    log.error('Failed to post customer invoice to GL', { invoiceId, error: err }, 'accounting');
    throw err;
  }
}

function mapPaymentRow(row: Row): CustomerPayment {
  return {
    id: String(row.id),
    paymentNumber: row.payment_number ? String(row.payment_number) : '',
    clientId: String(row.client_id),
    paymentDate: String(row.payment_date),
    totalAmount: Number(row.total_amount),
    paymentMethod: String(row.payment_method) as CustomerPayment['paymentMethod'],
    bankReference: row.bank_reference ? String(row.bank_reference) : undefined,
    bankAccountId: row.bank_account_id ? String(row.bank_account_id) : undefined,
    description: row.description ? String(row.description) : undefined,
    status: String(row.status) as CustomerPaymentStatus,
    glJournalEntryId: row.gl_journal_entry_id ? String(row.gl_journal_entry_id) : undefined,
    projectId: row.project_id ? String(row.project_id) : undefined,
    createdBy: String(row.created_by),
    confirmedBy: row.confirmed_by ? String(row.confirmed_by) : undefined,
    confirmedAt: row.confirmed_at ? String(row.confirmed_at) : undefined,
    createdAt: String(row.created_at),
    updatedAt: String(row.updated_at),
    clientName: row.client_name ? String(row.client_name) : undefined,
    allocatedAmount: row.allocated_amount !== undefined ? Number(row.allocated_amount) : 0,
  };
}

function mapAllocationRow(row: Row): CustomerPaymentAllocation & { amount: number } {
  const amt = Number(row.amount_allocated || row.amount || 0);
  return {
    id: String(row.id),
    paymentId: String(row.payment_id),
    invoiceId: String(row.invoice_id),
    amountAllocated: amt,
    amount: amt,
    createdAt: String(row.created_at),
    invoiceNumber: row.invoice_number ? String(row.invoice_number) : undefined,
  };
}

/**
 * PRD-060: FibreFlow Accounting Module — Phase 2
 * Supplier Payment Service
 */

import { sql, withTransaction } from '@/lib/neon';
import { log } from '@/lib/logger';
import { createJournalEntry, postJournalEntry } from './journalEntryService';
import { getSystemAccount } from './systemAccountResolver';
import { validatePaymentAllocations } from '../utils/paymentAllocation';
import type {
  SupplierPayment,
  PaymentAllocation,
  PaymentAllocationInput,
  PaymentMethod,
  PaymentStatus,
  InvoiceForAllocation,
} from '../types/ap.types';
import type { JournalLineInput } from '../types/gl.types';
type Row = Record<string, unknown>;


interface PaymentFilters {
  status?: PaymentStatus;
  supplierId?: number;
  limit?: number;
  offset?: number;
}

export interface CreatePaymentInput {
  supplierId: number;
  paymentDate: string;
  totalAmount: number;
  paymentMethod?: PaymentMethod;
  bankAccountId?: string;
  reference?: string;
  description?: string;
  allocations: PaymentAllocationInput[];
}

export async function getSupplierPayments(companyId: string, filters?: PaymentFilters): Promise<{
  payments: SupplierPayment[];
  total: number;
}> {
  try {
    // TODO: Apply pagination cap to all list endpoints (M16)
    const limit = Math.min(filters?.limit || 50, 200);
    const offset = filters?.offset || 0;
    let rows: Row[];
    let countRows: Row[];

    if (filters?.status && filters?.supplierId) {
      rows = (await sql`
        SELECT sp.*, s.name AS supplier_name
        FROM supplier_payments sp LEFT JOIN suppliers s ON s.id = sp.supplier_id
        WHERE sp.company_id = ${companyId}::UUID
          AND sp.status = ${filters.status} AND sp.supplier_id = ${filters.supplierId}
        ORDER BY sp.payment_date DESC LIMIT ${limit} OFFSET ${offset}
      `) as Row[];
      countRows = (await sql`
        SELECT COUNT(*) AS cnt FROM supplier_payments
        WHERE company_id = ${companyId}::UUID
          AND status = ${filters.status} AND supplier_id = ${filters.supplierId}
      `) as Row[];
    } else if (filters?.status) {
      rows = (await sql`
        SELECT sp.*, s.name AS supplier_name
        FROM supplier_payments sp LEFT JOIN suppliers s ON s.id = sp.supplier_id
        WHERE sp.company_id = ${companyId}::UUID AND sp.status = ${filters.status}
        ORDER BY sp.payment_date DESC LIMIT ${limit} OFFSET ${offset}
      `) as Row[];
      countRows = (await sql`
        SELECT COUNT(*) AS cnt FROM supplier_payments
        WHERE company_id = ${companyId}::UUID AND status = ${filters.status}
      `) as Row[];
    } else if (filters?.supplierId) {
      rows = (await sql`
        SELECT sp.*, s.name AS supplier_name
        FROM supplier_payments sp LEFT JOIN suppliers s ON s.id = sp.supplier_id
        WHERE sp.company_id = ${companyId}::UUID AND sp.supplier_id = ${filters.supplierId}
        ORDER BY sp.payment_date DESC LIMIT ${limit} OFFSET ${offset}
      `) as Row[];
      countRows = (await sql`
        SELECT COUNT(*) AS cnt FROM supplier_payments
        WHERE company_id = ${companyId}::UUID AND supplier_id = ${filters.supplierId}
      `) as Row[];
    } else {
      rows = (await sql`
        SELECT sp.*, s.name AS supplier_name
        FROM supplier_payments sp LEFT JOIN suppliers s ON s.id = sp.supplier_id
        WHERE sp.company_id = ${companyId}::UUID
        ORDER BY sp.payment_date DESC LIMIT ${limit} OFFSET ${offset}
      `) as Row[];
      countRows = (await sql`
        SELECT COUNT(*) AS cnt FROM supplier_payments WHERE company_id = ${companyId}::UUID
      `) as Row[];
    }

    return { payments: rows.map(mapPaymentRow), total: Number(countRows[0]!.cnt) };
  } catch (err) {
    log.error('Failed to get supplier payments', { error: err }, 'accounting');
    throw err;
  }
}

export async function getSupplierPaymentById(companyId: string, 
  id: string
): Promise<(SupplierPayment & { allocations: PaymentAllocation[] }) | null> {
  try {
    const rows = (await sql`
      SELECT sp.*, s.name AS supplier_name
      FROM supplier_payments sp LEFT JOIN suppliers s ON s.id = sp.supplier_id
      WHERE sp.id = ${id} AND sp.company_id = ${companyId}::UUID
    `) as Row[];
    if (rows.length === 0) return null;

    const allocRows = (await sql`
      SELECT pa.*, si.invoice_number
      FROM payment_allocations pa
      LEFT JOIN supplier_invoices si ON si.id = pa.invoice_id
      WHERE pa.payment_id = ${id}
    `) as Row[];

    return { ...mapPaymentRow(rows[0]!), allocations: allocRows.map(mapAllocationRow) };
  } catch (err) {
    log.error('Failed to get supplier payment', { id, error: err }, 'accounting');
    throw err;
  }
}

export async function createSupplierPayment(companyId: string, 
  input: CreatePaymentInput,
  userId: string
): Promise<SupplierPayment> {
  try {
    // Load invoices for allocation validation
    const invoiceIds = input.allocations.map(a => a.invoiceId);
    const invoiceRows = (await sql`
      SELECT id, invoice_number, total_amount, amount_paid, balance
      FROM supplier_invoices
      WHERE id = ANY(${invoiceIds}::UUID[])
    `) as Row[];

    const invoices: InvoiceForAllocation[] = invoiceRows.map((r: Row) => ({
      id: String(r.id),
      invoiceNumber: String(r.invoice_number),
      totalAmount: Number(r.total_amount),
      amountPaid: Number(r.amount_paid),
      balance: Number(r.balance),
    }));

    const validation = validatePaymentAllocations(input.totalAmount, input.allocations, invoices);
    if (!validation.valid) {
      throw new Error(`Invalid allocations: ${validation.errors.join('; ')}`);
    }

    const paymentRow = await withTransaction(async (tx) => {
      const rows = (await tx`
        INSERT INTO supplier_payments (
          company_id, supplier_id, payment_date, total_amount, payment_method,
          bank_account_id, reference, description, created_by
        ) VALUES (
          ${companyId}::UUID, ${input.supplierId}, ${input.paymentDate}, ${input.totalAmount},
          ${input.paymentMethod || 'eft'}, ${input.bankAccountId || null},
          ${input.reference || null}, ${input.description || null}, ${userId}::UUID
        ) RETURNING *
      `) as Row[];

      const paymentId = String(rows[0]!.id);

      for (const alloc of input.allocations) {
        await tx`
          INSERT INTO payment_allocations (payment_id, invoice_id, amount_allocated)
          VALUES (${paymentId}::UUID, ${alloc.invoiceId}::UUID, ${alloc.amount})
        `;
      }

      return rows[0] as Row;
    });

    log.info('Created supplier payment', {
      paymentId: String(paymentRow.id),
      paymentNumber: String(paymentRow.payment_number),
      totalAmount: input.totalAmount,
    }, 'accounting');

    return mapPaymentRow(paymentRow);
  } catch (err) {
    log.error('Failed to create supplier payment', { error: err }, 'accounting');
    throw err;
  }
}

export async function processSupplierPayment(companyId: string, 
  id: string,
  userId: string
): Promise<SupplierPayment> {
  try {
    const payment = await getSupplierPaymentById(companyId, id);
    if (!payment) throw new Error(`Payment ${id} not found`);
    if (payment.status !== 'approved') throw new Error(`Payment must be approved before processing`);

    // Auto-post GL entry: DR Accounts Payable, CR Bank
    const apAccount = await getSystemAccount('payable');
    const bankAccount = payment.bankAccountId
      ? ((await sql`SELECT * FROM gl_accounts WHERE id = ${payment.bankAccountId}`) as Row[])[0]
      : await getSystemAccount('bank');

    if (!bankAccount) throw new Error('Bank account not found');

    const lines: JournalLineInput[] = [
      {
        glAccountId: apAccount.id,
        debit: payment.totalAmount,
        credit: 0,
        description: `Payment ${payment.paymentNumber} to supplier`,
      },
      {
        glAccountId: String(bankAccount.id),
        debit: 0,
        credit: payment.totalAmount,
        description: `Payment ${payment.paymentNumber} to supplier`,
      },
    ];

    const journalEntry = await createJournalEntry(companyId, {
      entryDate: payment.paymentDate,
      description: `Supplier payment ${payment.paymentNumber}`,
      source: 'auto_supplier_payment',
      sourceDocumentId: id,
      lines,
    }, userId);

    await postJournalEntry(companyId, journalEntry.id, userId);

    // Update invoice balances and mark payment processed atomically
    const updated = await withTransaction(async (tx) => {
      for (const alloc of payment.allocations) {
        await tx`
          UPDATE supplier_invoices
          SET amount_paid = amount_paid + ${alloc.amountAllocated}
          WHERE id = ${alloc.invoiceId}
        `;
        await tx`
          UPDATE supplier_invoices SET status = CASE
            WHEN (total_amount - amount_paid) <= 0.01 THEN 'paid'
            WHEN amount_paid > 0 THEN 'partially_paid'
            ELSE status
          END
          WHERE id = ${alloc.invoiceId}
        `;
      }

      const rows = (await tx`
        UPDATE supplier_payments
        SET status = 'processed', processed_at = NOW(),
            gl_journal_entry_id = ${journalEntry.id}::UUID
        WHERE id = ${id} AND company_id = ${companyId}::UUID
        RETURNING *
      `) as Row[];

      return rows[0] as Row;
    });

    log.info('Processed supplier payment', { id, journalEntryId: journalEntry.id }, 'accounting');
    return mapPaymentRow(updated);
  } catch (err) {
    log.error('Failed to process supplier payment', { id, error: err }, 'accounting');
    throw err;
  }
}

export async function approveSupplierPayment(companyId: string, 
  id: string,
  userId: string
): Promise<SupplierPayment> {
  try {
    const payment = await getSupplierPaymentById(companyId, id);
    if (!payment) throw new Error(`Payment ${id} not found`);
    if (payment.status !== 'draft') throw new Error(`Cannot approve payment with status: ${payment.status}`);

    const rows = (await sql`
      UPDATE supplier_payments
      SET status = 'approved', approved_by = ${userId}::UUID, approved_at = NOW()
      WHERE id = ${id} AND company_id = ${companyId}::UUID
      RETURNING *
    `) as Row[];

    return mapPaymentRow(rows[0]!);
  } catch (err) {
    log.error('Failed to approve supplier payment', { id, error: err }, 'accounting');
    throw err;
  }
}

function mapPaymentRow(row: Row): SupplierPayment {
  return {
    id: String(row.id),
    paymentNumber: row.payment_number ? String(row.payment_number) : '',
    supplierId: String(row.supplier_id),
    paymentDate: String(row.payment_date),
    totalAmount: Number(row.total_amount),
    paymentMethod: String(row.payment_method) as SupplierPayment['paymentMethod'],
    bankAccountId: row.bank_account_id ? String(row.bank_account_id) : undefined,
    reference: row.reference ? String(row.reference) : undefined,
    description: row.description ? String(row.description) : undefined,
    status: String(row.status) as SupplierPayment['status'],
    glJournalEntryId: row.gl_journal_entry_id ? String(row.gl_journal_entry_id) : undefined,
    batchId: row.batch_id ? String(row.batch_id) : undefined,
    createdBy: String(row.created_by),
    approvedBy: row.approved_by ? String(row.approved_by) : undefined,
    approvedAt: row.approved_at ? String(row.approved_at) : undefined,
    processedAt: row.processed_at ? String(row.processed_at) : undefined,
    createdAt: String(row.created_at),
    updatedAt: String(row.updated_at),
    supplierName: row.supplier_name ? String(row.supplier_name) : undefined,
  };
}

function mapAllocationRow(row: Row): PaymentAllocation {
  return {
    id: String(row.id),
    paymentId: String(row.payment_id),
    invoiceId: String(row.invoice_id),
    amountAllocated: Number(row.amount_allocated),
    createdAt: String(row.created_at),
    invoiceNumber: row.invoice_number ? String(row.invoice_number) : undefined,
  };
}

export async function approveAdjustment(companyId: string, id: string, userId: string): Promise<AccountingAdjustment> {
  const adjRows = (await sql`SELECT * FROM accounting_adjustments WHERE id = ${id} AND company_id = ${companyId}`) as Row[];
  if (!adjRows[0]) throw new Error('Adjustment not found');
  if (adjRows[0].status !== 'draft') throw new Error('Adjustment is not in draft status');

  const adj = adjRows[0];
  const amount = Number(adj.amount);
  const isCustomer = adj.entity_type === 'customer';
  const isDebit = adj.adjustment_type === 'debit';

  // GL accounts
  const balanceAccount = isCustomer
    ? await getSystemAccount('receivable')
    : await getSystemAccount('payable');
  const offsetAccount = isDebit
    ? await getSystemAccount('other_income')
    : await getSystemAccount('admin_expense');

  const lines: JournalLineInput[] = isDebit
    ? [
        { glAccountId: balanceAccount.id, debit: amount, credit: 0,
          description: `Adjustment ${adj.adjustment_number}` },
        { glAccountId: offsetAccount.id, debit: 0, credit: amount,
          description: `Adjustment ${adj.adjustment_number}` },
      ]
    : [
        { glAccountId: offsetAccount.id, debit: amount, credit: 0,
          description: `Adjustment ${adj.adjustment_number}` },
        { glAccountId: balanceAccount.id, debit: 0, credit: amount,
          description: `Adjustment ${adj.adjustment_number}` },
      ];

  const je = await createJournalEntry('', {
    entryDate: String(adj.adjustment_date),
    description: `${isCustomer ? 'Customer' : 'Supplier'} adjustment ${adj.adjustment_number}`,
    source: 'auto_adjustment',
    sourceDocumentId: id,
    lines,
  }, userId);
  await postJournalEntry(companyId, je.id, userId);

  const updated = (await sql`
    UPDATE accounting_adjustments
    SET status = 'approved', approved_by = ${userId}::UUID, approved_at = NOW(),
        gl_journal_entry_id = ${je.id}::UUID
    WHERE id = ${id} AND company_id = ${companyId} RETURNING *
  `) as Row[];

  log.info('Approved adjustment', { id, journalEntryId: je.id }, 'accounting');
  return mapRow(updated[0]!);
}

export async function cancelAdjustment(companyId: string, id: string): Promise<void> {
  await sql`UPDATE accounting_adjustments SET status = 'cancelled' WHERE id = ${id} AND company_id = ${companyId} AND status = 'draft'`;

export async function approveWriteOff(companyId: string, id: string, userId: string): Promise<CustomerWriteOff> {
  const woRows = (await sql`
    SELECT wo.*, ci.invoice_number FROM customer_write_offs wo
    LEFT JOIN customer_invoices ci ON ci.id = wo.invoice_id
    WHERE wo.id = ${id} AND wo.company_id = ${companyId}
  `) as Row[];
  if (!woRows[0]) throw new Error('Write-off not found');
  if (woRows[0].status !== 'draft') throw new Error('Write-off is not in draft status');

  const wo = woRows[0];
  const amount = Number(wo.amount);

  // GL: DR Bad Debts Expense, CR Accounts Receivable
  const expenseAccount = await getSystemAccount('admin_expense');
  const arAccount = await getSystemAccount('receivable');

  const lines: JournalLineInput[] = [
    { glAccountId: expenseAccount.id, debit: amount, credit: 0,
      description: `Bad debt write-off: ${wo.invoice_number}` },
    { glAccountId: arAccount.id, debit: 0, credit: amount,
      description: `Write-off AR: ${wo.invoice_number}` },
  ];

  const je = await createJournalEntry('', {
    entryDate: String(wo.write_off_date),
    description: `Write-off ${wo.write_off_number} — ${wo.invoice_number}`,
    source: 'auto_write_off',
    sourceDocumentId: id,
    lines,
  }, userId);
  await postJournalEntry(companyId, je.id, userId);

  // Update invoice balance
  await sql`
    UPDATE customer_invoices
    SET amount_paid = amount_paid + ${amount},
        status = CASE WHEN (total_amount - amount_paid - ${amount}) <= 0.01 THEN 'paid' ELSE status END
    WHERE id = ${wo.invoice_id}::UUID
  `;

  const updated = (await sql`
    UPDATE customer_write_offs
    SET status = 'approved', approved_by = ${userId}::UUID, approved_at = NOW(),
        gl_journal_entry_id = ${je.id}::UUID
    WHERE id = ${id} AND company_id = ${companyId} RETURNING *
  `) as Row[];

  log.info('Approved write-off', { id, journalEntryId: je.id }, 'accounting');
  return mapRow(updated[0]!);
}

export async function cancelWriteOff(companyId: string, id: string): Promise<void> {
  await sql`UPDATE customer_write_offs SET status = 'cancelled' WHERE id = ${id} AND company_id = ${companyId} AND status = 'draft'`;
}

