/**
 * PRD-060: FibreFlow Accounting Module — Phase 3
 * Credit Note Service (Customer & Supplier)
 */

import { sql, withTransaction } from '@/lib/neon';
import { log } from '@/lib/logger';
import { createJournalEntry, postJournalEntry, reverseJournalEntry } from './journalEntryService';
import { getSystemAccount } from './systemAccountResolver';
import type { CreditNote, CreditNoteCreateInput, CreditNoteStatus } from '../types/ar.types';
import type { JournalLineInput } from '../types/gl.types';

interface CreditNoteFilters {
  type?: 'customer' | 'supplier';
  status?: CreditNoteStatus;
  limit?: number;
  offset?: number;
}

export async function getCreditNotes(companyId: string, filters?: CreditNoteFilters): Promise<{
  creditNotes: CreditNote[];
  total: number;
}> {
  try {
    // TODO: Apply pagination cap to all list endpoints (M16)
    const limit = Math.min(filters?.limit || 50, 200);
    const offset = filters?.offset || 0;
    let rows: Record<string, unknown>[];
    let countRows: Record<string, unknown>[];

    if (filters?.type) {
      rows = (await sql`
        SELECT cn.*, c.name AS client_name, COALESCE(s.company_name, s.name) AS supplier_name,
          COALESCE(ci.invoice_number, si.invoice_number) AS invoice_number
        FROM credit_notes cn
        LEFT JOIN customers c ON c.id = cn.client_id
        LEFT JOIN suppliers s ON s.id = cn.supplier_id
        LEFT JOIN customer_invoices ci ON ci.id = cn.customer_invoice_id
        LEFT JOIN supplier_invoices si ON si.id = cn.supplier_invoice_id
        WHERE cn.company_id = ${companyId} AND cn.type = ${filters.type}
        ORDER BY cn.credit_date DESC LIMIT ${limit} OFFSET ${offset}
      `) as Record<string, unknown>[];
      countRows = (await sql`
        SELECT COUNT(*) AS cnt FROM credit_notes WHERE company_id = ${companyId} AND type = ${filters.type}
      `) as Record<string, unknown>[];
    } else {
      rows = (await sql`
        SELECT cn.*, c.name AS client_name, COALESCE(s.company_name, s.name) AS supplier_name,
          COALESCE(ci.invoice_number, si.invoice_number) AS invoice_number
        FROM credit_notes cn
        LEFT JOIN customers c ON c.id = cn.client_id
        LEFT JOIN suppliers s ON s.id = cn.supplier_id
        LEFT JOIN customer_invoices ci ON ci.id = cn.customer_invoice_id
        LEFT JOIN supplier_invoices si ON si.id = cn.supplier_invoice_id
        WHERE cn.company_id = ${companyId}
        ORDER BY cn.credit_date DESC LIMIT ${limit} OFFSET ${offset}
      `) as Record<string, unknown>[];
      countRows = (await sql`SELECT COUNT(*) AS cnt FROM credit_notes WHERE company_id = ${companyId}`) as Record<string, unknown>[];
    }

    return { creditNotes: rows.map(mapRow), total: Number(countRows[0]!.cnt) };
  } catch (err) {
    log.error('Failed to get credit notes', { error: err }, 'accounting');
    throw err;
  }
}

export async function getCreditNoteById(companyId: string, id: string): Promise<CreditNote | null> {
  const rows = (await sql`
    SELECT cn.*, c.name AS client_name, COALESCE(s.company_name, s.name) AS supplier_name,
      COALESCE(ci.invoice_number, si.invoice_number) AS invoice_number
    FROM credit_notes cn
    LEFT JOIN customers c ON c.id = cn.client_id
    LEFT JOIN suppliers s ON s.id = cn.supplier_id
    LEFT JOIN customer_invoices ci ON ci.id = cn.customer_invoice_id
    LEFT JOIN supplier_invoices si ON si.id = cn.supplier_invoice_id
    WHERE cn.id = ${id}::UUID AND cn.company_id = ${companyId}
  `) as Record<string, unknown>[];
  return rows.length > 0 ? mapRow(rows[0]!) : null;
}

export async function createCreditNote(companyId: string, 
  input: CreditNoteCreateInput,
  userId: string
): Promise<CreditNote> {
  try {
    const taxRate = input.taxRate ?? 15;
    const taxAmount = Math.round(input.subtotal * taxRate / 100 * 100) / 100;
    const totalAmount = input.subtotal + taxAmount;

    const rows = (await sql`
      INSERT INTO credit_notes (
        type, client_id, customer_invoice_id, supplier_id, supplier_invoice_id,
        credit_date, reason, subtotal, tax_rate, tax_amount, total_amount,
        project_id, created_by
      ) VALUES (
        ${input.type}, ${input.clientId || null}, ${input.customerInvoiceId || null},
        ${input.supplierId ? Number(input.supplierId) : null},
        ${input.supplierInvoiceId || null},
        ${input.creditDate}, ${input.reason || null},
        ${input.subtotal}, ${taxRate}, ${taxAmount}, ${totalAmount},
        ${input.projectId || null}, ${userId}::UUID
      ) RETURNING *
    `) as Record<string, unknown>[];

    log.info('Created credit note', { id: String(rows[0]!.id), type: input.type }, 'accounting');
    return mapRow(rows[0]!);
  } catch (err) {
    log.error('Failed to create credit note', { error: err }, 'accounting');
    throw err;
  }
}

export async function approveCreditNote(companyId: string, id: string, userId: string): Promise<CreditNote> {
  try {
    const cnRows = (await sql`SELECT * FROM credit_notes WHERE id = ${id} AND company_id = ${companyId}`) as Record<string, unknown>[];
    if (cnRows.length === 0) throw new Error(`Credit note ${id} not found`);
    const cn = cnRows[0]!;
    if (String(cn.status) !== 'draft') throw new Error(`Cannot approve credit note with status: ${cn.status}`);

    let lines: JournalLineInput[];

    if (String(cn.type) === 'customer') {
      // Customer CN: DR Revenue, CR Accounts Receivable
      const revenueAccount = await getSystemAccount('default_revenue');
      const arAccount = await getSystemAccount('receivable');
      const vatAccount = await getSystemAccount('vat_output');

      lines = [
        { glAccountId: revenueAccount.id, debit: Number(cn.subtotal), credit: 0,
          description: `Credit note ${cn.credit_note_number}` },
      ];
      if (Number(cn.tax_amount) > 0 && vatAccount) {
        lines.push({ glAccountId: vatAccount.id, debit: Number(cn.tax_amount), credit: 0,
          description: `VAT reversal: ${cn.credit_note_number}` });
      }
      lines.push({ glAccountId: arAccount.id, debit: 0, credit: Number(cn.total_amount),
        description: `AR credit: ${cn.credit_note_number}` });
    } else {
      // Supplier CN: DR Accounts Payable, CR Expense
      const apAccount = await getSystemAccount('payable');
      const expenseAccount = await getSystemAccount('default_expense');
      const vatAccount = await getSystemAccount('vat_input');

      lines = [
        { glAccountId: apAccount.id, debit: Number(cn.total_amount), credit: 0,
          description: `AP credit: ${cn.credit_note_number}` },
      ];
      if (Number(cn.tax_amount) > 0 && vatAccount) {
        lines.push({ glAccountId: vatAccount.id, debit: 0, credit: Number(cn.tax_amount),
          description: `VAT reversal: ${cn.credit_note_number}` });
      }
      lines.push({ glAccountId: expenseAccount.id, debit: 0, credit: Number(cn.subtotal),
        description: `Expense credit: ${cn.credit_note_number}` });
    }

    const je = await createJournalEntry(companyId, {
      entryDate: String(cn.credit_date),
      description: `Credit note ${cn.credit_note_number}`,
      source: 'auto_credit_note',
      sourceDocumentId: id,
      lines,
    }, userId);
    await postJournalEntry(companyId, je.id, userId);

    // Update invoice balance and credit note status atomically
    const updated = await withTransaction(async (tx) => {
      if (String(cn.type) === 'customer' && cn.customer_invoice_id) {
        await tx`
          UPDATE customer_invoices SET amount_paid = amount_paid + ${Number(cn.total_amount)}
          WHERE id = ${cn.customer_invoice_id}::UUID
        `;
      } else if (String(cn.type) === 'supplier' && cn.supplier_invoice_id) {
        await tx`
          UPDATE supplier_invoices SET amount_paid = amount_paid + ${Number(cn.total_amount)}
          WHERE id = ${cn.supplier_invoice_id}::UUID
        `;
      }

      const rows = (await tx`
        UPDATE credit_notes SET status = 'approved', approved_by = ${userId}::UUID,
          approved_at = NOW(), gl_journal_entry_id = ${je.id}::UUID
        WHERE id = ${id} RETURNING *
      `) as Record<string, unknown>[];

      return rows[0] as Record<string, unknown>;
    });

    log.info('Approved credit note', { id, journalEntryId: je.id }, 'accounting');
    return mapRow(updated);
  } catch (err) {
    log.error('Failed to approve credit note', { id, error: err }, 'accounting');
    throw err;
  }
}

export async function cancelCreditNote(companyId: string, 
  id: string,
  userId: string,
  reason?: string
): Promise<CreditNote> {
  try {
    const cnRows = (await sql`SELECT * FROM credit_notes WHERE id = ${id} AND company_id = ${companyId}`) as Record<string, unknown>[];
    if (cnRows.length === 0) throw new Error(`Credit note ${id} not found`);
    const cn = cnRows[0]!;
    if (String(cn.status) !== 'approved') {
      throw new Error(`Cannot cancel credit note with status: ${cn.status}`);
    }

    // Reverse GL journal entry — manages its own transaction, must stay outside
    if (cn.gl_journal_entry_id) {
      await reverseJournalEntry('', String(cn.gl_journal_entry_id), userId);
    }

    // Atomically reverse invoice balance adjustments and mark credit note cancelled
    const updated = await withTransaction(async (tx) => {
      if (String(cn.type) === 'customer' && cn.customer_invoice_id) {
        await tx`
          UPDATE customer_invoices
          SET amount_paid = GREATEST(0, amount_paid - ${Number(cn.total_amount)})
          WHERE id = ${cn.customer_invoice_id}::UUID
        `;
        await tx`
          UPDATE customer_invoices SET status = CASE
            WHEN amount_paid <= 0.01 THEN 'approved'
            WHEN amount_paid < total_amount THEN 'partially_paid'
            ELSE status
          END
          WHERE id = ${cn.customer_invoice_id}::UUID
        `;
      } else if (String(cn.type) === 'supplier' && cn.supplier_invoice_id) {
        await tx`
          UPDATE supplier_invoices
          SET amount_paid = GREATEST(0, amount_paid - ${Number(cn.total_amount)})
          WHERE id = ${cn.supplier_invoice_id}::UUID
        `;
      }

      const rows = (await tx`
        UPDATE credit_notes
        SET status = 'cancelled', cancelled_by = ${userId}::UUID,
            cancelled_at = NOW(), cancel_reason = ${reason || null}
        WHERE id = ${id} RETURNING *
      `) as Record<string, unknown>[];

      return rows[0] as Record<string, unknown>;
    });

    log.info('Cancelled credit note', { id, reason }, 'accounting');
    return mapRow(updated);
  } catch (err) {
    log.error('Failed to cancel credit note', { id, error: err }, 'accounting');
    throw err;
  }
}

function mapRow(row: Record<string, unknown>): CreditNote {
  return {
    id: String(row.id),
    creditNoteNumber: row.credit_note_number ? String(row.credit_note_number) : '',
    type: String(row.type) as CreditNote['type'],
    clientId: row.client_id ? String(row.client_id) : undefined,
    customerInvoiceId: row.customer_invoice_id ? String(row.customer_invoice_id) : undefined,
    supplierId: row.supplier_id ? String(row.supplier_id) : undefined,
    supplierInvoiceId: row.supplier_invoice_id ? String(row.supplier_invoice_id) : undefined,
    creditDate: String(row.credit_date),
    reason: row.reason ? String(row.reason) : undefined,
    subtotal: Number(row.subtotal),
    taxRate: Number(row.tax_rate),
    taxAmount: Number(row.tax_amount),
    totalAmount: Number(row.total_amount),
    status: String(row.status) as CreditNoteStatus,
    glJournalEntryId: row.gl_journal_entry_id ? String(row.gl_journal_entry_id) : undefined,
    projectId: row.project_id ? String(row.project_id) : undefined,
    createdBy: String(row.created_by),
    approvedBy: row.approved_by ? String(row.approved_by) : undefined,
    approvedAt: row.approved_at ? String(row.approved_at) : undefined,
    createdAt: String(row.created_at),
    updatedAt: String(row.updated_at),
    clientName: row.client_name ? String(row.client_name) : undefined,
    supplierName: row.supplier_name ? String(row.supplier_name) : undefined,
    invoiceNumber: row.invoice_number ? String(row.invoice_number) : undefined,
  };
}

/**
 * Email Service
 * Generic email sending via SMTP (nodemailer) + invoice-specific helpers
 * Gracefully handles missing SMTP configuration
 */

import { log } from '@/lib/logger';
import { sql } from '@/lib/neon';
import { generateInvoicePdf } from './invoicePdfService';
import { inviteEmailHtml, invoiceEmailHtml } from '@/lib/email-templates';
import type { InviteEmailData, InvoiceEmailData } from '@/lib/email-templates';
type Row = Record<string, unknown>;


// ─── Types ──────────────────────────────────────────────────────────────────

export interface EmailAttachment {
  filename: string;
  content: Buffer;
  contentType: string;
}

export interface EmailOptions {
  to: string | string[];
  subject: string;
  html: string;
  attachments?: EmailAttachment[];
}

export interface EmailResult {
  success: boolean;
  messageId?: string;
  error?: string;
}

// ─── SMTP Configuration ────────────────────────────────────────────────────

interface SmtpConfig {
  host: string;
  port: number;
  user: string;
  pass: string;
  from: string;
}

function getSmtpConfig(): SmtpConfig | null {
  const host = process.env.SMTP_HOST;
  const port = process.env.SMTP_PORT;
  const user = process.env.SMTP_USER;
  const pass = process.env.SMTP_PASS;
  const from = process.env.SMTP_FROM || 'accounts@isaflow.co.za';

  if (!host || !user || !pass) {
    return null;
  }

  return {
    host,
    port: port ? parseInt(port, 10) : 587,
    user,
    pass,
    from,
  };
}

// ─── Generic Email Sender ───────────────────────────────────────────────────

export async function sendEmail(options: EmailOptions): Promise<EmailResult> {
  const config = getSmtpConfig();

  if (!config) {
    log.warn('SMTP not configured. Set SMTP_HOST, SMTP_USER, SMTP_PASS environment variables.', {}, 'emailService');
    return { success: false, error: 'SMTP not configured' };
  }

  try {
    // Dynamic import to avoid loading nodemailer when not needed
    const nodemailer = await import('nodemailer');

    const transporter = nodemailer.createTransport({
      host: config.host,
      port: config.port,
      secure: config.port === 465,
      auth: {
        user: config.user,
        pass: config.pass,
      },
      tls: {
        // Allow self-signed certs in dev; enforce TLS validation in production
        rejectUnauthorized: process.env.NODE_ENV === 'production',
      },
    });

    const recipients = Array.isArray(options.to) ? options.to.join(', ') : options.to;

    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const mailOptions: any = {
      from: config.from,
      to: recipients,
      subject: options.subject,
      html: options.html,
      attachments: options.attachments?.map((att) => ({
        filename: att.filename,
        content: att.content,
        contentType: att.contentType,
      })),
    };

    const info = await transporter.sendMail(mailOptions);

    log.info('Email sent', {
      messageId: info.messageId,
      to: recipients,
      subject: options.subject,
    }, 'emailService');

    return {
      success: true,
      messageId: info.messageId,
    };
  } catch (err) {
    const message = err instanceof Error ? err.message : 'Unknown email error';
    log.error('Failed to send email', { error: message, to: options.to }, 'emailService');
    return { success: false, error: message };
  }
}

// ─── Invoice Email ──────────────────────────────────────────────────────────

const fmtZAR = (amount: number): string =>
  'R ' + Number(amount).toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ',');

const fmtDate = (d: string | null | undefined): string => {
  if (!d) return '—';
  const parts = d.split('T')[0]?.split('-') ?? [];
  if (parts.length === 3) return `${parts[2]}/${parts[1]}/${parts[0]}`;
  return d;
};

export async function sendInvoiceEmail(companyId: string, 
  invoiceId: string,
  recipientEmail: string
): Promise<EmailResult> {
  // Fetch invoice summary for email body
  const invoiceRows = (await sql`
    SELECT ci.invoice_number, ci.invoice_date, ci.due_date,
           ci.total_amount, ci.amount_paid,
           c.name AS client_name
    FROM customer_invoices ci
    LEFT JOIN customers c ON c.id = ci.client_id
    WHERE ci.id = ${invoiceId}::UUID
  `) as Row[];

  if (invoiceRows.length === 0) {
    throw new Error(`Invoice not found: ${invoiceId}`);
  }

  const invoiceRow = invoiceRows[0]!;
  const invoice = {
    invoice_number: String(invoiceRow.invoice_number ?? ''),
    invoice_date: invoiceRow.invoice_date != null ? String(invoiceRow.invoice_date) : null,
    due_date: invoiceRow.due_date != null ? String(invoiceRow.due_date) : null,
    total_amount: Number(invoiceRow.total_amount),
    amount_paid: Number(invoiceRow.amount_paid ?? 0),
    client_name: invoiceRow.client_name != null ? String(invoiceRow.client_name) : null,
  };
  const balance = invoice.total_amount - invoice.amount_paid;
  const companyName = 'IsaFlow';

  // Generate PDF
  const pdfBuffer = await generateInvoicePdf('', invoiceId);

  // Build email HTML (table-based for email client compatibility)
  const invoiceData: InvoiceEmailData = {
    invoiceNumber: invoice.invoice_number,
    clientName: invoice.client_name || 'Valued Customer',
    invoiceDate: fmtDate(invoice.invoice_date),
    dueDate: fmtDate(invoice.due_date),
    totalAmount: fmtZAR(invoice.total_amount),
    balanceDue: fmtZAR(balance),
    companyName,
  };
  const html = invoiceEmailHtml(invoiceData);

  // Send email with PDF attachment
  const result = await sendEmail({
    to: recipientEmail,
    subject: `Invoice ${invoice.invoice_number} from ${companyName}`,
    html,
    attachments: [
      {
        filename: `${invoice.invoice_number || 'Invoice'}.pdf`,
        content: pdfBuffer,
        contentType: 'application/pdf',
      },
    ],
  });

  // Update tracking fields on the invoice
  if (result.success) {
    await sql`
      UPDATE customer_invoices
      SET email_sent_at = NOW(),
          email_sent_to = ${recipientEmail},
          email_message_id = ${result.messageId || null},
          updated_at = NOW()
      WHERE id = ${invoiceId}::UUID
    `;

    log.info('Invoice email sent and tracked', {
      invoiceId,
      recipientEmail,
      messageId: result.messageId,
    }, 'emailService');
  }

  return result;
}

// ─── Invite Email ───────────────────────────────────────────────────────────

export interface InviteEmailOptions {
  recipientEmail: string;
  inviteToken: string;
  companyName: string;
  inviterName: string;
  role: string;
  baseUrl: string;
}

export async function sendInviteEmail(options: InviteEmailOptions): Promise<EmailResult> {
  const inviteUrl = `${options.baseUrl}/invite/${options.inviteToken}`;

  const inviteData: InviteEmailData = {
    inviterName: options.inviterName,
    companyName: options.companyName,
    role: options.role,
    inviteUrl,
    recipientEmail: options.recipientEmail,
  };

  return sendEmail({
    to: options.recipientEmail,
    subject: `You've been invited to join ${options.companyName} on ISAFlow`,
    html: inviteEmailHtml(inviteData),
  });
}

/**
 * PRD-060: FibreFlow Accounting Module — Phase 4
 * Bank Reconciliation Service — reconciliation CRUD, allocation, and auto-match
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { runAutoMatch } from '../utils/autoMatch';
import { createJournalEntry, postJournalEntry } from './journalEntryService';
import { matchTransaction, fmtDate } from './bankTransactionQueryService';
import type { BankReconciliation, AutoMatchResult } from '../types/bank.types';
import type { JournalLineInput } from '../types/gl.types';

type Row = Record<string, unknown>;

// ── Reconciliation CRUD ───────────────────────────────────────────────────────

export async function getReconciliations(
  companyId: string, bankAccountId?: string
): Promise<BankReconciliation[]> {
  try {
    const rows = bankAccountId
      ? (await sql`
          SELECT br.*, ga.account_name AS bank_account_name,
            (SELECT COUNT(*) FROM bank_transactions WHERE reconciliation_id = br.id AND status = 'matched') AS matched_count,
            (SELECT COUNT(*) FROM bank_transactions WHERE reconciliation_id = br.id AND status = 'imported') AS unmatched_count
          FROM bank_reconciliations br
          LEFT JOIN gl_accounts ga ON ga.id = br.bank_account_id
          WHERE br.company_id = ${companyId} AND br.bank_account_id = ${bankAccountId}::UUID
          ORDER BY br.statement_date DESC`) as Row[]
      : (await sql`
          SELECT br.*, ga.account_name AS bank_account_name,
            (SELECT COUNT(*) FROM bank_transactions WHERE reconciliation_id = br.id AND status = 'matched') AS matched_count,
            (SELECT COUNT(*) FROM bank_transactions WHERE reconciliation_id = br.id AND status = 'imported') AS unmatched_count
          FROM bank_reconciliations br
          LEFT JOIN gl_accounts ga ON ga.id = br.bank_account_id
          WHERE br.company_id = ${companyId}
          ORDER BY br.statement_date DESC`) as Row[];
    return rows.map(mapReconRow);
  } catch (err) {
    log.error('Failed to get reconciliations', { error: err }, 'accounting');
    throw err;
  }
}

export async function getReconciliationById(
  companyId: string, id: string
): Promise<BankReconciliation | null> {
  try {
    const rows = (await sql`
      SELECT br.*, ga.account_name AS bank_account_name,
        (SELECT COUNT(*) FROM bank_transactions WHERE reconciliation_id = br.id AND status = 'matched') AS matched_count,
        (SELECT COUNT(*) FROM bank_transactions WHERE reconciliation_id = br.id AND status = 'imported') AS unmatched_count
      FROM bank_reconciliations br
      LEFT JOIN gl_accounts ga ON ga.id = br.bank_account_id
      WHERE br.id = ${id}::UUID AND br.company_id = ${companyId}`) as Row[];
    return rows.length > 0 ? mapReconRow(rows[0]!) : null;
  } catch (err) {
    log.error('Failed to get reconciliation', { id, error: err }, 'accounting');
    throw err;
  }
}

export async function startReconciliation(
  companyId: string, bankAccountId: string, statementDate: string,
  statementBalance: number, userId: string
): Promise<BankReconciliation> {
  try {
    const balRows = (await sql`
      SELECT COALESCE(SUM(jl.debit) - SUM(jl.credit), 0) AS gl_balance
      FROM gl_journal_lines jl
      JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
      WHERE jl.gl_account_id = ${bankAccountId}::UUID
        AND je.status = 'posted' AND je.entry_date <= ${statementDate}`) as Row[];
    const glBalance = Number(balRows[0]!.gl_balance);
    const rows = (await sql`
      INSERT INTO bank_reconciliations (
        company_id, bank_account_id, statement_date, statement_balance, gl_balance,
        reconciled_balance, started_by
      ) VALUES (
        ${companyId}, ${bankAccountId}::UUID, ${statementDate}, ${statementBalance},
        ${glBalance}, ${glBalance}, ${userId}::UUID
      ) RETURNING *`) as Row[];
    await sql`
      UPDATE bank_transactions SET reconciliation_id = ${rows[0]!.id}::UUID
      WHERE bank_account_id = ${bankAccountId}::UUID
        AND status = 'imported' AND reconciliation_id IS NULL`;
    log.info('Started bank reconciliation', {
      id: String(rows[0]!.id), bankAccountId, statementBalance, glBalance,
    }, 'accounting');
    return mapReconRow(rows[0]!);
  } catch (err) {
    log.error('Failed to start reconciliation', { error: err }, 'accounting');
    throw err;
  }
}

export async function completeReconciliation(
  companyId: string, id: string, userId: string
): Promise<BankReconciliation> {
  try {
    const recon = await getReconciliationById(companyId, id);
    if (!recon) throw new Error(`Reconciliation ${id} not found`);
    if (recon.status === 'completed') throw new Error('Reconciliation already completed');
    if (Math.abs(recon.difference) > 0.01) {
      throw new Error(`Cannot complete: difference is R${recon.difference.toFixed(2)} (must be R0.00)`);
    }
    await sql`UPDATE bank_transactions SET status = 'reconciled'
      WHERE reconciliation_id = ${id}::UUID AND status = 'matched'`;
    const rows = (await sql`
      UPDATE bank_reconciliations
      SET status = 'completed', completed_by = ${userId}::UUID, completed_at = NOW()
      WHERE id = ${id}::UUID AND company_id = ${companyId} RETURNING *`) as Row[];
    log.info('Completed bank reconciliation', { id }, 'accounting');
    return mapReconRow(rows[0]!);
  } catch (err) {
    log.error('Failed to complete reconciliation', { id, error: err }, 'accounting');
    throw err;
  }
}

export async function createAdjustmentEntry(
  companyId: string, reconciliationId: string, bankAccountId: string,
  contraAccountId: string, amount: number, description: string, userId: string
): Promise<string> {
  try {
    const lines: JournalLineInput[] = amount > 0
      ? [{ glAccountId: bankAccountId, debit: amount, credit: 0, description },
         { glAccountId: contraAccountId, debit: 0, credit: amount, description }]
      : [{ glAccountId: contraAccountId, debit: Math.abs(amount), credit: 0, description },
         { glAccountId: bankAccountId, debit: 0, credit: Math.abs(amount), description }];
    const recon = await getReconciliationById(companyId, reconciliationId);
    if (!recon) throw new Error(`Reconciliation ${reconciliationId} not found`);
    const je = await createJournalEntry(companyId, {
      entryDate: recon.statementDate,
      description: `Bank recon adjustment: ${description}`,
      source: 'auto_bank_recon', sourceDocumentId: reconciliationId, lines,
    }, userId);
    await postJournalEntry(companyId, je.id, userId);
    await updateReconciledBalance(reconciliationId);
    log.info('Created adjustment entry', { reconciliationId, journalEntryId: je.id }, 'accounting');
    return je.id;
  } catch (err) {
    log.error('Failed to create adjustment entry', { error: err }, 'accounting');
    throw err;
  }
}

// ── Auto-Match ────────────────────────────────────────────────────────────────

export async function autoMatchTransactions(
  companyId: string, bankAccountId: string, reconciliationId?: string
): Promise<AutoMatchResult> {
  try {
    const bankTxRows = (await sql`
      SELECT id, amount, transaction_date, reference, description
      FROM bank_transactions
      WHERE bank_account_id = ${bankAccountId}::UUID AND status = 'imported'
      ORDER BY transaction_date`) as Row[];
    if (bankTxRows.length === 0) return { matched: 0, unmatched: 0, candidates: [] };
    const glRows = (await sql`
      SELECT jl.id, jl.debit, jl.credit, jl.description,
        je.entry_date, je.entry_number, je.source_document_id
      FROM gl_journal_lines jl
      JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
      WHERE jl.gl_account_id = ${bankAccountId}::UUID AND je.status = 'posted'
        AND jl.id NOT IN (
          SELECT matched_journal_line_id FROM bank_transactions
          WHERE matched_journal_line_id IS NOT NULL)
      ORDER BY je.entry_date`) as Row[];
    const bankTxs = bankTxRows.map((r: Row) => ({
      id: String(r.id), amount: Number(r.amount), transactionDate: String(r.transaction_date),
      reference: r.reference ? String(r.reference) : undefined,
      description: r.description ? String(r.description) : undefined,
    }));
    const glLines = glRows.map((r: Row) => ({
      id: String(r.id), debit: Number(r.debit), credit: Number(r.credit),
      description: r.description ? String(r.description) : undefined,
      entryDate: String(r.entry_date),
      entryNumber: r.entry_number ? String(r.entry_number) : undefined,
      sourceDocumentId: r.source_document_id ? String(r.source_document_id) : undefined,
    }));
    const result = runAutoMatch(bankTxs, glLines);
    let matchedCount = 0;
    for (const match of result.matches) {
      if (match.confidence >= 0.9) {
        await matchTransaction('', match.bankTransactionId, match.journalLineId, reconciliationId);
        matchedCount++;
      }
    }
    const lowConfidence = result.matches.filter(m => m.confidence < 0.9);
    log.info('Auto-match completed', {
      bankAccountId, autoMatched: matchedCount,
      candidates: lowConfidence.length, unmatched: result.unmatched.length,
    }, 'accounting');
    return { matched: matchedCount, unmatched: result.unmatched.length, candidates: lowConfidence };
  } catch (err) {
    log.error('Failed to auto-match transactions', { error: err }, 'accounting');
    throw err;
  }
}

// ── Helpers ───────────────────────────────────────────────────────────────────

export async function updateReconciledBalance(reconciliationId: string): Promise<void> {
  const sumRows = (await sql`
    SELECT COALESCE(SUM(amount), 0) AS matched_total FROM bank_transactions
    WHERE reconciliation_id = ${reconciliationId}::UUID AND status IN ('matched', 'reconciled')`) as Row[];
  const reconRows = (await sql`
    SELECT gl_balance FROM bank_reconciliations WHERE id = ${reconciliationId}::UUID`) as Row[];
  if (reconRows.length > 0) {
    const reconciledBalance = Number(reconRows[0]!.gl_balance) + Number(sumRows[0]!.matched_total);
    await sql`UPDATE bank_reconciliations SET reconciled_balance = ${reconciledBalance}
      WHERE id = ${reconciliationId}::UUID`;
  }
}

function mapReconRow(row: Row): BankReconciliation {
  return {
    id: String(row.id),
    bankAccountId: String(row.bank_account_id),
    statementDate: fmtDate(row.statement_date),
    statementBalance: Number(row.statement_balance),
    glBalance: Number(row.gl_balance),
    reconciledBalance: Number(row.reconciled_balance),
    difference: Number(row.difference),
    status: String(row.status) as BankReconciliation['status'],
    startedBy: String(row.started_by),
    startedAt: String(row.started_at),
    completedBy: row.completed_by ? String(row.completed_by) : undefined,
    completedAt: row.completed_at ? String(row.completed_at) : undefined,
    notes: row.notes ? String(row.notes) : undefined,
    createdAt: String(row.created_at),
    updatedAt: String(row.updated_at),
    bankAccountName: row.bank_account_name ? String(row.bank_account_name) : undefined,
    matchedCount: row.matched_count !== undefined ? Number(row.matched_count) : undefined,
    unmatchedCount: row.unmatched_count !== undefined ? Number(row.unmatched_count) : undefined,
  };
}

