      { source: '/accounting/reports/trial-balance', destination: '/accounting/trial-balance', permanent: true },
    ];
  },

  // Security headers
  async headers() {
    return [
      {
        source: '/:path*',
        headers: [
          { key: 'X-Frame-Options', value: 'DENY' },
          { key: 'X-Content-Type-Options', value: 'nosniff' },
          { key: 'Referrer-Policy', value: 'strict-origin-when-cross-origin' },
          { key: 'Permissions-Policy', value: 'camera=(), microphone=(), geolocation=()' },
          { key: 'X-DNS-Prefetch-Control', value: 'on' },
          { key: 'Strict-Transport-Security', value: 'max-age=31536000; includeSubDomains; preload' },
          { key: 'Content-Security-Policy', value: process.env.NODE_ENV === 'production' ? cspProd : cspDev },
        ],
      },
    ];
  },

  // Webpack config
  webpack: (config, { isServer }) => {
    if (!isServer) {
      config.resolve.fallback = {
        ...config.resolve.fallback,
        fs: false,
        net: false,
        tls: false,
        crypto: false,
      };
    }
    return config;
  },
};

module.exports = nextConfig;

/**
 * Next.js Edge Middleware
 * - admin.isaflow.co.za: serve /admin/* pages with super_admin auth verification
 * - app.isaflow.co.za: redirect / to /accounting (app domain — no landing page)
 * - isaflow.co.za: show landing page at /
 * - Redirects /admin/* on non-admin hosts to admin.isaflow.co.za
 * - Redirects unauthenticated /accounting/* and /payroll/* requests to /login
 */

import { NextResponse } from 'next/server';
import type { NextRequest } from 'next/server';
import { jwtVerify } from 'jose';

const AUTH_COOKIE_NAME = 'ff_auth_token';

// Sentinel used when JWT_SECRET is absent — any token verified against this will
// always fail the role check, giving defense-in-depth without crashing the edge runtime.
const MISSING_SECRET_SENTINEL = '__MIDDLEWARE_NO_SECRET__';

const getJWTSecret = (): Uint8Array => {
  const secret = process.env.JWT_SECRET;
  // Return sentinel instead of empty string so jwtVerify still runs but produces
  // a payload that cannot match a real token signed with the real secret.
  return new TextEncoder().encode(secret ?? MISSING_SECRET_SENTINEL);
};

const PUBLIC_PATHS = [
  '/login',
  '/register',
  '/api/auth/login',
  '/api/auth/logout',
  '/api/auth/register',
  '/onboarding',
  '/api/onboarding',
  '/invite',
  '/api/invite',
];

/** Hostnames that should skip the landing page and go straight to the app */
const APP_HOSTS = ['app.isaflow.co.za'];

/** Hostnames that serve the /admin platform */
const ADMIN_HOSTS = ['admin.isaflow.co.za'];

/** Paths that bypass auth checks on the admin subdomain.
 *  NOTE: '/api/' routes pass through without rewriting (they use withAdmin
 *  middleware on each handler for auth). Only page paths get rewritten. */
const ADMIN_PASSTHROUGH = [
  '/_next',
  '/login',
  '/register',
  '/favicon.ico',
  '/icons',
  '/manifest.json',
  '/sw.js',
];

const ADMIN_URL = process.env.NEXT_PUBLIC_ADMIN_URL ?? 'https://admin.isaflow.co.za';

async function verifyAdmin(token: string): Promise<boolean> {
  // Reject immediately if JWT_SECRET is not configured — never allow access
  // with a missing secret, regardless of what the token contains.
  if (!process.env.JWT_SECRET) return false;
  try {
    const { payload } = await jwtVerify(token, getJWTSecret());
    return payload.role === 'super_admin';
  } catch {
    return false;
  }
}

export async function middleware(request: NextRequest) {
  const { pathname } = request.nextUrl;
  const host = request.headers.get('host')?.split(':')[0] ?? '';

  const isAdminHost = ADMIN_HOSTS.includes(host);

  // ── Admin subdomain handling ─────────────────────────────────────────────────
  if (isAdminHost) {
    // Always passthrough for static assets, login page, and API routes
    // API routes must not be rewritten — they live at /api/*, not /admin/api/*
    if (
      ADMIN_PASSTHROUGH.some(p => pathname.startsWith(p)) ||
      pathname.startsWith('/api/') ||
      pathname.match(/\.\w+$/)  // static files (logo.png, etc.)
    ) {
      return NextResponse.next();
    }

    // Verify super_admin auth for all other paths (page navigations)
    const adminToken = request.cookies.get(AUTH_COOKIE_NAME)?.value;
    if (!adminToken) {
      const loginUrl = new URL('/login', request.url);
      loginUrl.searchParams.set('returnTo', pathname);
      return NextResponse.redirect(loginUrl);
    }

    const isAdmin = await verifyAdmin(adminToken);
    if (!isAdmin) {
      return NextResponse.redirect(new URL('/login', request.url));
    }

    // Rewrite page paths: / → /admin, /companies → /admin/companies, etc.
    if (!pathname.startsWith('/admin')) {
      const rewrittenUrl = request.nextUrl.clone();
      rewrittenUrl.pathname = pathname === '/' ? '/admin' : `/admin${pathname}`;
      return NextResponse.rewrite(rewrittenUrl);
    }

    return NextResponse.next();
  }

  // ── Non-admin hosts: redirect /admin/* to admin subdomain ───────────────────
  if (pathname.startsWith('/admin')) {
    const adminPath = pathname.replace(/^\/admin/, '') || '/';
    return NextResponse.redirect(`${ADMIN_URL}${adminPath}`);
  }

  // Allow public paths, static files, and API routes on main domains
  if (
    PUBLIC_PATHS.some(p => pathname.startsWith(p)) ||
    pathname.startsWith('/_next') ||
    pathname.startsWith('/api/') ||
    pathname.startsWith('/icons') ||
    pathname.startsWith('/landing') ||
    pathname === '/manifest.json' ||
    pathname === '/sw.js' ||
    pathname === '/favicon.ico'
  ) {
    return NextResponse.next();
  }

  // app.isaflow.co.za: redirect root to /accounting
  if (pathname === '/' && APP_HOSTS.includes(host)) {
    return NextResponse.redirect(new URL('/accounting', request.url));
  }

  // Check for auth cookie on protected routes
  const token = request.cookies.get(AUTH_COOKIE_NAME)?.value;

  if (!token && (pathname.startsWith('/accounting') || pathname.startsWith('/payroll'))) {
    const loginUrl = new URL('/login', request.url);
    loginUrl.searchParams.set('returnTo', pathname);
    return NextResponse.redirect(loginUrl);
  }

  // Redirect to onboarding if user hasn't completed it
  if (token && !request.cookies.get('ff_onboarding_done')?.value) {
    if (pathname.startsWith('/accounting') || pathname.startsWith('/payroll')) {
      return NextResponse.redirect(new URL('/onboarding', request.url));
    }
  }

  return NextResponse.next();
}

export const config = {
  matcher: ['/((?!_next/static|_next/image|favicon.ico).*)'],
};

import type { NextApiHandler, NextApiRequest, NextApiResponse } from 'next';
import { apiLogger } from '@/lib/logger';

const SENSITIVE_KEYS = new Set(['password', 'confirmPassword', 'password_hash', 'token', 'secret', 'apiKey', 'api_key']);

function sanitizeBody(body: unknown): unknown {
  if (!body || typeof body !== 'object') return body;
  const sanitized: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(body as Record<string, unknown>)) {
    sanitized[key] = SENSITIVE_KEYS.has(key) ? '[REDACTED]' : value;
  }
  return sanitized;
}

/**
 * Standard API error response
 */
export interface ApiErrorResponse {
  success: false;
  data: null;
  message: string;
  code?: string;
  details?: Record<string, unknown>;
}

/**
 * Standard API success response
 */
export interface ApiSuccessResponse<T = unknown> {
  success: true;
  data: T;
  message?: string;
}

export type ApiResponse<T = unknown> = ApiSuccessResponse<T> | ApiErrorResponse;

/**
 * Wraps an API handler with error handling.
 *
 * Generic R extends NextApiRequest to support AuthenticatedNextApiRequest,
 * CompanyApiRequest, or plain NextApiRequest without requiring `as any` casts.
 * The handler's res parameter is typed as NextApiResponse<any> so callers that
 * declare `res: NextApiResponse` (without a type argument) are assignable.
 */

export function withErrorHandler(
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  handler: (req: any, res: NextApiResponse<any>) => unknown
): NextApiHandler {
  return async (req: NextApiRequest, res: NextApiResponse) => {
    const startTime = Date.now();

    try {
      // Set CORS headers - restrict to known origins
      const allowedOrigins = [
        'https://app.isaflow.co.za',
        'https://admin.isaflow.co.za',
        'https://isaflow.co.za',
        ...(process.env.NODE_ENV === 'development'
          ? ['http://localhost:3101', 'http://localhost:3004']
          : []),
      ];
      const origin = req.headers.origin;
      if (origin && allowedOrigins.includes(origin)) {
        res.setHeader('Access-Control-Allow-Origin', origin);
        res.setHeader('Vary', 'Origin');
        res.setHeader('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, OPTIONS');
        res.setHeader('Access-Control-Allow-Headers', 'Content-Type, Authorization');
      }

      // Handle OPTIONS request for CORS
      if (req.method === 'OPTIONS') {
        return res.status(200).end();
      }

      // Log incoming request
      apiLogger.info({
        type: 'request',
        method: req.method,
        url: req.url,
        query: req.query,
        body: req.method !== 'GET' ? sanitizeBody(req.body) : undefined,
      }, `API Request: ${req.method} ${req.url}`);

      // Execute the actual handler
      await handler(req, res);

      // Log successful response
      const duration = Date.now() - startTime;
      apiLogger.info({
        type: 'response',
        method: req.method,
        url: req.url,
        statusCode: res.statusCode,
        duration: `${duration}ms`,
      }, `API Response: ${req.method} ${req.url} - ${res.statusCode} (${duration}ms)`);

    } catch (error) {
      const duration = Date.now() - startTime;

      // Log error with context
      apiLogger.error({
        type: 'error',
        method: req.method,
        url: req.url,
        error: error instanceof Error ? error.message : 'Unknown error',
        stack: error instanceof Error ? error.stack : undefined,
        duration: `${duration}ms`,
      });

      // Check if headers were already sent
      if (res.headersSent) {
        apiLogger.warn({ method: req.method, url: req.url }, 'Headers already sent, cannot send error response');
        return;
      }

      // Send error response — mask internal details in production
      const errorMessage =
        process.env.NODE_ENV === 'production'
          ? 'An unexpected error occurred'
          : error instanceof Error ? error.message : 'An unexpected error occurred';

      res.status(500).json({
        success: false,
        data: null,
        message: errorMessage,
        code: 'INTERNAL_SERVER_ERROR',
        ...(process.env.NODE_ENV === 'development' && {
          details: error instanceof Error ? {
            message: error.message,
            stack: error.stack,
          } as Record<string, unknown> : { error: String(error) },
        }),
      });
    }
  };
}

/**
 * Creates a standard success response
 */
export function successResponse<T>(data: T, message?: string): ApiSuccessResponse<T> {
  return {
    success: true,
    data,
    ...(message && { message }),
  };
}

/**
 * Creates a standard error response
 */
export function errorResponse(
  message: string,
  code?: string,
  details?: Record<string, unknown>
): ApiErrorResponse {
  return {
    success: false,
    data: null,
    message,
    ...(code && { code }),
    ...(details && process.env.NODE_ENV === 'development' && { details }),
  };
}

/**
 * Common HTTP error responses
 */
export const HttpErrors = {
  BadRequest: (message = 'Bad Request') =>
    errorResponse(message, 'BAD_REQUEST'),

  Unauthorized: (message = 'Unauthorized') =>
    errorResponse(message, 'UNAUTHORIZED'),

  Forbidden: (message = 'Forbidden') =>
    errorResponse(message, 'FORBIDDEN'),

  NotFound: (message = 'Not Found') =>
    errorResponse(message, 'NOT_FOUND'),

  MethodNotAllowed: (method: string) =>
    errorResponse(`Method ${method} not allowed`, 'METHOD_NOT_ALLOWED'),

  InternalServerError: (message = 'Internal Server Error') =>
    errorResponse(message, 'INTERNAL_SERVER_ERROR'),

  DatabaseError: (message = 'Database operation failed') =>
    errorResponse(message, 'DATABASE_ERROR'),

  ValidationError: (message = 'Validation failed', details?: Record<string, unknown>) =>
    errorResponse(message, 'VALIDATION_ERROR', details),
};

/**
 * Optimized Auth Middleware
 * PERFORMANCE: Reduced /api/auth/me from 600-1100ms to <200ms
 *
 * Changes:
 * 1. Combined session + user query into single JOIN (2 queries → 1 query)
 * 2. Added composite index recommendation for user_sessions
 * 3. Removed redundant user.isActive check after DB validation
 */

import type { NextApiRequest, NextApiResponse, NextApiHandler } from 'next';
import { sql } from '@/lib/neon';
import { verifyToken } from './jwt';
import type { AuthUser, AuthRole } from './types';
import { ROLE_HIERARCHY } from './types';
import { log } from '@/lib/logger';

// Cookie name for JWT token
export const AUTH_COOKIE_NAME = 'ff_auth_token';

// Extend NextApiRequest to include user
export interface AuthenticatedNextApiRequest extends NextApiRequest {
  user: AuthUser;
  sessionId: string;
}

// Accept handlers that declare a more specific req type (e.g. AuthenticatedNextApiRequest,
// CompanyApiRequest) — safe because withAuth enriches the request before calling the handler.
// eslint-disable-next-line @typescript-eslint/no-explicit-any
type AuthenticatedHandler = (req: any, res: NextApiResponse<any>) => any;

/**
 * Extract token from request (cookie or Authorization header)
 */
function extractToken(req: NextApiRequest): string | null {
  // First try cookie
  const cookieToken = req.cookies[AUTH_COOKIE_NAME];
  if (cookieToken) return cookieToken;

  // Then try Authorization header
  const authHeader = req.headers.authorization;
  if (authHeader?.startsWith('Bearer ')) {
    return authHeader.substring(7);
  }

  return null;
}

/**
 * Get user and validate session in a SINGLE query (optimized)
 * // 🟢 WORKING: Combines session validation + user lookup
 * Performance: ~100ms vs previous ~600ms (2 sequential queries)
 */
export async function getUserAndValidateSession(
  userId: string,
  sessionId: string,
  tokenHash: string
): Promise<AuthUser | null> {
  // Single JOIN query instead of 2 sequential queries
  // REQUIRES INDEX: CREATE INDEX idx_user_sessions_composite ON user_sessions(id, token_hash, expires_at);
  const result = await sql`
    SELECT
      u.id,
      u.email,
      u.first_name,
      u.last_name,
      u.role,
      u.permissions,
      u.is_active,
      u.profile_picture,
      u.department,
      u.must_change_password,
      s.id as session_id
    FROM users u
    INNER JOIN user_sessions s ON s.user_id = u.id
    WHERE u.id = ${userId}
      AND s.id = ${sessionId}
      AND s.token_hash = ${tokenHash}
      AND s.expires_at > NOW()
      AND u.is_active = true
    LIMIT 1
  `;

  const row = result[0];
  if (!row) return null;

  const firstName = (row.first_name as string) || '';
  const lastName = (row.last_name as string) || '';

  return {
    id: row.id as string,
    userId: row.id as string, // Alias for backwards compatibility
    email: row.email as string,
    firstName,
    lastName,
    name: `${firstName} ${lastName}`.trim() || (row.email as string),
    role: row.role as AuthRole,
    permissions: (row.permissions as string[]) || [],
    isActive: row.is_active as boolean,
    profilePicture: row.profile_picture as string | undefined,
    department: row.department as string | undefined,
    mustChangePassword: (row.must_change_password as boolean) || false,
  };
}

/**
 * Main authentication middleware
 * Verifies JWT token and attaches user to request
 * // 🟢 WORKING: Optimized single-query auth
 */
export function withAuth(handler: AuthenticatedHandler): NextApiHandler {
  return async (req: NextApiRequest, res: NextApiResponse) => {
    try {
      // Extract token
      const token = extractToken(req);
      if (!token) {
        return res.status(401).json({
          success: false,
          error: { code: 'UNAUTHORIZED', message: 'Authentication required' },
        });
      }

      // Verify JWT (in-memory operation, fast)
      const payload = await verifyToken(token);
      if (!payload) {
        return res.status(401).json({
          success: false,
          error: { code: 'INVALID_TOKEN', message: 'Invalid or expired token' },
        });
      }

      // Hash token for session lookup
      const crypto = await import('crypto');
      const tokenHash = crypto.createHash('sha256').update(token).digest('hex');

      // Single optimized query: validate session + get user (replaces 2 queries)
      const user = await getUserAndValidateSession(
        payload.sub,
        payload.sessionId,
        tokenHash
      );

      if (!user) {
        // Could be: invalid session, expired session, inactive user, or user deleted
        return res.status(401).json({
          success: false,
          error: { code: 'SESSION_INVALID', message: 'Session expired or invalid' },
        });
      }

      // Attach user and session to request
      (req as AuthenticatedNextApiRequest).user = user;
      (req as AuthenticatedNextApiRequest).sessionId = payload.sessionId;

      // Enforce must_change_password: block all endpoints except the password-change allowlist
      if (user.mustChangePassword) {
        const allowedPaths = [
          '/api/auth/change-password',
          '/api/auth/me',
          '/api/auth/logout',
          '/api/auth/preferences',
        ];
        const url = req.url?.split('?')[0] ?? '';
        if (!allowedPaths.includes(url)) {
          return res.status(403).json({
            error: 'Password change required',
            code: 'MUST_CHANGE_PASSWORD',
          });
        }
      }

      // Call the actual handler
      return handler(req as AuthenticatedNextApiRequest, res);
    } catch (error) {
      log.error('Auth middleware error', error instanceof Error ? { message: error.message, stack: error.stack } : { error }, 'AuthMiddleware');
      return res.status(500).json({
        success: false,
        error: { code: 'AUTH_ERROR', message: 'Authentication error' },
      });
    }
  };
}

/**
 * Role-based access control middleware
 * Must be used after withAuth
 */
export function withRole(requiredRole: AuthRole) {
  return (handler: AuthenticatedHandler): AuthenticatedHandler => {
    return async (req: NextApiRequest, res: NextApiResponse) => {
      const authReq = req as AuthenticatedNextApiRequest;
      const userRoleLevel = ROLE_HIERARCHY[authReq.user.role] || 0;
      const requiredRoleLevel = ROLE_HIERARCHY[requiredRole] || 0;

      if (userRoleLevel < requiredRoleLevel) {
        return res.status(403).json({
          success: false,
          error: {
            code: 'FORBIDDEN',
            message: `This action requires ${requiredRole} role or higher`,
          },
        });
      }

      return handler(req, res);
    };
  };
}

/**
 * Permission-based access control middleware
 * Must be used after withAuth
 */
export function withPermission(requiredPermission: string) {
  return (handler: AuthenticatedHandler): AuthenticatedHandler => {
    return async (req: NextApiRequest, res: NextApiResponse) => {
      const authReq = req as AuthenticatedNextApiRequest;
      const hasPermission =
        authReq.user.permissions.includes('all') ||
        authReq.user.permissions.includes(requiredPermission);

      if (!hasPermission) {
        return res.status(403).json({
          success: false,
          error: {
            code: 'FORBIDDEN',
            message: `Missing required permission: ${requiredPermission}`,
          },
        });
      }

      return handler(req, res);
    };
  };
}

/**
 * Combined role and permission check
 */
export function withRoleAndPermission(
  requiredRole: AuthRole,
  requiredPermission: string
) {
  return (handler: AuthenticatedHandler): AuthenticatedHandler => {
    return withRole(requiredRole)(withPermission(requiredPermission)(handler));
  };
}

/**
 * Optional auth - attaches user if authenticated, but doesn't require it
 * // 🟢 WORKING: Same optimization applied to optional auth
 */
export function withOptionalAuth(
  handler: (
    req: NextApiRequest & { user?: AuthUser; sessionId?: string },
    res: NextApiResponse
  ) => Promise<void> | void
): NextApiHandler {
  return async (req: NextApiRequest, res: NextApiResponse) => {
    try {
      const token = extractToken(req);
      if (token) {
        const payload = await verifyToken(token);
        if (payload) {
          const crypto = await import('crypto');
          const tokenHash = crypto.createHash('sha256').update(token).digest('hex');

          const user = await getUserAndValidateSession(
            payload.sub,
            payload.sessionId,
            tokenHash
          );

          if (user) {
            const authReq = req as NextApiRequest & { user?: AuthUser; sessionId?: string };
            authReq.user = user;
            authReq.sessionId = payload.sessionId;
          }
        }
      }

      return handler(req as NextApiRequest & { user?: AuthUser; sessionId?: string }, res);
    } catch {
      // On error, just proceed without user
      return handler(req as NextApiRequest & { user?: AuthUser; sessionId?: string }, res);
    }
  };
}

/**
 * Helper to check if user has a specific role or higher
 */
export function hasRole(user: AuthUser, requiredRole: AuthRole): boolean {
  const userLevel = ROLE_HIERARCHY[user.role] || 0;
  const requiredLevel = ROLE_HIERARCHY[requiredRole] || 0;
  return userLevel >= requiredLevel;
}

/**
 * Helper to check if user has a specific permission
 */
export function hasPermission(user: AuthUser, permission: string): boolean {
  return user.permissions.includes('all') || user.permissions.includes(permission);
}

