interface CalcInput {
  cost: number;
  salvageValue: number;
  usefulLifeYears: number;
  monthsElapsed: number;
  accumulatedDepreciation?: number;
}

export function calculateStraightLine(input: CalcInput): DepreciationResult {
  const { cost, salvageValue, usefulLifeYears, monthsElapsed, accumulatedDepreciation } = input;
  if (usefulLifeYears <= 0 || cost <= salvageValue) {
    return { monthlyAmount: 0, annualAmount: 0, annualRate: 0, method: 'straight_line', remainingMonths: 0 };
  }
  const totalMonths = usefulLifeYears * 12;
  const remainingMonths = Math.max(0, totalMonths - monthsElapsed);
  if (remainingMonths <= 0) {
    return { monthlyAmount: 0, annualAmount: 0, annualRate: 0, method: 'straight_line', remainingMonths: 0 };
  }
  const depreciableAmount = cost - salvageValue;
  const annualDep = depreciableAmount / usefulLifeYears;
  const annualRate = (annualDep / cost) * 100;
  let monthlyDep = Math.round((annualDep / 12) * 100) / 100;
  if (accumulatedDepreciation !== undefined) {
    const remaining = depreciableAmount - accumulatedDepreciation;
    if (remaining <= 0) {
      return { monthlyAmount: 0, annualAmount: 0, annualRate: Math.round(annualRate * 100) / 100, method: 'straight_line', remainingMonths: 0 };
    }
    monthlyDep = Math.min(monthlyDep, Math.round(remaining * 100) / 100);
  }
  return { monthlyAmount: monthlyDep, annualAmount: Math.round(annualDep * 100) / 100, annualRate: Math.round(annualRate * 100) / 100, method: 'straight_line', remainingMonths };
}

export function calculateReducingBalance(input: CalcInput): DepreciationResult {
  const { cost, salvageValue, usefulLifeYears, accumulatedDepreciation } = input;
  if (usefulLifeYears <= 0 || cost <= salvageValue) {
    return { monthlyAmount: 0, annualAmount: 0, annualRate: 0, method: 'reducing_balance', remainingMonths: 0 };
  }
  const rate = 2 / usefulLifeYears;
  const annualRate = rate * 100;
  const accum = accumulatedDepreciation ?? 0;
  const bookValue = cost - accum;
  const maxDepreciable = bookValue - salvageValue;
  if (maxDepreciable <= 0) {
    return { monthlyAmount: 0, annualAmount: 0, annualRate: Math.round(annualRate * 100) / 100, method: 'reducing_balance', remainingMonths: 0 };
  }
  const annualDep = bookValue * rate;
  let monthlyDep = Math.round((annualDep / 12) * 100) / 100;
  monthlyDep = Math.min(monthlyDep, Math.round(maxDepreciable * 100) / 100);
  const remainingMonths = monthlyDep > 0 ? Math.ceil(maxDepreciable / monthlyDep) : 0;
  return { monthlyAmount: monthlyDep, annualAmount: Math.round(annualDep * 100) / 100, annualRate: Math.round(annualRate * 100) / 100, method: 'reducing_balance', remainingMonths };
}

export function calculateSumOfYears(input: CalcInput): DepreciationResult {
  const { cost, salvageValue, usefulLifeYears, monthsElapsed } = input;
  if (usefulLifeYears <= 0 || cost <= salvageValue) {
    return { monthlyAmount: 0, annualAmount: 0, annualRate: 0, method: 'sum_of_years', remainingMonths: 0 };
  }
  const currentYear = Math.floor(monthsElapsed / 12) + 1;
  const totalMonths = usefulLifeYears * 12;
  const remainingMonths = Math.max(0, totalMonths - monthsElapsed);
  if (currentYear > usefulLifeYears || remainingMonths <= 0) {
    return { monthlyAmount: 0, annualAmount: 0, annualRate: 0, method: 'sum_of_years', remainingMonths: 0 };
  }
  const sumOfDigits = (usefulLifeYears * (usefulLifeYears + 1)) / 2;
  const remainingYears = usefulLifeYears - currentYear + 1;
  const fraction = remainingYears / sumOfDigits;
  const depreciableAmount = cost - salvageValue;
  const annualDep = depreciableAmount * fraction;
  const monthlyDep = Math.round((annualDep / 12) * 100) / 100;
  const annualRate = Math.round((annualDep / cost) * 100 * 100) / 100;
  return { monthlyAmount: monthlyDep, annualAmount: Math.round(annualDep * 100) / 100, annualRate, method: 'sum_of_years', remainingMonths };
}

export function calculateDepreciation(input: DepreciationInput): DepreciationResult {
  const calcInput: CalcInput = { cost: input.cost, salvageValue: input.salvageValue, usefulLifeYears: input.usefulLifeYears, monthsElapsed: input.monthsElapsed, accumulatedDepreciation: input.accumulatedDepreciation };
  switch (input.method) {
    case 'reducing_balance': return calculateReducingBalance(calcInput);
    case 'sum_of_years': return calculateSumOfYears(calcInput);
    case 'straight_line':
    default: return calculateStraightLine(calcInput);
  }
}

const VALID_DEPRECIATION_METHODS: DepreciationMethod[] = ['straight_line', 'reducing_balance', 'sum_of_years'];
const VALID_STATUSES: AssetStatus[] = ['available', 'assigned', 'in_maintenance', 'disposed', 'written_off'];
const VALID_DISPOSAL_METHODS: DisposalMethod[] = ['sale', 'scrap', 'write_off', 'donation', 'theft', 'insurance_claim'];

export function validateAsset(input: AssetInput): ValidationResult {
  const errors: Array<{ field: string; message: string }> = [];
  if (!input.name || input.name.trim() === '') errors.push({ field: 'name', message: 'Asset name is required' });
  if (input.cost === undefined || input.cost === null || input.cost <= 0) errors.push({ field: 'cost', message: 'Cost must be greater than zero' });
  if (input.salvageValue !== undefined && input.salvageValue > input.cost) errors.push({ field: 'salvageValue', message: 'Salvage value cannot exceed cost' });
  if (!input.usefulLifeYears || input.usefulLifeYears <= 0) errors.push({ field: 'usefulLifeYears', message: 'Useful life must be greater than zero' });
  if (input.depreciationMethod && !VALID_DEPRECIATION_METHODS.includes(input.depreciationMethod as DepreciationMethod)) errors.push({ field: 'depreciationMethod', message: 'Invalid depreciation method' });
  if (input.status && !VALID_STATUSES.includes(input.status as AssetStatus)) errors.push({ field: 'status', message: 'Invalid asset status' });
  if (input.purchaseDate) {
    const parsed = new Date(input.purchaseDate);
    if (isNaN(parsed.getTime())) { errors.push({ field: 'purchaseDate', message: 'Invalid date format' }); }
    else { const today = new Date(); today.setHours(23, 59, 59, 999); if (parsed > today) errors.push({ field: 'purchaseDate', message: 'Purchase date cannot be in the future' }); }
  }
  return { success: errors.length === 0, ...(errors.length > 0 ? { errors } : {}) };
}

export function validateDisposal(input: DisposalInput): ValidationResult {
  const errors: Array<{ field: string; message: string }> = [];
  if (!input.assetId || input.assetId.trim() === '') errors.push({ field: 'assetId', message: 'Asset ID is required' });
  if (input.disposalAmount < 0) errors.push({ field: 'disposalAmount', message: 'Disposal amount cannot be negative' });
  if (!input.reason || input.reason.trim() === '') errors.push({ field: 'reason', message: 'Disposal reason is required' });
  if (input.disposalMethod && !VALID_DISPOSAL_METHODS.includes(input.disposalMethod as DisposalMethod)) errors.push({ field: 'disposalMethod', message: 'Invalid disposal method' });
  if (input.disposalDate) { const parsed = new Date(input.disposalDate); if (isNaN(parsed.getTime())) errors.push({ field: 'disposalDate', message: 'Invalid date format' }); }
  return { success: errors.length === 0, ...(errors.length > 0 ? { errors } : {}) };
}

/**
 * Document Validation Service
 * Compares VLM-extracted data against entity records to detect discrepancies.
 */

import type {
  ExtractedDocument,
  ExtractedStatutoryDoc,
  ValidationDiscrepancy,
  DocumentValidationResult,
} from '@/modules/accounting/types/documentCapture.types';

// ---------------------------------------------------------------------------
// Invoice Validation
// ---------------------------------------------------------------------------

interface InvoiceRecord {
  invoiceNumber?: string;
  totalAmount?: number;
  vatAmount?: number;
  taxRate?: number;
  vendorName?: string;
  supplierName?: string;
  customerName?: string;
  clientName?: string;
  invoiceDate?: string;
}

export function validateInvoiceDocument(
  extracted: ExtractedDocument,
  invoice: InvoiceRecord,
): DocumentValidationResult {
  const discrepancies: ValidationDiscrepancy[] = [];

  // Total amount
  if (extracted.totalAmount !== null && invoice.totalAmount !== undefined) {
    const diff = Math.abs(extracted.totalAmount - invoice.totalAmount);
    if (diff > 0.02) {
      discrepancies.push({
        field: 'totalAmount',
        expected: invoice.totalAmount,
        actual: extracted.totalAmount,
        severity: diff > invoice.totalAmount * 0.05 ? 'error' : 'warning',
        message: `Total mismatch: document shows ${extracted.totalAmount}, record has ${invoice.totalAmount}`,
      });
    }
  }

  // VAT amount
  if (extracted.vatAmount !== null && invoice.vatAmount !== undefined) {
    const diff = Math.abs(extracted.vatAmount - invoice.vatAmount);
    if (diff > 1) {
      discrepancies.push({
        field: 'vatAmount',
        expected: invoice.vatAmount,
        actual: extracted.vatAmount,
        severity: 'warning',
        message: `VAT mismatch: document shows ${extracted.vatAmount}, record has ${invoice.vatAmount}`,
      });
    }
  }

  // VAT arithmetic check
  if (extracted.subtotal !== null && extracted.vatAmount !== null && extracted.totalAmount !== null) {
    const expected = Math.round((extracted.subtotal + extracted.vatAmount) * 100) / 100;
    if (Math.abs(expected - extracted.totalAmount) > 0.02) {
      discrepancies.push({
        field: 'vatArithmetic',
        expected: expected,
        actual: extracted.totalAmount,
        severity: 'error',
        message: `VAT arithmetic error on document: subtotal (${extracted.subtotal}) + VAT (${extracted.vatAmount}) = ${expected}, but total shows ${extracted.totalAmount}`,
      });
    }
  }

  // Reference number
  if (extracted.referenceNumber && invoice.invoiceNumber) {
    const normExtracted = extracted.referenceNumber.replace(/[-\s/]/g, '').toLowerCase();
    const normInvoice = invoice.invoiceNumber.replace(/[-\s/]/g, '').toLowerCase();
    if (normExtracted !== normInvoice) {
      discrepancies.push({
        field: 'referenceNumber',
        expected: invoice.invoiceNumber,
        actual: extracted.referenceNumber,
        severity: 'warning',
        message: `Reference mismatch: document shows "${extracted.referenceNumber}", record has "${invoice.invoiceNumber}"`,
      });
    }
  }

  // Vendor/customer name (fuzzy check)
  const entityName = invoice.vendorName || invoice.supplierName || invoice.customerName || invoice.clientName;
  const extractedName = extracted.vendorName || extracted.customerName;
  if (entityName && extractedName) {
    const normEntity = entityName.toLowerCase().replace(/\b(pty|ltd|cc|inc)\b/gi, '').trim();
    const normExtracted = extractedName.toLowerCase().replace(/\b(pty|ltd|cc|inc)\b/gi, '').trim();
    if (!normExtracted.includes(normEntity) && !normEntity.includes(normExtracted)) {
      discrepancies.push({
        field: 'entityName',
        expected: entityName,
        actual: extractedName,
        severity: 'warning',
        message: `Name mismatch: document shows "${extractedName}", record has "${entityName}"`,
      });
    }
  }

  // Date check
  if (extracted.date && invoice.invoiceDate) {
    if (extracted.date !== invoice.invoiceDate) {
      discrepancies.push({
        field: 'date',
        expected: invoice.invoiceDate,
        actual: extracted.date,
        severity: 'info',
        message: `Date differs: document shows ${extracted.date}, record has ${invoice.invoiceDate}`,
      });
    }
  }

  const errorCount = discrepancies.filter(d => d.severity === 'error').length;
  const warningCount = discrepancies.filter(d => d.severity === 'warning').length;
  const score = Math.max(0, 1 - (errorCount * 0.3 + warningCount * 0.1));

  return {
    valid: errorCount === 0,
    score: Math.round(score * 100) / 100,
    discrepancies,
    validatedAt: new Date().toISOString(),
  };
}

// ---------------------------------------------------------------------------
// Payment Receipt Validation
// ---------------------------------------------------------------------------

interface PaymentRecord {
  totalAmount?: number;
  paymentDate?: string;
  reference?: string;
  bankReference?: string;
}

export function validatePaymentReceipt(
  extracted: ExtractedDocument,
  payment: PaymentRecord,
): DocumentValidationResult {
  const discrepancies: ValidationDiscrepancy[] = [];

  if (extracted.totalAmount !== null && payment.totalAmount !== undefined) {
    const diff = Math.abs(extracted.totalAmount - payment.totalAmount);
    if (diff > 0.02) {
      discrepancies.push({
        field: 'totalAmount',
        expected: payment.totalAmount,
        actual: extracted.totalAmount,
        severity: diff > payment.totalAmount * 0.01 ? 'error' : 'warning',
        message: `Amount mismatch: receipt shows ${extracted.totalAmount}, payment record has ${payment.totalAmount}`,
      });
    }
  }

  if (extracted.date && payment.paymentDate) {
    const docDate = new Date(extracted.date);
    const payDate = new Date(payment.paymentDate);
    const daysDiff = Math.abs((docDate.getTime() - payDate.getTime()) / (1000 * 60 * 60 * 24));
    if (daysDiff > 7) {
      discrepancies.push({
        field: 'date',
        expected: payment.paymentDate,
        actual: extracted.date,
        severity: 'warning',
        message: `Date differs by ${Math.round(daysDiff)} days: receipt ${extracted.date}, payment ${payment.paymentDate}`,
      });
    }
  }

  const errorCount = discrepancies.filter(d => d.severity === 'error').length;
  const score = Math.max(0, 1 - (errorCount * 0.3 + (discrepancies.length - errorCount) * 0.1));

  return {
    valid: errorCount === 0,
    score: Math.round(score * 100) / 100,
    discrepancies,
    validatedAt: new Date().toISOString(),
  };
}

// ---------------------------------------------------------------------------
// Statutory Compliance Validation
// ---------------------------------------------------------------------------

interface CompanyRecord {
  companyName?: string;
  registrationNumber?: string;
  vatNumber?: string;
}

export function validateStatutoryCompliance(
  extracted: ExtractedStatutoryDoc,
  company: CompanyRecord,
): DocumentValidationResult {
  const discrepancies: ValidationDiscrepancy[] = [];

  if (extracted.entityName && company.companyName) {
    const normExtracted = extracted.entityName.toLowerCase().replace(/\b(pty|ltd|cc|inc)\b/gi, '').trim();
    const normCompany = company.companyName.toLowerCase().replace(/\b(pty|ltd|cc|inc)\b/gi, '').trim();
    if (!normExtracted.includes(normCompany) && !normCompany.includes(normExtracted)) {
      discrepancies.push({
        field: 'entityName',
        expected: company.companyName,
        actual: extracted.entityName,
        severity: 'error',
        message: `Entity name mismatch: certificate shows "${extracted.entityName}", company is "${company.companyName}"`,
      });
    }
  }

  if (extracted.expiryDate) {
    const expiry = new Date(extracted.expiryDate);
    const now = new Date();
    if (expiry < now) {
      discrepancies.push({
        field: 'expiryDate',
        expected: 'valid (not expired)',
        actual: extracted.expiryDate,
        severity: 'error',
        message: `Certificate expired on ${extracted.expiryDate}`,
      });
    } else {
      const daysUntil = Math.ceil((expiry.getTime() - now.getTime()) / (1000 * 60 * 60 * 24));
      if (daysUntil < 30) {
        discrepancies.push({
          field: 'expiryDate',
          expected: 'valid for >30 days',
          actual: `${daysUntil} days remaining`,
          severity: 'warning',
          message: `Certificate expires in ${daysUntil} days (${extracted.expiryDate})`,
        });
      }
    }
  }

  if (extracted.vatNumber && company.vatNumber && extracted.vatNumber !== company.vatNumber) {
    discrepancies.push({
      field: 'vatNumber',
      expected: company.vatNumber,
      actual: extracted.vatNumber,
      severity: 'error',
      message: `VAT number mismatch: certificate shows ${extracted.vatNumber}, company has ${company.vatNumber}`,
    });
  }

  const errorCount = discrepancies.filter(d => d.severity === 'error').length;
  const score = Math.max(0, 1 - (errorCount * 0.3 + (discrepancies.length - errorCount) * 0.1));

  return {
    valid: errorCount === 0,
    score: Math.round(score * 100) / 100,
    discrepancies,
    validatedAt: new Date().toISOString(),
  };
}

/**
 * Leave Management Service — BCEA-compliant leave, termination, overtime
 * Pure business logic — no database dependencies.
 */

export type LeaveType = 'annual' | 'sick' | 'family_responsibility' | 'maternity' | 'unpaid' | 'study';

export interface LeaveApplicationInput {
  employeeId: string;
  leaveType: LeaveType | string;
  startDate: string;
  endDate: string;
  days: number;
  reason?: string;
  availableBalance: number;
}

export interface TerminationInput {
