// ═══════════════════════════════════════════════════════════════════════════
// SARS SOURCE CODES
// ═══════════════════════════════════════════════════════════════════════════

export const SARS_SOURCE_CODES: Record<string, { description: string; category: 'income' | 'deduction' | 'employer' }> = {
  '3601': { description: 'Gross salary/wages', category: 'income' },
  '3605': { description: 'Annual bonus', category: 'income' },
  '3701': { description: 'Commission', category: 'income' },
  '3702': { description: 'Travel allowance', category: 'income' },
  '3703': { description: 'Reimbursive travel allowance', category: 'income' },
  '3713': { description: 'Other allowances', category: 'income' },
  '3801': { description: 'Overtime payments', category: 'income' },
  '3802': { description: 'Lump sum payments', category: 'income' },
  '3810': { description: 'Leave pay', category: 'income' },
  '3815': { description: 'Restraint of trade', category: 'income' },
  '4001': { description: 'Pension fund contributions (employee)', category: 'deduction' },
  '4002': { description: 'Provident fund contributions (employee)', category: 'deduction' },
  '4003': { description: 'Medical aid contributions (employee)', category: 'deduction' },
  '4004': { description: 'Retirement annuity contributions', category: 'deduction' },
  '4005': { description: 'Donations (Section 18A)', category: 'deduction' },
  '4102': { description: 'PAYE (Pay As You Earn)', category: 'deduction' },
  '4141': { description: 'UIF contributions (employee)', category: 'deduction' },
  '4142': { description: 'UIF contributions (employer)', category: 'employer' },
  '4150': { description: 'SDL (Skills Development Levy)', category: 'employer' },
};

// ═══════════════════════════════════════════════════════════════════════════
// SOURCE CODE MAPPING
// ═══════════════════════════════════════════════════════════════════════════

const CODE_MAPPING: Array<{ code: string; field: keyof IRP5EmployeeData }> = [
  { code: '3601', field: 'grossSalary' },
  { code: '3701', field: 'commission' },
  { code: '3801', field: 'overtime' },
  { code: '3605', field: 'bonus' },
  { code: '3702', field: 'travelAllowance' },
  { code: '4001', field: 'pensionContribEmployee' },
  { code: '4003', field: 'medicalAidEmployee' },
  { code: '4004', field: 'retirementAnnuity' },
  { code: '4102', field: 'paye' },
  { code: '4141', field: 'uifEmployee' },
  { code: '4142', field: 'uifEmployer' },
  { code: '4150', field: 'sdl' },
];

export function calculateIRP5SourceCodes(data: IRP5EmployeeData): SourceCodeEntry[] {
  const entries: SourceCodeEntry[] = [];
  for (const mapping of CODE_MAPPING) {
    const amount = data[mapping.field];
    if (amount && amount > 0) {
      entries.push({
        code: mapping.code,
        description: SARS_SOURCE_CODES[mapping.code]?.description || '',
        amount: Math.round(amount * 100) / 100,
      });
    }
  }
  return entries;
}

// ═══════════════════════════════════════════════════════════════════════════
// IRP5 CERTIFICATE
// ═══════════════════════════════════════════════════════════════════════════

export function buildIRP5Certificate(input: {
  employeeData: IRP5EmployeeData;
  employeeName: string;
  idNumber: string;
  taxNumber: string;
  employerName: string;
  employerPayeRef: string;
  taxYear: number;
  periodStart: string;
  periodEnd: string;
}): IRP5Certificate {
  const sourceCodes = calculateIRP5SourceCodes(input.employeeData);

  const incomeCodes = sourceCodes.filter(sc => {
    const def = SARS_SOURCE_CODES[sc.code];
    return def?.category === 'income';
  });
  const deductionCodes = sourceCodes.filter(sc => {
    const def = SARS_SOURCE_CODES[sc.code];
    return def?.category === 'deduction';
  });

  const totalGrossIncome = Math.round(incomeCodes.reduce((s, c) => s + c.amount, 0) * 100) / 100;
  const totalDeductions = Math.round(deductionCodes.reduce((s, c) => s + c.amount, 0) * 100) / 100;

  return {
    employeeName: input.employeeName,
    idNumber: input.idNumber,
    taxNumber: input.taxNumber,
    employerName: input.employerName,
    employerPayeRef: input.employerPayeRef,
    taxYear: input.taxYear,
    periodStart: input.periodStart,
    periodEnd: input.periodEnd,
    sourceCodes,
    totalGrossIncome,
    totalDeductions,
    netRemuneration: Math.round((totalGrossIncome - totalDeductions) * 100) / 100,
  };
}

// ═══════════════════════════════════════════════════════════════════════════
// EMP501 SUMMARY
// ═══════════════════════════════════════════════════════════════════════════

export function buildEMP501Summary(monthlyData: EMP501MonthlyData[], taxYear: number): EMP501Summary {
  const totalPaye = Math.round(monthlyData.reduce((s, m) => s + m.paye, 0) * 100) / 100;
  const totalUif = Math.round(monthlyData.reduce((s, m) => s + m.uif, 0) * 100) / 100;
  const totalSdl = Math.round(monthlyData.reduce((s, m) => s + m.sdl, 0) * 100) / 100;
  const maxEmployees = monthlyData.length > 0 ? Math.max(...monthlyData.map(m => m.totalEmployees)) : 0;

  return {
    taxYear,
    totalPaye,
    totalUif,
    totalSdl,
    totalLiability: Math.round((totalPaye + totalUif + totalSdl) * 100) / 100,
    monthlyData,
    totalEmployees: maxEmployees,
  };
}

// ═══════════════════════════════════════════════════════════════════════════
// VALIDATION
// ═══════════════════════════════════════════════════════════════════════════

export function validateIRP5Data(input: {
  employeeName: string;
  idNumber: string;
  taxNumber: string;
  grossSalary: number;
  paye: number;
}): { valid: boolean; errors: string[] } {
  const errors: string[] = [];
  if (!input.employeeName || input.employeeName.trim() === '') errors.push('Employee name is required');
  if (!input.idNumber || input.idNumber.length !== 13 || !/^\d{13}$/.test(input.idNumber)) errors.push('Valid 13-digit SA ID number is required');
  if (input.grossSalary < 0) errors.push('Gross salary cannot be negative');
  return { valid: errors.length === 0, errors };
}

// ═══════════════════════════════════════════════════════════════════════════
// FORMATTING
// ═══════════════════════════════════════════════════════════════════════════

export function formatSARSAmount(amount: number): string {
  return String(Math.round(amount * 100));
}

/**
 * SARS e-Filing Service — Payload builders, validation, compliance calendar
 * Covers: VAT201, EMP201, EMP501, IRP6 (provisional), IT14
 * Pure business logic — no database dependencies.
 */

// ═══════════════════════════════════════════════════════════════════════════
// TYPES
// ═══════════════════════════════════════════════════════════════════════════

export interface VAT201Data {
  taxPeriod: string;
  vatNumber: string;
  companyName: string;
  outputVATStandard: number;
  outputVATZeroRated: number;
  outputVATExempt: number;
  inputVATCapitalGoods: number;
  inputVATOther: number;
  adjustments: number;
}

export interface EMP201Data {
  taxPeriod: string;
  payeReference: string;
  companyName: string;
  totalPAYE: number;
  totalUIF: number;
  totalSDL: number;
  employeeCount: number;
}

export interface IRP6Data {
  taxYear: number;
  period: 1 | 2;
  taxableIncome: number;
  taxCredits: number;
  previousPayments: number;
  companyName: string;
  taxNumber: string;
}

export interface ComplianceDeadline {
  taxType: string;
  dueDate: string;
  description: string;
  period: string;
}

export interface SARSPayload {
  taxType: string;
  taxPeriod?: string;
  taxYear?: number;
  fields: Array<{ code: string; label: string; value: string | number }>;
  [key: string]: unknown;
}

// ═══════════════════════════════════════════════════════════════════════════
// TAX TYPES
// ═══════════════════════════════════════════════════════════════════════════

export const SARS_TAX_TYPES = {
  VAT201: { name: 'VAT Return', frequency: 'monthly', description: 'Monthly/bi-monthly VAT return' },
  EMP201: { name: 'Monthly Employer Declaration', frequency: 'monthly', description: 'PAYE, UIF, SDL monthly declaration' },
  EMP501: { name: 'Employer Reconciliation', frequency: 'bi-annual', description: 'Bi-annual employer tax reconciliation' },
  IRP6: { name: 'Provisional Tax', frequency: 'bi-annual', description: 'Provisional tax payment (1st & 2nd)' },
  IT14: { name: 'Company Income Tax', frequency: 'annual', description: 'Annual company income tax return' },
} as const;

// ═══════════════════════════════════════════════════════════════════════════
// FORMATTING
// ═══════════════════════════════════════════════════════════════════════════

export function formatSARSDate(dateStr: string): string {
  return dateStr.replace(/-/g, '');
}

export function formatSARSCurrency(amount: number): string {
  return String(Math.round(amount * 100));
}

// ═══════════════════════════════════════════════════════════════════════════
// VAT201 PAYLOAD
// ═══════════════════════════════════════════════════════════════════════════

export function buildVAT201Payload(data: VAT201Data): SARSPayload & {
  totalOutputVAT: number; totalInputVAT: number; netVAT: number;
} {
  const totalOutputVAT = Math.round((data.outputVATStandard + data.outputVATZeroRated + data.outputVATExempt) * 100) / 100;
  const totalInputVAT = Math.round((data.inputVATCapitalGoods + data.inputVATOther) * 100) / 100;
  const netVAT = Math.round((totalOutputVAT - totalInputVAT + data.adjustments) * 100) / 100;

  return {
    taxType: 'VAT201',
    taxPeriod: data.taxPeriod,
    vatNumber: data.vatNumber,
    companyName: data.companyName,
    totalOutputVAT,
    totalInputVAT,
    netVAT,
    fields: [
      { code: 'F01', label: 'Output VAT - Standard Rate (15%)', value: data.outputVATStandard },
      { code: 'F02', label: 'Output VAT - Zero Rated', value: data.outputVATZeroRated },
      { code: 'F03', label: 'Output VAT - Exempt', value: data.outputVATExempt },
      { code: 'F10', label: 'Input VAT - Capital Goods', value: data.inputVATCapitalGoods },
      { code: 'F11', label: 'Input VAT - Other', value: data.inputVATOther },
      { code: 'F13', label: 'Adjustments', value: data.adjustments },
      { code: 'F14', label: 'Total Output VAT', value: totalOutputVAT },
      { code: 'F15', label: 'Total Input VAT', value: totalInputVAT },
      { code: 'F16', label: 'Net VAT', value: netVAT },
    ],
  };
}

// ═══════════════════════════════════════════════════════════════════════════
// EMP201 PAYLOAD
// ═══════════════════════════════════════════════════════════════════════════

export function buildEMP201Payload(data: EMP201Data): SARSPayload & {
  paye: number; uif: number; sdl: number; totalLiability: number; payeReference: string;
} {
  const totalLiability = Math.round((data.totalPAYE + data.totalUIF + data.totalSDL) * 100) / 100;

  return {
    taxType: 'EMP201',
    taxPeriod: data.taxPeriod,
    payeReference: data.payeReference,
    companyName: data.companyName,
    paye: data.totalPAYE,
    uif: data.totalUIF,
    sdl: data.totalSDL,
    totalLiability,
    employeeCount: data.employeeCount,
    fields: [
      { code: 'PAYE', label: 'Pay As You Earn', value: data.totalPAYE },
      { code: 'UIF', label: 'Unemployment Insurance Fund', value: data.totalUIF },
      { code: 'SDL', label: 'Skills Development Levy', value: data.totalSDL },
      { code: 'TOTAL', label: 'Total Liability', value: totalLiability },
      { code: 'EMP_COUNT', label: 'Number of Employees', value: data.employeeCount },
    ],
  };
}

// ═══════════════════════════════════════════════════════════════════════════
// IRP6 (PROVISIONAL TAX) PAYLOAD
// ═══════════════════════════════════════════════════════════════════════════

function calculateEstimatedTax(taxableIncome: number): number {
  // SA company tax rate: 27% (2024/2025 onwards)
  const COMPANY_TAX_RATE = 0.27;
  return Math.round(taxableIncome * COMPANY_TAX_RATE * 100) / 100;
}

export function buildIRP6Payload(data: IRP6Data): SARSPayload & {
  estimatedTax: number; amountDue: number; period: number; taxYear: number;
} {
  const annualTax = calculateEstimatedTax(data.taxableIncome);
  // 1st provisional = ~50% of estimated annual tax, 2nd = remainder
  const estimatedTax = data.period === 1
    ? Math.round(annualTax * 0.5 * 100) / 100
    : Math.round(annualTax * 100) / 100;

  const amountDue = Math.round((estimatedTax - data.taxCredits - data.previousPayments) * 100) / 100;

  return {
    taxType: 'IRP6',
    taxYear: data.taxYear,
    period: data.period,
    companyName: data.companyName,
    taxNumber: data.taxNumber,
    estimatedTax,
    amountDue,
    fields: [
      { code: 'TAXABLE_INCOME', label: 'Estimated Taxable Income', value: data.taxableIncome },
      { code: 'EST_TAX', label: 'Estimated Tax', value: estimatedTax },
      { code: 'CREDITS', label: 'Tax Credits', value: data.taxCredits },
      { code: 'PREV_PAYMENTS', label: 'Previous Payments', value: data.previousPayments },
      { code: 'AMOUNT_DUE', label: 'Amount Due', value: amountDue },
    ],
  };
}

// ═══════════════════════════════════════════════════════════════════════════
// VALIDATION
// ═══════════════════════════════════════════════════════════════════════════

export function validateSARSSubmission(input: {
  taxType: string;
  taxPeriod: string;
  vatNumber?: string;
  payeReference?: string;
}): { valid: boolean; errors: string[] } {
  const errors: string[] = [];

  if (!input.taxType || input.taxType.trim() === '') errors.push('Tax type is required');
  if (!input.taxPeriod || input.taxPeriod.trim() === '') errors.push('Tax period is required');

  if (input.taxType === 'VAT201' && input.vatNumber) {
    if (!/^4\d{9}$/.test(input.vatNumber)) errors.push('VAT number must be 10 digits starting with 4');
  }

  return { valid: errors.length === 0, errors };
}

// ═══════════════════════════════════════════════════════════════════════════
// COMPLIANCE CALENDAR
// ═══════════════════════════════════════════════════════════════════════════

export function calculateComplianceDeadlines(year: number): ComplianceDeadline[] {
  const deadlines: ComplianceDeadline[] = [];

  // EMP201 — monthly, due by 7th of following month
  for (let m = 1; m <= 12; m++) {
    const dueMonth = m === 12 ? 1 : m + 1;
    const dueYear = m === 12 ? year + 1 : year;
    deadlines.push({
      taxType: 'EMP201',
      dueDate: `${dueYear}-${String(dueMonth).padStart(2, '0')}-07`,
      description: `EMP201 for ${year}-${String(m).padStart(2, '0')}`,
      period: `${year}-${String(m).padStart(2, '0')}`,
    });
  }

  // VAT201 — monthly, due by 25th of following month (Category A)
  for (let m = 1; m <= 12; m++) {
    const dueMonth = m === 12 ? 1 : m + 1;
    const dueYear = m === 12 ? year + 1 : year;
    deadlines.push({
      taxType: 'VAT201',
      dueDate: `${dueYear}-${String(dueMonth).padStart(2, '0')}-25`,
      description: `VAT201 for ${year}-${String(m).padStart(2, '0')}`,
      period: `${year}-${String(m).padStart(2, '0')}`,
    });
  }

  // EMP501 — interim (October) and annual (May)
  deadlines.push({
    taxType: 'EMP501',
    dueDate: `${year}-10-31`,
    description: `EMP501 Interim Reconciliation (Mar-Aug ${year})`,
    period: `${year}-H1`,
  });
  deadlines.push({
    taxType: 'EMP501',
    dueDate: `${year + 1}-05-31`,
    description: `EMP501 Annual Reconciliation (Mar ${year}-Feb ${year + 1})`,
    period: `${year}-H2`,
  });

  // IRP6 — 1st provisional (end of August), 2nd provisional (end of February)
  deadlines.push({
    taxType: 'IRP6',
    dueDate: `${year}-08-31`,
    description: `1st Provisional Tax Payment (${year})`,
    period: `${year}-P1`,
  });
  deadlines.push({
    taxType: 'IRP6',
    dueDate: `${year + 1}-02-28`,
    description: `2nd Provisional Tax Payment (${year})`,
    period: `${year}-P2`,
  });

  return deadlines.sort((a, b) => a.dueDate.localeCompare(b.dueDate));
}

/**
 * Project Accounting & Job Costing Service
 * Profitability, WIP, time billing, validation.
 * Pure business logic — no database dependencies.
 */

export type BillingMethod = 'time_and_materials' | 'fixed_price' | 'milestone' | 'retainer';

export interface ProjectFinancials {
  totalRevenue: number;
  totalLabourCost: number;
  totalExpenses: number;
  totalMaterialCost: number;
}

export interface ProfitabilityResult {
  totalCost: number;
  grossProfit: number;
  profitMargin: number;
  labourPercent: number;
  expensePercent: number;
  materialPercent: number;
}

export interface WIPInput {
  totalCostsIncurred: number;
  totalBilled: number;
  budgetTotal: number;
  percentComplete: number;
}

export interface WIPResult {
  wipBalance: number;
  earnedRevenue: number;
  status: 'under_billed' | 'over_billed' | 'fully_billed';
}

export interface ProjectInput {
  name: string;
  clientId: string;
  startDate: string;
  endDate?: string;
  budgetAmount: number;
  billingMethod: BillingMethod | string;
  description?: string;
}

export interface TimeEntryInput {
  employeeId: string;
  projectId: string;
  taskId?: string;
  date: string;
  hours: number;
  description: string;
  billable: boolean;
  hourlyRate?: number;
}

export interface ValidationResult {
  success: boolean;
  errors?: Array<{ field: string; message: string }>;
}

const VALID_BILLING_METHODS: BillingMethod[] = ['time_and_materials', 'fixed_price', 'milestone', 'retainer'];

// ═══════════════════════════════════════════════════════════════════════════
// PROFITABILITY
// ═══════════════════════════════════════════════════════════════════════════

export function calculateProjectProfitability(input: ProjectFinancials): ProfitabilityResult {
  const totalCost = Math.round((input.totalLabourCost + input.totalExpenses + input.totalMaterialCost) * 100) / 100;
  const grossProfit = Math.round((input.totalRevenue - totalCost) * 100) / 100;
  const profitMargin = input.totalRevenue > 0 ? Math.round((grossProfit / input.totalRevenue) * 10000) / 100 : 0;

  const labourPercent = totalCost > 0 ? Math.round((input.totalLabourCost / totalCost) * 10000) / 100 : 0;
  const expensePercent = totalCost > 0 ? Math.round((input.totalExpenses / totalCost) * 10000) / 100 : 0;
  const materialPercent = totalCost > 0 ? Math.round((input.totalMaterialCost / totalCost) * 10000) / 100 : 0;

  return { totalCost, grossProfit, profitMargin, labourPercent, expensePercent, materialPercent };
}

// ═══════════════════════════════════════════════════════════════════════════
// WIP
// ═══════════════════════════════════════════════════════════════════════════

export function calculateWIP(input: WIPInput): WIPResult {
  const earnedRevenue = Math.round((input.budgetTotal * input.percentComplete / 100) * 100) / 100;
  const wipBalance = Math.round((input.totalCostsIncurred - input.totalBilled) * 100) / 100;

  let status: WIPResult['status'] = 'under_billed';
  if (wipBalance < 0) status = 'over_billed';
  else if (wipBalance === 0) status = 'fully_billed';

  return { wipBalance, earnedRevenue, status };
}

// ═══════════════════════════════════════════════════════════════════════════
// BILLING
// ═══════════════════════════════════════════════════════════════════════════

export function calculateBillableAmount(hours: number, hourlyRate: number): number {
  return Math.round(hours * hourlyRate * 100) / 100;
}

// ═══════════════════════════════════════════════════════════════════════════
// VALIDATION
// ═══════════════════════════════════════════════════════════════════════════

export function validateProject(input: ProjectInput): ValidationResult {
  const errors: Array<{ field: string; message: string }> = [];
  if (!input.name || input.name.trim() === '') errors.push({ field: 'name', message: 'Project name is required' });
  if (!input.clientId || input.clientId.trim() === '') errors.push({ field: 'clientId', message: 'Client is required' });
  if (input.budgetAmount < 0) errors.push({ field: 'budgetAmount', message: 'Budget cannot be negative' });
  if (input.billingMethod && !VALID_BILLING_METHODS.includes(input.billingMethod as BillingMethod)) errors.push({ field: 'billingMethod', message: 'Invalid billing method' });
  return { success: errors.length === 0, ...(errors.length > 0 ? { errors } : {}) };
}

export function validateTimeEntry(input: TimeEntryInput): ValidationResult {
  const errors: Array<{ field: string; message: string }> = [];
  if (!input.employeeId || input.employeeId.trim() === '') errors.push({ field: 'employeeId', message: 'Employee is required' });
  if (!input.projectId || input.projectId.trim() === '') errors.push({ field: 'projectId', message: 'Project is required' });
  if (!input.hours || input.hours <= 0) errors.push({ field: 'hours', message: 'Hours must be greater than zero' });
  if (input.hours > 24) errors.push({ field: 'hours', message: 'Hours cannot exceed 24 per day' });
  if (!input.description || input.description.trim() === '') errors.push({ field: 'description', message: 'Description is required' });
  return { success: errors.length === 0, ...(errors.length > 0 ? { errors } : {}) };
}

/**
 * Enhanced Document Extraction Service
 * Fills gaps: supplier matching, auto-invoice, field confidence, Claude vision fallback.
 * Pure business logic — no database dependencies.
 */

export interface ExtractedDocFields {
  vendorName: string;
  documentDate: string;
  referenceNumber: string;
  subtotal: number;
  vatAmount: number;
  totalAmount: number;
  vatRate?: number;
  lineItems: Array<{ description: string; quantity: number; unitPrice: number; total: number }>;
}

export interface SupplierMatch {
  supplierId: string;
  supplierName: string;
  confidence: number;
}

export interface AutoInvoiceData {
  supplierId: string;
  invoiceNumber: string;
  invoiceDate: string;
  totalAmount: number;
  taxAmount: number;
  taxRate: number;
  items: Array<{ description: string; quantity: number; unitPrice: number; total: number }>;
}

export interface FieldConfidence {
  vendorName: number;
  documentDate: number;
  referenceNumber: number;
  totalAmount: number;
  vatAmount: number;
  overall: number;
}

// ═══════════════════════════════════════════════════════════════════════════
// SUPPLIER FUZZY MATCHING
// ═══════════════════════════════════════════════════════════════════════════

const STRIP_SUFFIXES = /\s*\(?(pty|ltd|limited|inc|cc|soc|holdings|group|pty\s*ltd|proprietary)\)?\s*/gi;

function normalize(name: string): string {
  return name.toLowerCase().replace(STRIP_SUFFIXES, '').replace(/[^a-z0-9\s]/g, '').replace(/\s+/g, ' ').trim();
}

function similarity(a: string, b: string): number {
  if (a === b) return 1;
  if (!a || !b) return 0;

  // Check if one contains the other
  if (a.includes(b) || b.includes(a)) {
    const shorter = a.length < b.length ? a : b;
    const longer = a.length >= b.length ? a : b;
    return shorter.length / longer.length;
  }

  // Word overlap
  const wordsA = new Set(a.split(' '));
  const wordsB = new Set(b.split(' '));
  const intersection = [...wordsA].filter(w => wordsB.has(w));
  const union = new Set([...wordsA, ...wordsB]);
  return union.size > 0 ? intersection.length / union.size : 0;
}

export function fuzzyMatchSupplier(
  extractedName: string,
  suppliers: Array<{ id: string; name: string }>,
): SupplierMatch | null {
  if (!extractedName || extractedName.trim() === '') return null;

  const normalizedInput = normalize(extractedName);
  if (!normalizedInput) return null;

  let bestMatch: SupplierMatch | null = null;
  let bestScore = 0;

  for (const s of suppliers) {
    const normalizedSupplier = normalize(s.name);
    const score = similarity(normalizedInput, normalizedSupplier);

    if (score > bestScore && score >= 0.5) {
      bestScore = score;
      bestMatch = {
        supplierId: s.id,
        supplierName: s.name,
        confidence: Math.round(score * 100) / 100,
      };
    }
  }

  return bestMatch;
}

