/**
 * AI Financial Report Narrative Service
 * Generates management commentary, variance analysis, trend narratives.
 * Pure business logic — no database dependencies.
 */

export type NarrativeTone = 'professional' | 'simplified' | 'executive';

export interface ReportData {
  reportType: 'income_statement' | 'balance_sheet' | 'cash_flow' | 'budget_vs_actual';
  period: string;
  companyName: string;
  currentPeriod: { revenue: number; expenses: number; netProfit: number };
  priorPeriod?: { revenue: number; expenses: number; netProfit: number };
  budget?: { revenue: number; expenses: number; netProfit: number };
}

export interface NarrativeResult {
  summary: string;
  highlights: string[];
  concerns: string[];
  recommendations: string[];
}

export interface VarianceItem {
  account: string;
  actual: number;
  budget: number;
  isExpense: boolean;
}

export interface VarianceCommentary {
  account: string;
  varianceAmount: number;
  percentVariance: number;
  direction: 'favorable' | 'unfavorable' | 'on_budget';
  commentary: string;
}

export interface TrendPoint {
  period: string;
  value: number;
}

export interface TrendResult {
  direction: 'up' | 'down' | 'flat';
  changePercent: number;
  narrative: string;
}

// ═══════════════════════════════════════════════════════════════════════════
// CONTEXT FORMATTING
// ═══════════════════════════════════════════════════════════════════════════

const fmt = (n: number) => `R${Math.abs(n).toLocaleString('en-ZA', { minimumFractionDigits: 0, maximumFractionDigits: 0 })}`;

export function formatNarrativeContext(data: { revenue: number; expenses: number; netProfit: number }): string {
  return `Revenue: ${fmt(data.revenue)} | Expenses: ${fmt(data.expenses)} | Net Profit: ${fmt(data.netProfit)} | Profit Margin: ${data.revenue > 0 ? Math.round((data.netProfit / data.revenue) * 100) : 0}%`;
}

// ═══════════════════════════════════════════════════════════════════════════
// NARRATIVE PROMPT
// ═══════════════════════════════════════════════════════════════════════════

const REPORT_TYPE_LABELS: Record<string, string> = {
  income_statement: 'Income Statement (Profit & Loss)',
  balance_sheet: 'Balance Sheet',
  cash_flow: 'Cash Flow Statement',
  budget_vs_actual: 'Budget vs Actual Report',
};

export function buildNarrativePrompt(data: ReportData, tone: NarrativeTone): string {
  const reportLabel = REPORT_TYPE_LABELS[data.reportType] || data.reportType;

  let context = `Report: ${reportLabel}\nPeriod: ${data.period}\nCompany: ${data.companyName}\n\n`;
  context += `Current Period:\n  ${formatNarrativeContext(data.currentPeriod)}\n`;

  if (data.priorPeriod) {
    context += `\nPrior Period:\n  ${formatNarrativeContext(data.priorPeriod)}\n`;
    const revChange = data.priorPeriod.revenue > 0 ? Math.round(((data.currentPeriod.revenue - data.priorPeriod.revenue) / data.priorPeriod.revenue) * 100) : 0;
    context += `  Revenue Change: ${revChange}%\n`;
  }

  if (data.budget) {
    context += `\nBudget:\n  ${formatNarrativeContext(data.budget)}\n`;
    const revVar = data.budget.revenue > 0 ? Math.round(((data.currentPeriod.revenue - data.budget.revenue) / data.budget.revenue) * 100) : 0;
    context += `  Revenue vs Budget: ${revVar}%\n`;
  }

  return `You are a South African chartered accountant writing a ${tone} management report narrative.

${context}

Write a commentary for this ${reportLabel}. Tone: ${tone}.

Respond in JSON:
{"summary": "2-3 sentence overview", "highlights": ["positive point 1", "..."], "concerns": ["concern 1", "..."], "recommendations": ["action item 1", "..."]}

Rules:
- Use ZAR (South African Rand) for all amounts
- Be specific with numbers and percentages
- ${tone === 'simplified' ? 'Use simple language suitable for non-financial directors' : 'Use professional accounting terminology'}
- Focus on actionable insights`;
}

// ═══════════════════════════════════════════════════════════════════════════
// RESPONSE PARSING
// ═══════════════════════════════════════════════════════════════════════════

export function parseNarrativeResponse(response: string): NarrativeResult | null {
  if (!response || response.trim() === '') return null;

  // Try JSON
  try {
    let jsonStr = response;
    const jsonMatch = response.match(/```(?:json)?\s*\n?([\s\S]*?)\n?```/);
    if (jsonMatch) jsonStr = jsonMatch[1]!;
    else {
      const objMatch = response.match(/\{[\s\S]*"summary"[\s\S]*\}/);
      if (objMatch) jsonStr = objMatch[0];
    }

    const parsed = JSON.parse(jsonStr);
    if (parsed.summary) {
      return {
        summary: String(parsed.summary),
        highlights: Array.isArray(parsed.highlights) ? parsed.highlights.map(String) : [],
        concerns: Array.isArray(parsed.concerns) ? parsed.concerns.map(String) : [],
        recommendations: Array.isArray(parsed.recommendations) ? parsed.recommendations.map(String) : [],
      };
    }
  } catch { /* not JSON */ }

  // Plain text fallback — use first sentence as summary
  const sentences = response.split(/[.!?]+/).filter(s => s.trim().length > 10);
  if (sentences.length > 0) {
    return {
      summary: sentences.slice(0, 2).join('. ').trim() + '.',
      highlights: [],
      concerns: [],
      recommendations: [],
    };
  }

  return null;
}

// ═══════════════════════════════════════════════════════════════════════════
// VARIANCE COMMENTARY
// ═══════════════════════════════════════════════════════════════════════════

/**
 * AI-Enhanced Cash Flow Forecasting Service
 * Payment probability, seasonal patterns, scenarios, 13-week rolling forecast.
 * Pure business logic — no database dependencies.
 */

export interface PaymentHistory {
  totalInvoices: number;
  paidOnTime: number;
  paidLate: number;
  unpaid: number;
  avgDaysToPayment: number;
}

export interface PaymentScore {
  probability: number;
  rating: 'reliable' | 'moderate' | 'poor' | 'unknown';
  estimatedDays: number;
}

export interface SeasonalPattern {
  hasSeasonality: boolean;
  peakMonth: number;
  troughMonth: number;
  factors: number[];
}

export interface ForecastScenario {
  name: 'optimistic' | 'base' | 'pessimistic';
  points: Array<{ month: number; inflow: number; outflow: number; closingBalance: number }>;
  alerts: string[];
}

export interface WeeklyForecast {
  weeks: Array<{ week: number; inflow: number; outflow: number; closingBalance: number }>;
  alertWeeks: number[];
  lowestBalance: number;
  lowestWeek: number;
}

export interface ForecastNarrative {
  summary: string;
  risks: string[];
  actions: string[];
}

// ═══════════════════════════════════════════════════════════════════════════
// PAYMENT PROBABILITY
// ═══════════════════════════════════════════════════════════════════════════

export function scorePaymentProbability(history: PaymentHistory): PaymentScore {
  if (history.totalInvoices === 0) {
    return { probability: 0.5, rating: 'unknown', estimatedDays: 30 };
  }

  const onTimeRate = history.paidOnTime / history.totalInvoices;
  const unpaidRate = history.unpaid / history.totalInvoices;
  const lateRate = history.paidLate / history.totalInvoices;

  // Weighted score: on-time is good, unpaid is very bad, late is moderately bad
  let probability = onTimeRate * 0.7 + (1 - unpaidRate) * 0.2 + (1 - lateRate) * 0.1;
  probability = Math.round(Math.max(0, Math.min(1, probability)) * 100) / 100;

  let rating: PaymentScore['rating'] = 'moderate';
  if (probability >= 0.85) rating = 'reliable';
  else if (probability < 0.5) rating = 'poor';

  const estimatedDays = Math.max(1, Math.round(history.avgDaysToPayment || 30));

  return { probability, rating, estimatedDays };
}

// ═══════════════════════════════════════════════════════════════════════════
// SEASONAL PATTERN DETECTION
// ═══════════════════════════════════════════════════════════════════════════

export function detectSeasonalPattern(monthlyData: number[]): SeasonalPattern {
  if (monthlyData.length < 6) {
    return { hasSeasonality: false, peakMonth: 0, troughMonth: 0, factors: [] };
  }

  const avg = monthlyData.reduce((s, v) => s + v, 0) / monthlyData.length;
  if (avg === 0) return { hasSeasonality: false, peakMonth: 0, troughMonth: 0, factors: [] };

  const factors = monthlyData.map(v => Math.round((v / avg) * 100) / 100);

  // Detect seasonality: coefficient of variation > 15%
  const variance = monthlyData.reduce((s, v) => s + Math.pow(v - avg, 2), 0) / monthlyData.length;
  const stdDev = Math.sqrt(variance);
  const cv = stdDev / avg;

  const peakIdx = monthlyData.indexOf(Math.max(...monthlyData));
  const troughIdx = monthlyData.indexOf(Math.min(...monthlyData));

  return {
    hasSeasonality: cv > 0.15,
    peakMonth: peakIdx + 1,
    troughMonth: troughIdx + 1,
    factors: monthlyData.length >= 12 ? factors : [],
  };
}

// ═══════════════════════════════════════════════════════════════════════════
// SCENARIO MODELING
// ═══════════════════════════════════════════════════════════════════════════

const SCENARIO_MULTIPLIERS = {
  optimistic: { inflow: 1.15, outflow: 0.95 },
  base: { inflow: 1.0, outflow: 1.0 },
  pessimistic: { inflow: 0.8, outflow: 1.1 },
};

export function buildForecastScenario(
  scenario: 'optimistic' | 'base' | 'pessimistic',
  input: { baseRevenue: number; baseExpenses: number; cashBalance: number; months: number },
): ForecastScenario {
  const mult = SCENARIO_MULTIPLIERS[scenario];
  const points: ForecastScenario['points'] = [];
  const alerts: string[] = [];
  let balance = input.cashBalance;

  for (let m = 0; m < input.months; m++) {
    const inflow = Math.round(input.baseRevenue * mult.inflow * 100) / 100;
    const outflow = Math.round(input.baseExpenses * mult.outflow * 100) / 100;
    balance = Math.round((balance + inflow - outflow) * 100) / 100;

    points.push({ month: m + 1, inflow, outflow, closingBalance: balance });

    if (balance < 0) {
      alerts.push(`Cash shortfall of R${Math.abs(balance).toLocaleString()} projected in month ${m + 1} (${scenario} scenario)`);
    }
  }

  return { name: scenario, points, alerts };
}

// ═══════════════════════════════════════════════════════════════════════════
// 13-WEEK ROLLING FORECAST
// ═══════════════════════════════════════════════════════════════════════════

export function calculateWeeklyForecast(input: {
  openingBalance: number;
  weeklyInflow: number;
  weeklyOutflow: number;
  weeks: number;
  minimumBalance?: number;
}): WeeklyForecast {
  const weeks: WeeklyForecast['weeks'] = [];
  const alertWeeks: number[] = [];
  let balance = input.openingBalance;
  let lowestBalance = input.openingBalance;
  let lowestWeek = 0;
  const minBal = input.minimumBalance ?? 0;

  for (let w = 0; w < input.weeks; w++) {
    balance = Math.round((balance + input.weeklyInflow - input.weeklyOutflow) * 100) / 100;
    weeks.push({ week: w + 1, inflow: input.weeklyInflow, outflow: input.weeklyOutflow, closingBalance: balance });

    if (balance < lowestBalance) { lowestBalance = balance; lowestWeek = w + 1; }
    if (balance < minBal) alertWeeks.push(w + 1);
  }

  return { weeks, alertWeeks, lowestBalance, lowestWeek };
}

