/**
 * POST /api/auth/register
 * Creates a new user account with email + password.
 * Does NOT set an auth cookie — user must log in after registering.
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { serialize } from 'cookie';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { hashPassword, checkPasswordStrength } from '@/lib/auth';
import { sql, transaction } from '@/lib/neon';
import { log } from '@/lib/logger';
import { checkRateLimit } from '@/lib/rateLimit';
import { signToken } from '@/lib/auth/jwt';
import { createSession } from '@/lib/auth/session';
import { AUTH_COOKIE_NAME } from '@/lib/auth/middleware';
import type { AuthRole } from '@/lib/auth/types';
type Row = Record<string, unknown>;


async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method ?? 'unknown', ['POST']);
  }

  // Rate limit: 3 registrations per IP per 15 minutes
  const rawIp = Array.isArray(req.headers['x-forwarded-for'])
    ? req.headers['x-forwarded-for'][0]
    : req.headers['x-forwarded-for'] ?? req.socket.remoteAddress;
  const ip: string = rawIp ?? 'unknown';
  if (checkRateLimit(ip, { windowMs: 15 * 60 * 1000, maxRequests: 3 })) {
    return res.status(429).json({
      success: false,
      error: { code: 'RATE_LIMITED', message: 'Too many attempts. Please try again later.' },
    });
  }

  const { firstName, lastName, email, password, confirmPassword, inviteToken } = req.body as {
    firstName?: string;
    lastName?: string;
    email?: string;
    password?: string;
    confirmPassword?: string;
    inviteToken?: string;
  };

  // Validate all fields present
  if (!firstName || !lastName || !email || !password || !confirmPassword) {
    return apiResponse.badRequest(res, 'All fields are required');
  }

  // Validate email format
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!emailRegex.test(email)) {
    return apiResponse.badRequest(res, 'Please enter a valid email address');
  }

  // Validate passwords match
  if (password !== confirmPassword) {
    return apiResponse.badRequest(res, 'Passwords do not match');
  }

  // Check password strength
  const strength = checkPasswordStrength(password);
  if (!strength.isValid) {
    return apiResponse.badRequest(res, `Password too weak: ${strength.issues[0] || 'Please choose a stronger password'}`);
  }

  try {
    // Check email uniqueness
    const existing = (await sql`
      SELECT id FROM users WHERE LOWER(email) = LOWER(${email.trim()}) LIMIT 1
    `) as Row[];

    if (existing.length > 0) {
      return apiResponse.badRequest(res, 'An account with this email already exists');
    }

    // Hash password
    const hash = await hashPassword(password);

    // Insert user
    const rows = (await sql`
      INSERT INTO users (email, password_hash, first_name, last_name, role, permissions, is_active, onboarding_completed)
      VALUES (${email.toLowerCase().trim()}, ${hash}, ${firstName.trim()}, ${lastName.trim()}, 'viewer', '[]', true, false)
      RETURNING id, email
    `) as Row[];

    const user = rows[0]!;
    const userId = String(user.id);
    const normalizedEmail = (email as string).toLowerCase().trim();

    // Auto-accept pending invitations: by token (if provided) + by email match
    let invitationsAccepted = 0;

    // 1. Accept the specific invite by token (from invite link flow)
    if (inviteToken && typeof inviteToken === 'string') {
      const tokenInvites = (await sql`
        SELECT id, company_id, role
        FROM company_invitations
        WHERE token = ${inviteToken}
          AND accepted_at IS NULL
          AND expires_at > NOW()
        LIMIT 1
      `) as Row[];

      if (tokenInvites.length > 0) {
        await transaction((txSql) =>
          tokenInvites.flatMap((inv) => [
            txSql`
              INSERT INTO company_users (company_id, user_id, role, is_default)
              VALUES (${inv.company_id as string}::UUID, ${userId}::UUID, ${inv.role as string}, false)
              ON CONFLICT (company_id, user_id) DO NOTHING
            `,
            txSql`
              UPDATE company_invitations SET accepted_at = NOW() WHERE id = ${inv.id as string}::UUID
            `,
          ])
        );
        invitationsAccepted += tokenInvites.length;
      }
    }

    // 2. Also accept any other pending invitations matching by email
    const pendingInvitations = (await sql`
      SELECT id, company_id, role
      FROM company_invitations
      WHERE LOWER(email) = LOWER(${normalizedEmail})
        AND accepted_at IS NULL
        AND expires_at > NOW()
    `) as Row[];

    if (pendingInvitations.length > 0) {
      await transaction((txSql) =>
        pendingInvitations.flatMap((inv) => [
          txSql`
            INSERT INTO company_users (company_id, user_id, role, is_default)
            VALUES (${inv.company_id as string}::UUID, ${userId}::UUID, ${inv.role as string}, false)
            ON CONFLICT (company_id, user_id) DO NOTHING
          `,
          txSql`
            UPDATE company_invitations SET accepted_at = NOW() WHERE id = ${inv.id as string}::UUID
          `,
        ])
      );
      invitationsAccepted += pendingInvitations.length;
    }

    const onboardingCompleted = invitationsAccepted > 0;
    if (onboardingCompleted) {
      await sql`UPDATE users SET onboarding_completed = true WHERE id = ${userId}`;
      log.info('Onboarding skipped via invitation acceptance at registration', { userId, invitationsAccepted }, 'auth/register');
    }

    log.info('User registered', { userId, email: user.email as string, invitationsAccepted }, 'auth/register');

    // Auto-login: create session and set auth cookie
    const authUser = {
      id: userId,
      userId,
      email: normalizedEmail,
      firstName: firstName.trim(),
      lastName: lastName.trim(),
      name: `${firstName.trim()} ${lastName.trim()}`.trim(),
      role: 'viewer' as AuthRole,
      permissions: [] as string[],
      isActive: true,
    };

    const ipAddress = Array.isArray(req.headers['x-forwarded-for'])
      ? req.headers['x-forwarded-for'][0]
      : req.headers['x-forwarded-for'] ?? req.socket.remoteAddress;
    const userAgent = req.headers['user-agent'];

    const tempToken = await signToken(authUser, 'pending');
    const session = await createSession(authUser.id, tempToken, ipAddress, userAgent);
    const finalToken = await signToken(authUser, session.id);

    const crypto = await import('crypto');
    const finalHash = crypto.createHash('sha256').update(finalToken).digest('hex');
    await sql`
      UPDATE user_sessions SET token_hash = ${finalHash} WHERE id = ${Number(session.id)}
    `;

    const isProd = process.env.NODE_ENV === 'production';
    const cookies = [
      serialize(AUTH_COOKIE_NAME, finalToken, {
        httpOnly: true,
        secure: true,
        sameSite: 'lax',
        path: '/',
        maxAge: 8 * 60 * 60,
        ...(isProd ? { domain: '.isaflow.co.za' } : {}),
      }),
    ];
    if (onboardingCompleted) {
      const domainSuffix = isProd ? '; Domain=.isaflow.co.za' : '';
      cookies.push(`ff_onboarding_done=1; Path=/; Max-Age=${30 * 24 * 60 * 60}; SameSite=Lax${isProd ? '; Secure' : ''}${domainSuffix}`);
    }
    res.setHeader('Set-Cookie', cookies);

    return apiResponse.created(res, {
      userId,
      email: normalizedEmail,
      invitationsAccepted,
      autoLoggedIn: true,
    });
  } catch (err) {
    log.error('Registration error', err instanceof Error ? { message: err.message } : { err }, 'auth/register');
    return apiResponse.internalError(res, err);
  }
}

export default withErrorHandler(handler);

/**
 * POST /api/auth/login
 * Authenticates a user with email + password.
 * On success: signs a JWT, creates a DB session, sets an HttpOnly cookie.
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { serialize } from 'cookie';
import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { apiResponse } from '@/lib/apiResponse';
import { verifyPassword } from '@/lib/auth/password';
import { signToken } from '@/lib/auth/jwt';
import { createSession } from '@/lib/auth/session';
import { AUTH_COOKIE_NAME } from '@/lib/auth/middleware';
import type { AuthRole } from '@/lib/auth/types';
import { get2FAStatus, isTrustedDevice } from '@/modules/auth/services/twoFactorService';
import { checkRateLimit } from '@/lib/rateLimit';
import { withErrorHandler } from '@/lib/api-error-handler';
type Row = Record<string, unknown>;

// Real bcrypt hash of 'timing-safe-dummy' at cost 12, used for constant-time rejection.
const TIMING_SAFE_HASH = '$2a$12$K4GByFHHbpZQKxVKzPEfXOdQuGfe0gPISQEFMEfcrrKjAXBgmC.Xq';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method ?? 'unknown', ['POST']);
  }

  // Rate limit: 5 attempts per IP per 15 minutes
  // Use the last x-forwarded-for entry (proxy-appended) to prevent client IP spoofing.
  const ip: string = (() => {
    const forwarded = req.headers['x-forwarded-for'];
    if (forwarded) {
      const raw = Array.isArray(forwarded) ? forwarded[0] ?? '' : forwarded;
      const ips = raw.split(',').map((s: string) => s.trim());
      return ips[ips.length - 1] || req.socket.remoteAddress || 'unknown';
    }
    return req.socket.remoteAddress || 'unknown';
  })();
  if (checkRateLimit(ip, { windowMs: 15 * 60 * 1000, maxRequests: 5 })) {
    return res.status(429).json({
      success: false,
      error: { code: 'RATE_LIMITED', message: 'Too many attempts. Please try again later.' },
    });
  }

  const { email, password, deviceFingerprint } = req.body as {
    email?: string;
    password?: string;
    deviceFingerprint?: string;
  };

  if (!email || !password) {
    return apiResponse.badRequest(res, 'Email and password are required');
  }

  try {
    // Look up user by email
    const rows = (await sql`
      SELECT id, email, password_hash, first_name, last_name, role,
             is_active, permissions, profile_picture, department, onboarding_completed,
             failed_login_attempts, locked_until
      FROM users
      WHERE email = ${email.toLowerCase().trim()}
      LIMIT 1
    `) as Row[];

    const user = rows[0];

    if (!user) {
      // Constant-time failure — avoid timing attacks
      await verifyPassword(password, TIMING_SAFE_HASH);
      return res.status(401).json({
        success: false,
        error: { code: 'INVALID_CREDENTIALS', message: 'Invalid email or password' },
      });
    }

    if (!user.is_active) {
      return res.status(403).json({
        success: false,
        error: { code: 'ACCOUNT_INACTIVE', message: 'Account is disabled' },
      });
    }

    // Check account lockout
    if (user.locked_until) {
      const lockedUntil = user.locked_until instanceof Date ? user.locked_until : new Date(user.locked_until as string);
      if (lockedUntil > new Date()) {
        const minutesRemaining = Math.ceil((lockedUntil.getTime() - Date.now()) / 60000);
        return res.status(403).json({
          success: false,
          error: {
            code: 'ACCOUNT_LOCKED',
            message: `Account locked due to too many failed attempts. Try again in ${minutesRemaining} minute(s).`,
          },
        });
      }
    }

    // Verify password
    const passwordValid = await verifyPassword(password, user.password_hash as string);
    if (!passwordValid) {
      // Increment failed attempts; lock after 10 failures
      const attempts = ((user.failed_login_attempts as number) ?? 0) + 1;
      if (attempts >= 10) {
        await sql`
          UPDATE users
          SET failed_login_attempts = ${attempts},
              locked_until = NOW() + INTERVAL '30 minutes'
          WHERE id = ${user.id as string}
        `;
        log.warn('Account locked after failed attempts', { userId: user.id, attempts }, 'auth/login');
      } else {
        await sql`
          UPDATE users SET failed_login_attempts = ${attempts} WHERE id = ${user.id as string}
        `;
      }
      return res.status(401).json({
        success: false,
        error: { code: 'INVALID_CREDENTIALS', message: 'Invalid email or password' },
      });
    }

    // Check 2FA before creating a full session
    const twoFAStatus = await get2FAStatus(String(user.id));
    if (twoFAStatus.enabled) {
      // Check if device is already trusted
      const trusted = deviceFingerprint
        ? await isTrustedDevice(String(user.id), deviceFingerprint)
        : false;

      if (!trusted) {
        // Issue a short-lived temp token (5 min) — no DB session yet
        const tempAuthUser = {
          id: String(user.id),
          userId: String(user.id),
          email: user.email as string,
          firstName: (user.first_name as string) || '',
          lastName: (user.last_name as string) || '',
          name: '',
          role: user.role as AuthRole,
          permissions: [],
          isActive: true,
        };
        const tempToken = await signToken(tempAuthUser, '2fa-pending', '5m');
        log.info('2FA required — temp token issued', { userId: user.id }, 'auth/login');
        return res.status(200).json({
          success: true,
          data: { requiresTwoFactor: true, tempToken },
        });
      }
    }

    const firstName = (user.first_name as string) || '';
    const lastName = (user.last_name as string) || '';

    const authUser = {
      id: String(user.id),
      userId: String(user.id),
      email: user.email as string,
      firstName,
      lastName,
      name: `${firstName} ${lastName}`.trim() || (user.email as string),
      role: user.role as AuthRole,
      permissions: (user.permissions as string[]) || [],
      isActive: true,
      profilePicture: user.profile_picture as string | undefined,
      department: user.department as string | undefined,
    };

    // Sign JWT and create DB session — reuse the already-resolved safe IP
    const ipAddress = ip;
    const userAgent = req.headers['user-agent'];

    // Reset failed login attempts on successful password verification
    await sql`
      UPDATE users SET failed_login_attempts = 0, locked_until = NULL WHERE id = ${authUser.id}
    `;

    // Create session first, then sign token with the real sessionId
    // We pass a temporary token to createSession, then update the hash
    const tempToken = await signToken(authUser, 'pending');
    const session = await createSession(authUser.id, tempToken, ipAddress, userAgent);

    // Re-sign token with the real sessionId
    const finalToken = await signToken(authUser, session.id);

    // Update session with the hash of the final token
    const crypto = await import('crypto');
    const finalHash = crypto.createHash('sha256').update(finalToken).digest('hex');
    await sql`
      UPDATE user_sessions SET token_hash = ${finalHash} WHERE id = ${Number(session.id)}
    `;

    // Set HttpOnly cookie — 8h session, always secure
    const isProd = process.env.NODE_ENV === 'production';
    const authCookieString = serialize(AUTH_COOKIE_NAME, finalToken, {
      httpOnly: true,
      secure: true,
      sameSite: 'lax',
      path: '/',
      maxAge: 8 * 60 * 60, // 8 hours
      ...(isProd ? { domain: '.isaflow.co.za' } : {}),
    });

    // Auto-accept any pending company invitations for this email
    let invitationsAccepted = 0;
    let onboardingCompleted = !!user.onboarding_completed;

    const pendingInvitations = (await sql`
      SELECT id, company_id, role
      FROM company_invitations
      WHERE LOWER(email) = LOWER(${authUser.email})
        AND accepted_at IS NULL
        AND expires_at > NOW()
    `) as Row[];

    for (const inv of pendingInvitations) {
      await sql`
        INSERT INTO company_users (company_id, user_id, role, is_default)
        VALUES (${inv.company_id as string}::UUID, ${authUser.id}::UUID, ${inv.role as string}, false)
        ON CONFLICT (company_id, user_id) DO NOTHING
      `;
      await sql`
        UPDATE company_invitations SET accepted_at = NOW() WHERE id::TEXT = ${inv.id as string}
      `;
      invitationsAccepted++;
    }

    if (invitationsAccepted > 0 && !onboardingCompleted) {
      await sql`UPDATE users SET onboarding_completed = true WHERE id = ${authUser.id}`;
      onboardingCompleted = true;
      log.info('Onboarding skipped via invitation acceptance', { userId: authUser.id, invitationsAccepted }, 'auth/login');
    }

    // If user already belongs to a company, they're onboarded — fix stale DB flag
    if (!onboardingCompleted) {
      const companyCheck = (await sql`
        SELECT 1 FROM company_users WHERE user_id::TEXT = ${authUser.id} LIMIT 1
      `) as Row[];
      if (companyCheck.length > 0) {
        await sql`UPDATE users SET onboarding_completed = true WHERE id = ${authUser.id}`;
        onboardingCompleted = true;
        log.info('Onboarding auto-completed — user already has a company', { userId: authUser.id }, 'auth/login');
      }
    }

    // Auto-dismiss accounting tour for existing users (prevents tour on every login)
    if (onboardingCompleted) {
      await sql`
        INSERT INTO user_preferences (user_id, key, value, updated_at)
        VALUES (${authUser.id}, 'onboarding_tour_completed', 'true', NOW())
        ON CONFLICT (user_id, key) DO NOTHING
      `;
    }

    const cookies = [authCookieString];
    if (onboardingCompleted) {
      const domainSuffix = isProd ? '; Domain=.isaflow.co.za' : '';
      cookies.push(`ff_onboarding_done=1; Path=/; Max-Age=${30 * 24 * 60 * 60}; SameSite=Lax${isProd ? '; Secure' : ''}${domainSuffix}`);
    }
    res.setHeader('Set-Cookie', cookies);

    log.info('User logged in', { userId: authUser.id, email: authUser.email }, 'auth/login');

    return apiResponse.success(res, {
      user: { ...authUser, onboardingCompleted },
      invitationsAccepted,
    }, 'Login successful');
  } catch (err) {
    log.error('Login error', err instanceof Error ? { message: err.message } : { err }, 'auth/login');
    return apiResponse.internalError(res, err);
  }
}

export default withErrorHandler(handler);

/**
 * POST /api/auth/logout
 * Deletes the current user session from the database and clears the auth cookie.
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { serialize } from 'cookie';
import { log } from '@/lib/logger';
import { apiResponse } from '@/lib/apiResponse';
import { verifyToken } from '@/lib/auth/jwt';
import { deleteSession } from '@/lib/auth/session';
import { AUTH_COOKIE_NAME } from '@/lib/auth/middleware';
import { withErrorHandler } from '@/lib/api-error-handler';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method ?? 'unknown', ['POST']);
  }

  const token = req.cookies[AUTH_COOKIE_NAME];

  // Best-effort session deletion — don't fail if token is missing/invalid
  if (token) {
    try {
      const payload = await verifyToken(token);
      if (payload?.sessionId) {
        await deleteSession(payload.sessionId);
      }
    } catch (err) {
      log.warn('Failed to delete session during logout', { err }, 'auth/logout');
    }
  }

  // Clear the auth cookie and onboarding cookie on both domains
  const isProd = process.env.NODE_ENV === 'production';
  const secureSuffix = isProd ? '; Secure' : '';
  const clearOpts = {
    httpOnly: true,
    secure: isProd,
    sameSite: 'lax' as const,
    path: '/',
    maxAge: 0,
    expires: new Date(0),
  };
  res.setHeader('Set-Cookie', [
    // Clear auth cookie with .isaflow.co.za domain (for admin + app subdomains)
    serialize(AUTH_COOKIE_NAME, '', {
      ...clearOpts,
      ...(isProd ? { domain: '.isaflow.co.za' } : {}),
    }),
    // Clear auth cookie without domain (host-scoped, backward compat)
    serialize(AUTH_COOKIE_NAME, '', clearOpts),
    // Clear onboarding cookie with domain
    `ff_onboarding_done=; Path=/; Max-Age=0; SameSite=Lax${secureSuffix}${isProd ? '; Domain=.isaflow.co.za' : ''}`,
    // Clear onboarding cookie without domain (host-scoped)
    `ff_onboarding_done=; Path=/; Max-Age=0; SameSite=Lax${secureSuffix}`,
  ]);

  log.info('User logged out', {}, 'auth/logout');
  return apiResponse.success(res, null, 'Logged out successfully');
}

export default withErrorHandler(handler);

/**
 * POST /api/auth/2fa-verify
 * Verify TOTP code during login using a short-lived temp token.
 * Returns full auth token on success (mirrors login response).
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { serialize } from 'cookie';
import { sql } from '@/lib/neon';
import { apiResponse } from '@/lib/apiResponse';
import { verifyToken, signToken } from '@/lib/auth/jwt';
import { createSession } from '@/lib/auth/session';
import { AUTH_COOKIE_NAME } from '@/lib/auth/middleware';
import { verifyTOTPCode, addTrustedDevice } from '@/modules/auth/services/twoFactorService';
import { log } from '@/lib/logger';
import type { AuthRole } from '@/lib/auth/types';
import { createHash } from 'crypto';
import { checkRateLimit } from '@/lib/rateLimit';
import { withErrorHandler } from '@/lib/api-error-handler';
type Row = Record<string, unknown>;


async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method ?? 'unknown', ['POST']);
  }

  // Rate limit: 5 attempts per IP per 15 minutes
  const rawIp = Array.isArray(req.headers['x-forwarded-for'])
    ? req.headers['x-forwarded-for'][0]
    : req.headers['x-forwarded-for'] ?? req.socket.remoteAddress;
  const ip: string = rawIp ?? 'unknown';
  if (checkRateLimit(ip, { windowMs: 15 * 60 * 1000, maxRequests: 5 })) {
    return res.status(429).json({
      success: false,
      error: { code: 'RATE_LIMITED', message: 'Too many attempts. Please try again later.' },
    });
  }

  const {
    tempToken,
    code,
    trustDevice,
    deviceFingerprint,
    deviceName,
  } = req.body as {
    tempToken?: string;
    code?: string;
    trustDevice?: boolean;
    deviceFingerprint?: string;
    deviceName?: string;
  };

  if (!tempToken || !code) {
    return apiResponse.badRequest(res, 'tempToken and code are required');
  }

  try {
    // Verify the temp token
    const payload = await verifyToken(tempToken);
    if (!payload) {
      return res.status(401).json({
        success: false,
        error: { code: 'INVALID_TOKEN', message: 'Invalid or expired temp token' },
      });
    }

    // Temp tokens use sessionId = '2fa-pending'
    if (payload.sessionId !== '2fa-pending') {
      return res.status(401).json({
        success: false,
        error: { code: 'INVALID_TOKEN', message: 'Token is not a 2FA temp token' },
      });
    }

    const userId = payload.sub;

    // Look up the user
    const rows = (await sql`
      SELECT id, email, first_name, last_name, role,
             is_active, permissions, profile_picture, department, onboarding_completed
      FROM users
      WHERE id = ${userId} AND is_active = true
      LIMIT 1
    `) as Row[];

    const user = rows[0];
    if (!user) {
      return res.status(401).json({
        success: false,
        error: { code: 'USER_NOT_FOUND', message: 'User not found' },
      });
    }

    // Verify TOTP code
    const codeValid = await verifyTOTPCode(userId, code.trim());
    if (!codeValid) {
      return res.status(401).json({
        success: false,
        error: { code: 'INVALID_2FA_CODE', message: 'Invalid authentication code' },
      });
    }

    const firstName = (user.first_name as string) || '';
    const lastName = (user.last_name as string) || '';

    const authUser = {
      id: String(user.id),
      userId: String(user.id),
      email: user.email as string,
      firstName,
      lastName,
      name: `${firstName} ${lastName}`.trim() || (user.email as string),
      role: user.role as AuthRole,
      permissions: (user.permissions as string[]) || [],
      isActive: true,
      profilePicture: user.profile_picture as string | undefined,
      department: user.department as string | undefined,
    };

    // Create full session
    const ipAddress = Array.isArray(req.headers['x-forwarded-for'])
      ? req.headers['x-forwarded-for'][0]
      : req.headers['x-forwarded-for'] ?? req.socket.remoteAddress;
    const userAgent = req.headers['user-agent'];

    const pendingToken = await signToken(authUser, 'pending');
    const session = await createSession(authUser.id, pendingToken, ipAddress, userAgent);

    const finalToken = await signToken(authUser, session.id);
    const finalHash = createHash('sha256').update(finalToken).digest('hex');

    await sql`
      UPDATE user_sessions SET token_hash = ${finalHash} WHERE id = ${Number(session.id)}
    `;

    // Optionally trust device
    if (trustDevice && deviceFingerprint) {
      await addTrustedDevice(userId, deviceFingerprint, deviceName ?? 'Unknown Device');
    }

    let onboardingCompleted = !!user.onboarding_completed;

    // If user already belongs to a company, they're onboarded — fix stale DB flag
    if (!onboardingCompleted) {
      const companyCheck = (await sql`
        SELECT 1 FROM company_users WHERE user_id = ${userId}::UUID LIMIT 1
      `) as Record<string, unknown>[];
      if (companyCheck.length > 0) {
        await sql`UPDATE users SET onboarding_completed = true WHERE id = ${userId}`;
        onboardingCompleted = true;
      }
    }

    // Auto-dismiss accounting tour for existing users
    if (onboardingCompleted) {
      await sql`
        INSERT INTO user_preferences (user_id, key, value, updated_at)
        VALUES (${userId}, 'onboarding_tour_completed', 'true', NOW())
        ON CONFLICT (user_id, key) DO NOTHING
      `;
    }

    const isProd = process.env.NODE_ENV === 'production';
    const authCookieString = serialize(AUTH_COOKIE_NAME, finalToken, {
      httpOnly: true,
      secure: true,
      sameSite: 'lax',
      path: '/',
      maxAge: 8 * 60 * 60, // 8 hours
      ...(isProd ? { domain: '.isaflow.co.za' } : {}),
    });

    const cookies = [authCookieString];
    if (onboardingCompleted) {
      const domainSuffix = isProd ? '; Domain=.isaflow.co.za' : '';
      cookies.push(`ff_onboarding_done=1; Path=/; Max-Age=${30 * 24 * 60 * 60}; SameSite=Lax${isProd ? '; Secure' : ''}${domainSuffix}`);
    }
    res.setHeader('Set-Cookie', cookies);

    log.info('2FA verified — full session created', { userId }, 'api/auth/2fa-verify');

    return apiResponse.success(res, {
      user: { ...authUser, onboardingCompleted },
    }, 'Two-factor authentication verified');
  } catch (err) {
    log.error('2fa-verify error', err instanceof Error ? { message: err.message } : { err }, 'api/auth/2fa-verify');
    return apiResponse.internalError(res, err);
  }
}

export default withErrorHandler(handler);

/**
 * Bank Feeds — OAuth Callback
 * Handles the redirect from Stitch after user authorizes bank access.
 * Exchanges code for tokens, fetches accounts, creates connection.
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth, type AuthenticatedNextApiRequest } from '@/lib/auth';
import {
  exchangeCode, fetchStitchAccounts, createConnection,
} from '@/modules/accounting/services/bankFeedService';
import cookie from 'cookie';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method!, ['GET']);
  }

  const { code, state, error } = req.query;

  if (error) {
    // User cancelled or Stitch returned error
    return res.redirect('/accounting/bank-accounts?feed_error=' + encodeURIComponent(String(error)));
  }

  if (!code || !state) {
    return apiResponse.badRequest(res, 'Missing code or state parameter');
  }

  // Retrieve stored state + code verifier from cookie
  const cookies = cookie.parse(req.headers.cookie || '');
  const rawState = cookies.stitch_oauth_state;
  if (!rawState) {
    return apiResponse.badRequest(res, 'OAuth state cookie missing. Please try connecting again.');
  }

  let storedState: { state: string; codeVerifier: string };
  try {
    storedState = JSON.parse(decodeURIComponent(rawState));
  } catch {
    return apiResponse.badRequest(res, 'Invalid OAuth state');
  }

  if (storedState.state !== state) {
    return apiResponse.badRequest(res, 'OAuth state mismatch — possible CSRF attack');
  }

  const userId = (req as AuthenticatedNextApiRequest).user.id;

  // Exchange code for tokens
  const tokens = await exchangeCode(String(code), storedState.codeVerifier);

  // Fetch linked bank accounts
  const accounts = await fetchStitchAccounts(tokens.accessToken);

  // Clear the state cookie
  res.setHeader('Set-Cookie', `stitch_oauth_state=; Path=/; HttpOnly; Max-Age=0${process.env.NODE_ENV === 'production' ? '; Secure' : ''}`);

  // Store accounts info and redirect to bank accounts page with success
  // In a real flow, user would select which account to link.
  // For now, store the first account or return the list for selection.

  if (accounts.length === 0) {
    return res.redirect('/accounting/bank-accounts?feed_error=no_accounts');
  }

  // Return accounts for the user to select which to link
  // Store tokens temporarily in the session
  const bankAccountId = req.query.bankAccountId as string;
  if (bankAccountId) {
    // Direct link — create connection immediately
    const account = accounts[0]!;
    await createConnection({
      bankAccountId,
      externalAccountId: account.id,
      bankName: account.bankId,
      accountNumberMasked: account.accountNumber,
      branchCode: account.branchCode,
      accountType: account.accountType,
      accessToken: tokens.accessToken,
      refreshToken: tokens.refreshToken,
      expiresIn: tokens.expiresIn,
      createdBy: userId,
    });
    return res.redirect('/accounting/bank-accounts?feed_connected=true');
  }

  // Return accounts for selection — tokens are NOT returned to the client
  return apiResponse.success(res, { accounts });
}


export default withAuth(withErrorHandler(handler));

/**
 * POST /api/onboarding/complete
 * Marks onboarding as completed for the current user.
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth, type AuthenticatedNextApiRequest } from '@/lib/auth';
