/**
 * Bank Reconciliation Report Data API
 * GET /api/accounting/bank-reconciliation-report?bankAccountId=<uuid>
 *
 * Returns matched and unmatched transaction data alongside statement balances
 * for rendering the PDF reconciliation report on the client.
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import { sql } from '@/lib/neon';

// ─── Row types returned from DB ───────────────────────────────────────────────

type TxRow = {
  id: string;
  transaction_date: string | Date;
  description: string | null;
  reference: string | null;
  amount: string | number;
  journal_entry_number: string | null;
};

type BatchRow = {
  opening_balance: string | null;
  closing_balance: string | null;
  statement_date: string | Date;
};

type AccountRow = {
  account_name: string;
};

// ─── Helpers ──────────────────────────────────────────────────────────────────

function toDateStr(d: string | Date): string {
  if (d instanceof Date) return d.toISOString().split('T')[0] ?? '';
  return String(d).split('T')[0] ?? '';
}

async function fetchBankAccountName(companyId: string, bankAccountId: string): Promise<string> {
  const rows = (await sql`
    SELECT account_name
    FROM gl_accounts
    WHERE id = ${bankAccountId}::UUID AND company_id = ${companyId}
    LIMIT 1
  `) as AccountRow[];
  return rows[0]?.account_name ?? 'Unknown Account';
}

async function fetchLatestBatch(companyId: string, bankAccountId: string): Promise<BatchRow | null> {
  const rows = (await sql`
    SELECT opening_balance, closing_balance, statement_date
    FROM bank_import_batches
    WHERE bank_account_id = ${bankAccountId}::UUID AND company_id = ${companyId}::UUID
    ORDER BY created_at DESC
    LIMIT 1
  `) as BatchRow[];
  return rows[0] ?? null;
}

async function fetchMatchedTransactions(companyId: string, bankAccountId: string): Promise<TxRow[]> {
  return (await sql`
    SELECT
      bt.id,
      bt.transaction_date,
      bt.description,
      bt.reference,
      bt.amount,
      je.entry_number AS journal_entry_number
    FROM bank_transactions bt
    LEFT JOIN gl_journal_lines jl ON jl.id = bt.matched_journal_line_id
    LEFT JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
    WHERE bt.bank_account_id = ${bankAccountId}::UUID
      AND bt.status = 'matched'
      AND bt.company_id = ${companyId}
    ORDER BY bt.transaction_date
  `) as TxRow[];
}

async function fetchUnmatchedTransactions(companyId: string, bankAccountId: string): Promise<TxRow[]> {
  return (await sql`
    SELECT
      bt.id,
      bt.transaction_date,
      bt.description,
      bt.reference,
      bt.amount,
      NULL::TEXT AS journal_entry_number
    FROM bank_transactions bt
    WHERE bt.bank_account_id = ${bankAccountId}::UUID
      AND bt.status = 'imported'
      AND bt.company_id = ${companyId}
    ORDER BY bt.transaction_date
  `) as TxRow[];
}

// ─── Handler ──────────────────────────────────────────────────────────────────

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const { companyId } = req as CompanyApiRequest;

  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET']);
  }

  const { bankAccountId } = req.query;

  if (!bankAccountId || typeof bankAccountId !== 'string' || bankAccountId.trim() === '') {
    return apiResponse.badRequest(res, 'bankAccountId query parameter is required');
  }

  try {
    // Parallel fetch: account name, latest batch, matched and unmatched transactions
    const [bankAccountName, latestBatch, matchedRows, unmatchedRows] = await Promise.all([
      fetchBankAccountName(companyId, bankAccountId),
      fetchLatestBatch(companyId, bankAccountId),
      fetchMatchedTransactions(companyId, bankAccountId),
      fetchUnmatchedTransactions(companyId, bankAccountId),
    ]);

    const mapTx = (row: TxRow) => ({
      date: toDateStr(row.transaction_date),
      description: row.description ?? '',
      amount: Number(row.amount),
      reference: row.reference ?? undefined,
      journalRef: row.journal_entry_number ?? undefined,
    });

    return apiResponse.success(res, {
      bankAccountName,
      statementDate: latestBatch ? toDateStr(latestBatch.statement_date) : '',
      openingBalance:
        latestBatch?.opening_balance !== null && latestBatch?.opening_balance !== undefined
          ? Number(latestBatch.opening_balance)
          : null,
      closingBalance:
        latestBatch?.closing_balance !== null && latestBatch?.closing_balance !== undefined
          ? Number(latestBatch.closing_balance)
          : null,
      matchedTransactions: matchedRows.map(mapTx),
      unmatchedTransactions: unmatchedRows.map(mapTx),
    });
  } catch (err) {
    log.error('Failed to get bank reconciliation report data', { error: err }, 'accounting-api');
    return apiResponse.badRequest(res, 'Failed to get bank reconciliation report data');
  }
}


export default withCompany(withErrorHandler(handler));

/**
 * Bank Transaction → Fleet Cross-Module Linking API
 *
 * POST /api/accounting/bank-match-fleet
 *   Body: { bankTransactionId, fleetEntityType: 'fuel' | 'service', fleetEntityId }
 *
 * Links a bank transaction to either a fleet fuel transaction or a fleet
 * service history record, storing the reference on both sides and marking
 * the bank transaction as 'matched' when it was previously 'imported'.
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import { sql } from '@/lib/neon';

// ── Types ─────────────────────────────────────────────────────────────────────

type FleetEntityType = 'fuel' | 'service';

interface PostBody {
  bankTransactionId?: string;
  fleetEntityType?: FleetEntityType;
  fleetEntityId?: string;
}

// ── Handler ───────────────────────────────────────────────────────────────────

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method ?? 'UNKNOWN', ['POST']);
  }

  const { companyId } = req as CompanyApiRequest;
  const { bankTransactionId, fleetEntityType, fleetEntityId } = req.body as PostBody;

  // ── Validation ─────────────────────────────────────────────────────────────
  if (!bankTransactionId) return apiResponse.badRequest(res, 'bankTransactionId is required');
  if (!fleetEntityId) return apiResponse.badRequest(res, 'fleetEntityId is required');
  if (!fleetEntityType || !['fuel', 'service'].includes(fleetEntityType)) {
    return apiResponse.badRequest(res, "fleetEntityType must be 'fuel' or 'service'");
  }

  if (fleetEntityType === 'fuel') {
    // ── Fuel transaction link ──────────────────────────────────────────────
    await sql`
      UPDATE fleet_fuel_transactions
      SET bank_transaction_id = ${bankTransactionId}::UUID
      WHERE id = ${fleetEntityId}::UUID AND company_id = ${companyId}::UUID
    `;

    await sql`
      UPDATE bank_transactions
      SET
        linked_fleet_fuel_id = ${fleetEntityId}::UUID,
        status = CASE WHEN status = 'imported' THEN 'matched' ELSE status END,
        updated_at = NOW()
      WHERE id = ${bankTransactionId}::UUID AND company_id = ${companyId}
    `;

    log.info('Linked bank tx to fleet fuel', { bankTransactionId, fleetEntityId }, 'bank-match-fleet');
    return apiResponse.success(res, {
      linked: true,
      bankTransactionId,
      fleetEntityType: 'fuel',
      fleetEntityId,
    });
  }

  // ── Service history link ───────────────────────────────────────────────────
  await sql`
    UPDATE fleet_service_history
    SET bank_transaction_id = ${bankTransactionId}::UUID
    WHERE id = ${fleetEntityId}::UUID AND company_id = ${companyId}::UUID
  `;

  await sql`
    UPDATE bank_transactions
    SET
      linked_fleet_service_id = ${fleetEntityId}::UUID,
      status = CASE WHEN status = 'imported' THEN 'matched' ELSE status END,
      updated_at = NOW()
    WHERE id = ${bankTransactionId}::UUID AND company_id = ${companyId}
  `;

  log.info('Linked bank tx to fleet service', { bankTransactionId, fleetEntityId }, 'bank-match-fleet');
  return apiResponse.success(res, {
    linked: true,
    bankTransactionId,
    fleetEntityType: 'service',
    fleetEntityId,
  });
}


export default withCompany(withErrorHandler(handler));

/**
 * Bank Transaction → Asset Cross-Module Linking API
 *
 * POST /api/accounting/bank-match-asset
 *   Body: { bankTransactionId, assetId }
 *
 * Links a bank transaction to an asset record, storing the reference on
 * both sides and marking the bank transaction as 'matched' when it was
 * previously 'imported'.
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import { sql } from '@/lib/neon';

// ── Types ─────────────────────────────────────────────────────────────────────

interface PostBody {
  bankTransactionId?: string;
  assetId?: string;
}

// ── Handler ───────────────────────────────────────────────────────────────────

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method ?? 'UNKNOWN', ['POST']);
  }

  const { companyId } = req as CompanyApiRequest;
  const { bankTransactionId, assetId } = req.body as PostBody;

  // ── Validation ─────────────────────────────────────────────────────────────
  if (!bankTransactionId) return apiResponse.badRequest(res, 'bankTransactionId is required');
  if (!assetId) return apiResponse.badRequest(res, 'assetId is required');

  // ── Write reverse link on the asset ───────────────────────────────────────
  await sql`
    UPDATE assets
    SET bank_transaction_id = ${bankTransactionId}::UUID
    WHERE id = ${assetId}::UUID AND company_id = ${companyId}::UUID
  `;

  // ── Write forward link on the bank transaction ─────────────────────────────
  await sql`
    UPDATE bank_transactions
    SET
      linked_asset_id = ${assetId}::UUID,
      status = CASE WHEN status = 'imported' THEN 'matched' ELSE status END,
      updated_at = NOW()
    WHERE id = ${bankTransactionId}::UUID AND company_id = ${companyId}
  `;

  log.info('Linked bank tx to asset', { bankTransactionId, assetId }, 'bank-match-asset');

  return apiResponse.success(res, {
    linked: true,
    bankTransactionId,
    assetId,
  });
}


export default withCompany(withErrorHandler(handler));

/**
 * Bank Import Batches API
 * GET /api/accounting/bank-import-batches?bankAccountId=<uuid>
 * Returns the most recent import batches for a bank account, used by the
 * Statement Balance Widget to display opening/closing balances per statement.
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import { sql } from '@/lib/neon';

// 🟢 WORKING: Import batch row shape returned from DB
type ImportBatchRow = {
  id: string;
  bank_account_id: string;
  statement_date: string | Date;
  bank_format: string | null;
  opening_balance: string | null;
  closing_balance: string | null;
  transaction_count: string | number;
  created_at: string | Date;
};

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const { companyId } = req as CompanyApiRequest;

  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET']);
  }

  const { bankAccountId } = req.query;

  if (!bankAccountId || typeof bankAccountId !== 'string' || bankAccountId.trim() === '') {
    return apiResponse.badRequest(res, 'bankAccountId query parameter is required');
  }

  try {
    const rows = (await sql`
      SELECT
        id,
        bank_account_id,
        statement_date,
        bank_format,
        opening_balance,
        closing_balance,
        transaction_count,
        created_at
      FROM bank_import_batches
      WHERE bank_account_id = ${bankAccountId}::UUID
        AND company_id = ${companyId}::UUID
      ORDER BY created_at DESC
      LIMIT 20
    `) as ImportBatchRow[];

    const batches = rows.map(r => ({
      id: r.id,
      statementDate: r.statement_date instanceof Date
        ? r.statement_date.toISOString().split('T')[0]
        : String(r.statement_date).split('T')[0],
      bankFormat: r.bank_format ?? null,
      openingBalance: r.opening_balance !== null ? Number(r.opening_balance) : null,
      closingBalance: r.closing_balance !== null ? Number(r.closing_balance) : null,
      transactionCount: Number(r.transaction_count),
      createdAt: r.created_at instanceof Date
        ? r.created_at.toISOString()
        : String(r.created_at),
    }));

    return apiResponse.success(res, { batches });
  } catch (err) {
    log.error('Failed to get bank import batches', { error: err }, 'accounting-api');
    return apiResponse.success(res, { batches: [] });
  }
}


export default withCompany(withErrorHandler(handler));

