/**
 * Bank Feeds — Initiate Connection
 * GET — returns Stitch OAuth authorization URL
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { getAuthorizationUrl, isConfigured } from '@/modules/accounting/services/bankFeedService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method!, ['GET']);
  }

  if (!isConfigured()) {
    return apiResponse.badRequest(res, 'Bank feed integration not configured. Set STITCH_CLIENT_ID, STITCH_CLIENT_SECRET, and STITCH_REDIRECT_URI in environment.');
  }

  const { url, state, nonce, codeVerifier } = getAuthorizationUrl();

  // Store state + verifier in a secure cookie for the callback
  const stateData = JSON.stringify({ state, nonce, codeVerifier });
  res.setHeader('Set-Cookie', `stitch_oauth_state=${encodeURIComponent(stateData)}; Path=/; HttpOnly; SameSite=Lax; Max-Age=600${process.env.NODE_ENV === 'production' ? '; Secure' : ''}`);

  return apiResponse.success(res, { url });
}


export default withAuth(withErrorHandler(handler));

/**
 * Bank Feeds — OAuth Callback
 * Handles the redirect from Stitch after user authorizes bank access.
 * Exchanges code for tokens, fetches accounts, creates connection.
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth, type AuthenticatedNextApiRequest } from '@/lib/auth';
import {
  exchangeCode, fetchStitchAccounts, createConnection,
} from '@/modules/accounting/services/bankFeedService';
import cookie from 'cookie';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method!, ['GET']);
  }

  const { code, state, error } = req.query;

  if (error) {
    // User cancelled or Stitch returned error
    return res.redirect('/accounting/bank-accounts?feed_error=' + encodeURIComponent(String(error)));
  }

  if (!code || !state) {
    return apiResponse.badRequest(res, 'Missing code or state parameter');
  }

  // Retrieve stored state + code verifier from cookie
  const cookies = cookie.parse(req.headers.cookie || '');
  const rawState = cookies.stitch_oauth_state;
  if (!rawState) {
    return apiResponse.badRequest(res, 'OAuth state cookie missing. Please try connecting again.');
  }

  let storedState: { state: string; codeVerifier: string };
  try {
    storedState = JSON.parse(decodeURIComponent(rawState));
  } catch {
    return apiResponse.badRequest(res, 'Invalid OAuth state');
  }

  if (storedState.state !== state) {
    return apiResponse.badRequest(res, 'OAuth state mismatch — possible CSRF attack');
  }

  const userId = (req as AuthenticatedNextApiRequest).user.id;

  // Exchange code for tokens
  const tokens = await exchangeCode(String(code), storedState.codeVerifier);

  // Fetch linked bank accounts
  const accounts = await fetchStitchAccounts(tokens.accessToken);

  // Clear the state cookie
  res.setHeader('Set-Cookie', `stitch_oauth_state=; Path=/; HttpOnly; Max-Age=0${process.env.NODE_ENV === 'production' ? '; Secure' : ''}`);

  // Store accounts info and redirect to bank accounts page with success
  // In a real flow, user would select which account to link.
  // For now, store the first account or return the list for selection.

  if (accounts.length === 0) {
    return res.redirect('/accounting/bank-accounts?feed_error=no_accounts');
  }

  // Return accounts for the user to select which to link
  // Store tokens temporarily in the session
  const bankAccountId = req.query.bankAccountId as string;
  if (bankAccountId) {
    // Direct link — create connection immediately
    const account = accounts[0]!;
    await createConnection({
      bankAccountId,
      externalAccountId: account.id,
      bankName: account.bankId,
      accountNumberMasked: account.accountNumber,
      branchCode: account.branchCode,
      accountType: account.accountType,
      accessToken: tokens.accessToken,
      refreshToken: tokens.refreshToken,
      expiresIn: tokens.expiresIn,
      createdBy: userId,
    });
    return res.redirect('/accounting/bank-accounts?feed_connected=true');
  }

  // Return accounts for selection — tokens are NOT returned to the client
  return apiResponse.success(res, { accounts });
}


export default withAuth(withErrorHandler(handler));

/**
 * Bank Feed Connections API
 * GET  — list connections
 * POST — sync or disconnect a connection (create is handled by callback.ts OAuth flow)
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import {
  listConnections, disconnectConnection,
  syncTransactions, getSyncHistory, isConfigured,
} from '@/modules/accounting/services/bankFeedService';

async function handler(req: NextApiRequest, res: NextApiResponse) {

  if (req.method === 'GET') {
    if (req.query.action === 'status') {
      return apiResponse.success(res, { configured: isConfigured() });
    }

    if (req.query.action === 'history' && req.query.connectionId) {
      const history = await getSyncHistory(req.query.connectionId as string);
      return apiResponse.success(res, { items: history });
    }

    const connections = await listConnections();
    return apiResponse.success(res, { items: connections });
  }

  if (req.method === 'POST') {
    const { action } = req.body;

    // NOTE: The 'create' action (which previously accepted raw accessToken and
    // refreshToken from the client body) has been removed. Accepting OAuth tokens
    // from client-supplied body is a security anti-pattern — tokens must only
    // arrive via the server-side OAuth callback flow in:
    //   pages/api/bank-feeds/callback.ts
    // That handler validates the OAuth state, exchanges the code for tokens, and
    // calls createConnection() directly. Do not re-add a client-facing create path.

    if (action === 'sync') {
      const { connectionId } = req.body;
      if (!connectionId) return apiResponse.badRequest(res, 'connectionId required');
      const result = await syncTransactions(connectionId);
      return apiResponse.success(res, result);
    }

    if (action === 'disconnect') {
      const { connectionId } = req.body;
      if (!connectionId) return apiResponse.badRequest(res, 'connectionId required');
      await disconnectConnection(connectionId);
      return apiResponse.success(res, { disconnected: true });
    }

    return apiResponse.badRequest(res, 'Invalid action. Use: sync, disconnect');
  }

  return apiResponse.methodNotAllowed(res, req.method!, ['GET', 'POST']);
}


export default withAuth(withErrorHandler(handler));

/**
 * Feature Check API
 * GET /api/features/check?code=payroll
 * Customer-facing endpoint — not admin-only. Returns whether the current company
 * has access to a given feature flag. Used by the FeatureGate component.
 */

import type { NextApiResponse } from 'next';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { hasFeature } from '@/modules/admin/services/featureFlagService';

async function handler(req: CompanyApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET']);
  }

  const code = req.query.code as string | undefined;
  if (!code) return apiResponse.badRequest(res, 'code query param required');

  const enabled = await hasFeature(req.companyId, code);
  return apiResponse.success(res, { code, enabled });
}


export default withCompany(withErrorHandler(handler));

/**
 * Client Portal — Invoices API
 * GET — list invoices for the authenticated portal user's client
 * Requires signed portal session cookie (JWT)
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { getClientInvoices } from '@/modules/accounting/services/portalService';
import { jwtVerify } from 'jose';
import cookie from 'cookie';

const PORTAL_SECRET = new TextEncoder().encode(
  (() => { if (!process.env.JWT_SECRET) throw new Error('JWT_SECRET is required'); return process.env.JWT_SECRET + '-portal'; })()
);

async function getPortalSession(req: NextApiRequest): Promise<{ clientId: string } | null> {
  const cookies = cookie.parse(req.headers.cookie || '');
  const token = cookies.portal_session;
  if (!token) return null;
  try {
    const { payload } = await jwtVerify(token, PORTAL_SECRET);
    return { clientId: payload.clientId as string };
  } catch {
    return null;
  }
}

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method!, ['GET']);
  }

  const session = await getPortalSession(req);
  if (!session) {
    return apiResponse.unauthorized(res, 'Portal authentication required');
  }

  const clientId = req.query.clientId as string;
  if (!clientId) {
    return apiResponse.badRequest(res, 'clientId is required');
  }

  // Enforce tenant isolation — user can only access their own client data
  if (session.clientId !== clientId) {
    return apiResponse.forbidden(res, 'Access denied — clientId mismatch');
  }

  const invoices = await getClientInvoices(clientId);
  return apiResponse.success(res, { items: invoices });
}

export default withErrorHandler(handler);

/**
 * Client Portal — Statement API
 * GET — get client statement
 * Requires signed portal session cookie (JWT)
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { getClientStatement } from '@/modules/accounting/services/portalService';
import { jwtVerify } from 'jose';
import cookie from 'cookie';

const PORTAL_SECRET = new TextEncoder().encode(
  (() => { if (!process.env.JWT_SECRET) throw new Error('JWT_SECRET is required'); return process.env.JWT_SECRET + '-portal'; })()
);

async function getPortalSession(req: NextApiRequest): Promise<{ clientId: string } | null> {
  const cookies = cookie.parse(req.headers.cookie || '');
  const token = cookies.portal_session;
  if (!token) return null;
  try {
    const { payload } = await jwtVerify(token, PORTAL_SECRET);
    return { clientId: payload.clientId as string };
  } catch {
    return null;
  }
}

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method!, ['GET']);
  }

  const session = await getPortalSession(req);
  if (!session) {
    return apiResponse.unauthorized(res, 'Portal authentication required');
  }

  const clientId = req.query.clientId as string;
  if (!clientId) {
    return apiResponse.badRequest(res, 'clientId is required');
  }

  // Enforce tenant isolation
  if (session.clientId !== clientId) {
    return apiResponse.forbidden(res, 'Access denied — clientId mismatch');
  }

  const asOfDate = (req.query.asOf as string) || new Date().toISOString().slice(0, 10);
  const statement = await getClientStatement(clientId, asOfDate);
  return apiResponse.success(res, statement);
}

export default withErrorHandler(handler);

/**
 * Client Portal — Authentication API
 * POST — login with email/password, sets signed httpOnly session cookie
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { authenticatePortalUser } from '@/modules/accounting/services/portalService';
import { SignJWT } from 'jose';
import cookie from 'cookie';
import { checkRateLimit } from '@/lib/rateLimit';

const PORTAL_SECRET = new TextEncoder().encode(
  (() => { if (!process.env.JWT_SECRET) throw new Error('JWT_SECRET is required'); return process.env.JWT_SECRET + '-portal'; })()
);

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method!, ['POST']);
  }

  // Rate limit: 5 attempts per IP per 15 minutes
  const rawIp = Array.isArray(req.headers['x-forwarded-for'])
    ? req.headers['x-forwarded-for'][0]
    : req.headers['x-forwarded-for'] ?? req.socket.remoteAddress;
  const ip: string = rawIp ?? 'unknown';
  if (checkRateLimit(ip, { windowMs: 15 * 60 * 1000, maxRequests: 5 })) {
    return res.status(429).json({
      success: false,
      error: { code: 'RATE_LIMITED', message: 'Too many attempts. Please try again later.' },
    });
  }

  const { email, password } = req.body;
  if (!email || !password) {
    return apiResponse.badRequest(res, 'email and password are required');
  }

  const user = await authenticatePortalUser(email, password);
  if (!user) {
    return apiResponse.unauthorized(res, 'Invalid email or password');
  }

  // Sign a JWT for the portal session
  const token = await new SignJWT({ clientId: user.clientId, email: user.email })
    .setProtectedHeader({ alg: 'HS256' })
    .setExpirationTime('24h')
    .setIssuedAt()
    .sign(PORTAL_SECRET);

  // Set httpOnly signed cookie
  res.setHeader('Set-Cookie', cookie.serialize('portal_session', token, {
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'strict',
    path: '/',
    maxAge: 60 * 60 * 24, // 24 hours
  }));

  return apiResponse.success(res, { user });
}

export default withErrorHandler(handler);

/**
 * Client Portal — Payment Link API
 * GET  — get payment link details by token
 * POST — create a new payment link for an invoice
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { createPaymentLink, getPaymentLink } from '@/modules/accounting/services/portalService';
import { generatePayFastForm } from '@/modules/accounting/services/paymentGatewayService';
import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
type Row = Record<string, unknown>;


async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method === 'GET') {
    const token = req.query.token as string;
    if (!token) return apiResponse.badRequest(res, 'token is required');
    const link = await getPaymentLink(token);
    if (!link) return apiResponse.notFound(res, 'Payment link');

    // Enrich with invoice details and PayFast form data
    const enriched: Record<string, unknown> = { ...link };
    try {
      const invoiceRows = (await sql`
        SELECT ci.invoice_number, ci.due_date, ci.online_payment_enabled, ci.company_id,
               co.name AS company_name
        FROM customer_invoices ci
        LEFT JOIN companies co ON co.id = ci.company_id
        WHERE ci.id = ${link.invoiceId}::UUID
      `) as Row[];

      if (invoiceRows[0]) {
        enriched.invoiceNumber = invoiceRows[0].invoice_number;
        enriched.dueDate = invoiceRows[0].due_date;
        enriched.companyName = invoiceRows[0].company_name;

        // Generate PayFast form data if online payment is enabled
        if (invoiceRows[0].online_payment_enabled) {
          const appUrl = process.env.NEXT_PUBLIC_APP_URL || 'http://localhost:3101';
          const companyId = invoiceRows[0].company_id as string;
          try {
            const formData = await generatePayFastForm(
              companyId,
              link.invoiceId,
              `${appUrl}/portal/pay/${token}?payment_status=success`,
              `${appUrl}/portal/pay/${token}?payment_status=cancelled`,
              `${appUrl}/api/accounting/payment-gateway-itn`,
            );
            enriched.payfastFormData = formData;
          } catch (e) {
            log.error('Failed to generate PayFast form for portal', e instanceof Error ? { message: e.message } : { error: e }, 'PaymentLink');
          }
        }
      }
    } catch (e) {
      log.error('Failed to enrich payment link', e instanceof Error ? { message: e.message } : { error: e }, 'PaymentLink');
    }

    return apiResponse.success(res, enriched);
  }

  if (req.method === 'POST') {
    const { invoiceId, clientId, amount } = req.body;
    if (!invoiceId || !clientId || !amount) {
      return apiResponse.badRequest(res, 'invoiceId, clientId, and amount are required');
    }

    // Resolve the authenticated user's company
    const userId = (req as AuthenticatedNextApiRequest).user.id;
    const companyRows = (await sql`
      SELECT company_id FROM company_users
      WHERE user_id = ${userId}
      ORDER BY is_default DESC, created_at ASC
      LIMIT 1
    `) as Row[];
    if (companyRows.length === 0) {
      return apiResponse.badRequest(res, 'No company assigned to this user');
    }
    const companyId = companyRows[0]!.company_id as string;

    // Verify invoice belongs to this company
    const invoice = (await sql`
      SELECT id FROM customer_invoices
      WHERE id = ${invoiceId}::UUID AND company_id = ${companyId}::UUID
    `) as Row[];
    if (invoice.length === 0) return apiResponse.notFound(res, 'Invoice not found');

    const token = await createPaymentLink(invoiceId, clientId, Number(amount));
    return apiResponse.success(res, { token, url: `/portal/pay/${token}` });
  }

  return apiResponse.methodNotAllowed(res, req.method!, ['GET', 'POST']);
}


