 *   STITCH_CLIENT_SECRET — Stitch application secret
 *   STITCH_REDIRECT_URI  — OAuth callback URL
 */

// Types
export type {
  BankFeedConnection,
  StitchTransaction,
  StitchAccount,
  SyncResult,
} from './bankFeedConnectionService';

// Connection management
export {
  isConfigured,
  getAuthorizationUrl,
