/**
 * Group Chart of Accounts & COA Mapping Service
 * Manages group-level accounts and company-to-group account mappings.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

type Row = Record<string, unknown>;

export interface GroupAccount {
  id: string;
  groupId: string;
  accountCode: string;
  accountName: string;
  accountType: string;
  accountSubtype: string | null;
  parentAccountId: string | null;
  normalBalance: string;
  level: number;
  displayOrder: number;
  isActive: boolean;
  createdAt: string;
}

export interface CoaMapping {
  id: string;
  groupId: string;
  groupAccountId: string;
  groupAccountCode?: string;
  groupAccountName?: string;
  companyId: string;
  companyAccountId: string;
  companyAccountCode?: string;
  companyAccountName?: string;
  createdAt: string;
}

export function mapGroupAccount(r: Row): GroupAccount {
  return {
    id: String(r.id),
    groupId: String(r.group_id),
    accountCode: String(r.account_code),
    accountName: String(r.account_name),
    accountType: String(r.account_type),
    accountSubtype: r.account_subtype != null ? String(r.account_subtype) : null,
    parentAccountId: r.parent_account_id != null ? String(r.parent_account_id) : null,
    normalBalance: String(r.normal_balance),
    level: Number(r.level),
    displayOrder: Number(r.display_order),
    isActive: Boolean(r.is_active),
    createdAt: String(r.created_at),
  };
}

export function mapCoaMapping(r: Row): CoaMapping {
  return {
    id: String(r.id),
    groupId: String(r.group_id),
    groupAccountId: String(r.group_account_id),
    groupAccountCode: r.group_account_code != null ? String(r.group_account_code) : undefined,
    groupAccountName: r.group_account_name != null ? String(r.group_account_name) : undefined,
    companyId: String(r.company_id),
    companyAccountId: String(r.company_account_id),
    companyAccountCode: r.company_account_code != null ? String(r.company_account_code) : undefined,
    companyAccountName: r.company_account_name != null ? String(r.company_account_name) : undefined,
    createdAt: String(r.created_at),
  };
}

// ── Group Chart of Accounts ──────────────────────────────────────────────────

export async function getGroupAccounts(groupId: string): Promise<GroupAccount[]> {
  const rows = (await sql`
    SELECT * FROM group_accounts
    WHERE group_id = ${groupId}::UUID AND is_active = true
    ORDER BY display_order, account_code
  `) as Row[];
  return rows.map(mapGroupAccount);
}

export async function createGroupAccount(groupId: string, input: {
  accountCode: string;
  accountName: string;
  accountType: string;
  accountSubtype?: string;
  parentAccountId?: string;
  normalBalance?: string;
  level?: number;
  displayOrder?: number;
}): Promise<GroupAccount> {
  const rows = (await sql`
    INSERT INTO group_accounts (
      group_id, account_code, account_name, account_type, account_subtype,
      parent_account_id, normal_balance, level, display_order
    )
    VALUES (
      ${groupId}::UUID,
      ${input.accountCode},
      ${input.accountName},
      ${input.accountType},
      ${input.accountSubtype || null},
      ${input.parentAccountId || null},
      ${input.normalBalance || 'debit'},
      ${input.level ?? 1},
      ${input.displayOrder ?? 0}
    )
    RETURNING *
  `) as Row[];
  log.info('Group account created', { groupId, code: input.accountCode }, 'accounting');
  return mapGroupAccount(rows[0]!);
}

export async function updateGroupAccount(accountId: string, input: Partial<{
  accountCode: string;
  accountName: string;
  accountType: string;
  accountSubtype: string;
  parentAccountId: string;
  normalBalance: string;
  level: number;
  displayOrder: number;
}>): Promise<GroupAccount> {
  const rows = (await sql`
    UPDATE group_accounts SET
      account_code = COALESCE(${input.accountCode ?? null}, account_code),
      account_name = COALESCE(${input.accountName ?? null}, account_name),
      account_type = COALESCE(${input.accountType ?? null}, account_type),
      account_subtype = COALESCE(${input.accountSubtype ?? null}, account_subtype),
      parent_account_id = COALESCE(${input.parentAccountId ?? null}, parent_account_id),
      normal_balance = COALESCE(${input.normalBalance ?? null}, normal_balance),
      level = COALESCE(${input.level ?? null}, level),
      display_order = COALESCE(${input.displayOrder ?? null}, display_order)
    WHERE id = ${accountId}::UUID
    RETURNING *
  `) as Row[];
  if (!rows[0]) throw new Error(`Group account ${accountId} not found`);
  return mapGroupAccount(rows[0]!);
}

export async function deleteGroupAccount(accountId: string): Promise<void> {
  await sql`
    UPDATE group_accounts SET is_active = false
    WHERE id = ${accountId}::UUID
  `;
}

export async function autoGenerateGroupCOA(groupId: string, sourceCompanyId: string): Promise<number> {
  const rows = (await sql`
    INSERT INTO group_accounts (group_id, account_code, account_name, account_type, account_subtype, normal_balance, level, display_order)
    SELECT
      ${groupId}::UUID,
      a.account_code,
      a.account_name,
      a.account_type,
      a.account_subtype,
      a.normal_balance,
      COALESCE(a.level, 1),
      COALESCE(a.display_order, 0)
    FROM gl_accounts a
    WHERE a.company_id = ${sourceCompanyId}::UUID AND a.is_active = true
    ON CONFLICT (group_id, account_code) DO NOTHING
    RETURNING id
  `) as Row[];
  log.info('Group COA auto-generated', { groupId, sourceCompanyId, count: rows.length }, 'accounting');
  return rows.length;
}

// ── COA Mappings ─────────────────────────────────────────────────────────────

export async function getCoaMappings(groupId: string, companyId?: string): Promise<CoaMapping[]> {
  const rows = companyId
    ? (await sql`
        SELECT m.*,
               ga.account_code AS group_account_code, ga.account_name AS group_account_name,
               ca.account_code AS company_account_code, ca.account_name AS company_account_name
        FROM group_coa_mappings m
        JOIN group_accounts ga ON ga.id = m.group_account_id
        JOIN gl_accounts ca ON ca.id = m.company_account_id
        WHERE m.group_id = ${groupId}::UUID AND m.company_id = ${companyId}::UUID
        ORDER BY ga.account_code
      `) as Row[]
    : (await sql`
        SELECT m.*,
               ga.account_code AS group_account_code, ga.account_name AS group_account_name,
               ca.account_code AS company_account_code, ca.account_name AS company_account_name
        FROM group_coa_mappings m
        JOIN group_accounts ga ON ga.id = m.group_account_id
        JOIN gl_accounts ca ON ca.id = m.company_account_id
        WHERE m.group_id = ${groupId}::UUID
        ORDER BY m.company_id, ga.account_code
      `) as Row[];
  return rows.map(mapCoaMapping);
}

export async function setCoaMapping(
  groupId: string,
  companyId: string,
  companyAccountId: string,
  groupAccountId: string,
): Promise<CoaMapping> {
  const rows = (await sql`
    INSERT INTO group_coa_mappings (group_id, company_id, company_account_id, group_account_id)
    VALUES (${groupId}::UUID, ${companyId}::UUID, ${companyAccountId}::UUID, ${groupAccountId}::UUID)
    ON CONFLICT (group_id, company_id, company_account_id)
    DO UPDATE SET group_account_id = ${groupAccountId}::UUID
    RETURNING *
  `) as Row[];
  return mapCoaMapping(rows[0]!);
}

export async function removeCoaMapping(mappingId: string): Promise<void> {
  await sql`DELETE FROM group_coa_mappings WHERE id = ${mappingId}::UUID`;
}

export async function autoMapAccounts(groupId: string, companyId: string): Promise<number> {
  const rows = (await sql`
    INSERT INTO group_coa_mappings (group_id, company_id, company_account_id, group_account_id)
    SELECT
      ${groupId}::UUID,
      ${companyId}::UUID,
      ca.id,
      ga.id
    FROM gl_accounts ca
    JOIN group_accounts ga ON ga.group_id = ${groupId}::UUID AND ga.account_code = ca.account_code AND ga.is_active = true
    WHERE ca.company_id = ${companyId}::UUID AND ca.is_active = true
    ON CONFLICT (group_id, company_id, company_account_id) DO NOTHING
    RETURNING id
  `) as Row[];
  log.info('Auto-mapped accounts', { groupId, companyId, mapped: rows.length }, 'accounting');
  return rows.length;
}

export async function getUnmappedAccounts(groupId: string, companyId: string): Promise<{
  id: string;
  accountCode: string;
  accountName: string;
  accountType: string;
}[]> {
  const rows = (await sql`
    SELECT ca.id, ca.account_code, ca.account_name, ca.account_type
    FROM gl_accounts ca
    WHERE ca.company_id = ${companyId}::UUID
      AND ca.is_active = true
      AND NOT EXISTS (
        SELECT 1 FROM group_coa_mappings m
        WHERE m.group_id = ${groupId}::UUID
          AND m.company_id = ${companyId}::UUID
          AND m.company_account_id = ca.id
      )
    ORDER BY ca.account_code
  `) as Row[];
  return rows.map((r: Row) => ({
    id: String(r.id),
    accountCode: String(r.account_code),
    accountName: String(r.account_name),
    accountType: String(r.account_type),
  }));
}

/**
 * Company Groups API
 * GET    — list groups / get single group
 * POST   — create group / add member / manage COA
 * PUT    — update group / update member
 * DELETE — remove member / delete group
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { sql } from '@/lib/neon';
import {
  getGroup,
  createGroup,
  updateGroup,
  deleteGroup,
  addMember,
  updateMember,
  removeMember,
  getGroupMembers,
  getGroupAccounts,
  createGroupAccount,
  updateGroupAccount,
  deleteGroupAccount,
  autoGenerateGroupCOA,
  getCoaMappings,
  setCoaMapping,
  removeCoaMapping,
  autoMapAccounts,
  getUnmappedAccounts,
} from '@/modules/accounting/services/groupCompanyService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const userId = (req as AuthenticatedNextApiRequest).user.id;
  const action = (req.query.action || req.body?.action) as string | undefined;

  // Verify user belongs to at least one company in the group
  async function verifyGroupAccess(gId: string): Promise<boolean> {
    const rows = (await sql`
      SELECT 1 FROM company_group_members cgm
      JOIN company_users cu ON cu.company_id = cgm.company_id
      WHERE cgm.group_id = ${gId}::UUID AND cu.user_id = ${userId}::UUID
      LIMIT 1
    `) as Record<string, unknown>[];
    return rows.length > 0;
  }

  // ── GET ────────────────────────────────────────────────────────────────────
  if (req.method === 'GET') {
    const groupId = req.query.group_id as string | undefined;

    if (action === 'members' && groupId) {
      const members = await getGroupMembers(groupId);
      return apiResponse.success(res, { items: members });
    }

    if (action === 'accounts' && groupId) {
      const accounts = await getGroupAccounts(groupId);
      return apiResponse.success(res, { items: accounts });
    }

    if (action === 'mappings' && groupId) {
      const companyId = req.query.company_id as string | undefined;
      if (companyId) {
        const membership = await sql`SELECT 1 FROM company_users WHERE company_id = ${companyId}::UUID AND user_id = ${userId}::UUID LIMIT 1` as Record<string, unknown>[];
        if (!membership[0]) return apiResponse.forbidden(res, 'Access denied to the specified company');
      }
      const mappings = await getCoaMappings(groupId, companyId);
      return apiResponse.success(res, { items: mappings });
    }

    if (action === 'unmapped' && groupId) {
      const companyId = req.query.company_id as string;
      if (!companyId) return apiResponse.badRequest(res, 'company_id required');
      const membership = await sql`SELECT 1 FROM company_users WHERE company_id = ${companyId}::UUID AND user_id = ${userId}::UUID LIMIT 1` as Record<string, unknown>[];
      if (!membership[0]) return apiResponse.forbidden(res, 'Access denied to the specified company');
      const unmapped = await getUnmappedAccounts(groupId, companyId);
      return apiResponse.success(res, { items: unmapped });
    }

    if (groupId) {
      if (!(await verifyGroupAccess(groupId))) return apiResponse.forbidden(res, 'Access denied to this group');
      const group = await getGroup(groupId);
      if (!group) return apiResponse.notFound(res, 'Group');
      return apiResponse.success(res, group);
    }

    const groups = (await sql`
      SELECT cg.*, COUNT(cgm2.id) FILTER (WHERE cgm2.left_date IS NULL)::int AS member_count
      FROM company_groups cg
      JOIN company_group_members cgm ON cgm.group_id = cg.id
      JOIN company_users cu ON cu.company_id::TEXT = cgm.company_id::TEXT
      LEFT JOIN company_group_members cgm2 ON cgm2.group_id = cg.id
      WHERE cu.user_id::TEXT = ${userId} AND cg.is_active = true
      GROUP BY cg.id
      ORDER BY cg.name
    `) as Record<string, unknown>[];
    return apiResponse.success(res, { items: groups });
  }

  // ── POST ───────────────────────────────────────────────────────────────────
  if (req.method === 'POST') {
    if (action === 'add-member') {
      const { groupId, companyId, ownershipPct, consolidationMethod } = req.body;
      if (!groupId || !companyId) return apiResponse.badRequest(res, 'groupId and companyId required');
      if (!(await verifyGroupAccess(groupId))) return apiResponse.forbidden(res, 'Access denied to this group');
      const member = await addMember(groupId, companyId, {
        ownershipPct: ownershipPct ?? 100,
        consolidationMethod: consolidationMethod ?? 'full',
      });
      return apiResponse.success(res, member);
    }

    if (action === 'create-group-account') {
      const { groupId, accountCode, accountName, accountType, accountSubtype, parentAccountId, normalBalance, level, displayOrder } = req.body;
      if (!groupId || !accountCode || !accountName || !accountType) {
        return apiResponse.badRequest(res, 'groupId, accountCode, accountName, accountType required');
      }
      if (!(await verifyGroupAccess(groupId))) return apiResponse.forbidden(res, 'Access denied to this group');
      const account = await createGroupAccount(groupId, {
        accountCode, accountName, accountType, accountSubtype, parentAccountId, normalBalance, level, displayOrder,
      });
      return apiResponse.success(res, account);
    }

    if (action === 'auto-generate-coa') {
      const { groupId, sourceCompanyId } = req.body;
      if (!groupId || !sourceCompanyId) return apiResponse.badRequest(res, 'groupId and sourceCompanyId required');
      if (!(await verifyGroupAccess(groupId))) return apiResponse.forbidden(res, 'Access denied to this group');
      const count = await autoGenerateGroupCOA(groupId, sourceCompanyId);
      return apiResponse.success(res, { accountsCreated: count });
    }

    if (action === 'set-mapping') {
      const { groupId, companyId, companyAccountId, groupAccountId } = req.body;
      if (!groupId || !companyId || !companyAccountId || !groupAccountId) {
        return apiResponse.badRequest(res, 'groupId, companyId, companyAccountId, groupAccountId required');
      }
      if (!(await verifyGroupAccess(groupId))) return apiResponse.forbidden(res, 'Access denied to this group');
      const mapping = await setCoaMapping(groupId, companyId, companyAccountId, groupAccountId);
      return apiResponse.success(res, mapping);
    }

    if (action === 'auto-map') {
      const { groupId, companyId } = req.body;
      if (!groupId || !companyId) return apiResponse.badRequest(res, 'groupId and companyId required');
      if (!(await verifyGroupAccess(groupId))) return apiResponse.forbidden(res, 'Access denied to this group');
      const count = await autoMapAccounts(groupId, companyId);
      return apiResponse.success(res, { mappedCount: count });
    }

    // Default POST: create group
    const { name, holdingCompanyId, defaultCurrency, financialYearStart } = req.body;
    if (!name) return apiResponse.badRequest(res, 'name is required');
    const group = await createGroup({ name, holdingCompanyId, defaultCurrency, financialYearStart }, userId);
    return apiResponse.success(res, group);
  }

  // ── PUT ────────────────────────────────────────────────────────────────────
  if (req.method === 'PUT') {
    if (action === 'update-member') {
      const { memberId, groupId: memberGroupId, ownershipPct, consolidationMethod } = req.body;
      if (!memberId) return apiResponse.badRequest(res, 'memberId required');
      if (!memberGroupId) return apiResponse.badRequest(res, 'groupId required');
      if (!(await verifyGroupAccess(memberGroupId))) return apiResponse.forbidden(res, 'Access denied to this group');
      await updateMember(memberId, { ownershipPct, consolidationMethod });
      return apiResponse.success(res, { updated: true });
    }

    if (action === 'update-group-account') {
      const { accountId, groupId: accountGroupId, ...updates } = req.body;
      if (!accountId) return apiResponse.badRequest(res, 'accountId required');
      if (!accountGroupId) return apiResponse.badRequest(res, 'groupId required');
      if (!(await verifyGroupAccess(accountGroupId))) return apiResponse.forbidden(res, 'Access denied to this group');
      const account = await updateGroupAccount(accountId, updates);
      return apiResponse.success(res, account);
    }

    const { groupId, ...updates } = req.body;
    if (!groupId) return apiResponse.badRequest(res, 'groupId required');
    if (!(await verifyGroupAccess(groupId))) return apiResponse.forbidden(res, 'Access denied to this group');
    const group = await updateGroup(groupId, updates);
    return apiResponse.success(res, group);
  }

  // ── DELETE ─────────────────────────────────────────────────────────────────
  if (req.method === 'DELETE') {
    if (action === 'remove-member') {
      const memberId = req.query.member_id as string;
      const groupId = req.query.group_id as string;
      if (!memberId) return apiResponse.badRequest(res, 'member_id required');
      if (!groupId) return apiResponse.badRequest(res, 'group_id required');
      if (!(await verifyGroupAccess(groupId))) return apiResponse.forbidden(res, 'Access denied to this group');
      await removeMember(memberId);
      return apiResponse.success(res, { removed: true });
    }

    if (action === 'remove-mapping') {
      const mappingId = req.query.mapping_id as string;
      const groupId = req.query.group_id as string;
      if (!mappingId) return apiResponse.badRequest(res, 'mapping_id required');
      if (!groupId) return apiResponse.badRequest(res, 'group_id required');
      if (!(await verifyGroupAccess(groupId))) return apiResponse.forbidden(res, 'Access denied to this group');
      await removeCoaMapping(mappingId);
      return apiResponse.success(res, { removed: true });
    }

    if (action === 'delete-group-account') {
      const accountId = req.query.account_id as string;
      const groupId = req.query.group_id as string;
      if (!accountId) return apiResponse.badRequest(res, 'account_id required');
      if (!groupId) return apiResponse.badRequest(res, 'group_id required');
      if (!(await verifyGroupAccess(groupId))) return apiResponse.forbidden(res, 'Access denied to this group');
      await deleteGroupAccount(accountId);
      return apiResponse.success(res, { deleted: true });
    }

    const groupId = req.query.group_id as string;
    if (!groupId) return apiResponse.badRequest(res, 'group_id required');
    if (!(await verifyGroupAccess(groupId))) return apiResponse.forbidden(res, 'Access denied to this group');
    await deleteGroup(groupId);
    return apiResponse.success(res, { deleted: true });
  }

  return apiResponse.methodNotAllowed(res, req.method!, ['GET', 'POST', 'PUT', 'DELETE']);
}


export default withAuth(withErrorHandler(handler));

